package com.bigboldchat;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ChatXLLauncher {
	public static void main(String[] args) throws Exception {
		ExternalPluginManager.loadBuiltin(ChatXL.class);
		RuneLite.main(args);
	}
}

package com.bigboldchat.overlay;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;

import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/*
 * Transparent RuneLite overlay used as the movable handle for split private chat.
 */
public final class PrivateChatOverlay extends Overlay {
	private Rectangle naturalBounds;

	public PrivateChatOverlay() {
		setPriority(Overlay.PRIORITY_HIGHEST);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPosition(OverlayPosition.DYNAMIC);
		setMovable(true);
		setSnappable(true);
	}

	@Override
	public String getName() {
		return "CHATXL_SPLIT_PM";
	}

	@Override
	public Dimension render(Graphics2D graphics) {
		if (naturalBounds == null || naturalBounds.isEmpty()) {
			return null;
		}

		/*
		 * The drag surface represents the PM layout rectangle, not the union of
		 * text-widget widths. This keeps horizontal Alt-drag usable even when a
		 * stale or malformed row temporarily extends beyond the effective width.
		 */
		if (!isManuallyPositioned()) {
			getBounds().setLocation(naturalBounds.x, naturalBounds.y);
		}

		return new Dimension(naturalBounds.width, naturalBounds.height);
	}

	public boolean isManuallyPositioned() {
		return getPreferredLocation() != null || getPreferredPosition() != null;
	}

	public void setNaturalBounds(Rectangle bounds) {
		naturalBounds = bounds == null
				? null
				: new Rectangle(bounds);
	}
}

package com.bigboldchat;

import com.bigboldchat.chat.FontLayoutService;
import com.bigboldchat.chat.FontMeasurementService;
import com.bigboldchat.chatbox.ChatRebuildCoordinator;
import com.bigboldchat.chatbox.ChatboxResizeService;
import com.bigboldchat.config.ChatboxConfigHandler;
import com.bigboldchat.config.FontConfigHandler;
import com.bigboldchat.debug.DebugManager;
import com.bigboldchat.debug.PerformanceMetrics;
import com.bigboldchat.input.ChatboxHotkey;
import com.bigboldchat.layout.PrivateChatLayout;
import com.bigboldchat.overlay.PrivateChatOverlay;

import com.google.inject.Provides;

import javax.inject.Inject;

import lombok.extern.slf4j.Slf4j;

import net.runelite.api.ChatLineBuffer;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MessageNode;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.CanvasSizeChanged;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
		name = "Chat XL",
		description = "Resize the chatbox and its text for improved readability.<br>"
				+ "[A.K.A. BBC - Big Bold Chat]",
		conflicts = {"Chat Resizer", "Resizable Chat"},
		tags = {"1877", "accessibility", "bbc", "big", "bigger", "bold", "chat", "chatbox", "classic", "fixed", "font", "fonts", "large", "magnifier", "magnify", "messages", "modern", "pm", "private", "readability", "resizable", "resize", "resizer", "resizing", "scale", "size", "small", "text", "zoom"},
		enabledByDefault = true
)
public class ChatXL extends Plugin {

	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private Configurations config;
	@Inject
	private ConfigManager configManager;
	@Inject
	private DebugManager debugManager;
	@Inject
	private KeyManager keyManager;
	@Inject
	private OverlayManager overlayManager;

	/*
	 * Diagnostics & performance.
	 */
	private PerformanceMetrics performanceMetrics;

	/*
	 * Production services.
	 */
	private FontMeasurementService fontMeasurementService;
	private FontLayoutService fontLayoutService;
	private ChatboxResizeService chatboxResizeService;
	private ChatRebuildCoordinator chatRebuildCoordinator;
	private ChatboxHotkey chatboxHotkey;
	private PrivateChatOverlay privateChatOverlay;
	private PrivateChatLayout privateChatLayout;

	/*
	 * Configuration handlers.
	 */
	private ChatboxConfigHandler chatboxConfigHandler;
	private FontConfigHandler fontConfigHandler;

	/**
	 * ================================================================
	 * START-UP & SHUT-DOWN
	 * ================================================================
	 */
	@Override
	protected void startUp() {
		performanceMetrics = debugManager.activate();
		chatboxResizeService = new ChatboxResizeService(client, performanceMetrics);
		privateChatOverlay = new PrivateChatOverlay();
		privateChatLayout = new PrivateChatLayout(client, config, configManager, privateChatOverlay);
		overlayManager.add(privateChatOverlay);
		chatRebuildCoordinator = new ChatRebuildCoordinator(
				client, clientThread, config, chatboxResizeService, performanceMetrics);
		chatboxHotkey = new ChatboxHotkey(
				clientThread, config, chatboxResizeService, keyManager, this::clearChatHistory);
		chatboxHotkey.activate();
		fontMeasurementService = new FontMeasurementService(client, performanceMetrics);
		fontLayoutService = new FontLayoutService(client, config, fontMeasurementService, performanceMetrics);
		chatboxConfigHandler = new ChatboxConfigHandler(chatRebuildCoordinator);
		fontConfigHandler = new FontConfigHandler(client, clientThread, fontLayoutService, performanceMetrics);
		/*
		 * Refresh retained rows through the active layout pipeline.
		 */
		clientThread.invokeLater(() -> {
			if (chatRebuildCoordinator != null) {
				chatRebuildCoordinator.onStartup();
			}

			debugManager.onLoggedIn();
		});

		log.debug("[Chat XL] Plugin Initiated.");
	}

	@Override
	protected void shutDown() {
		final FontLayoutService shutdownLayoutService = fontLayoutService;
		final ChatboxResizeService shutdownResizeService = chatboxResizeService;
		final PrivateChatOverlay shutdownPrivateChatOverlay = privateChatOverlay;
		final PrivateChatLayout shutdownPrivateChatLayout = privateChatLayout;
		final PerformanceMetrics shutdownPerformanceMetrics = performanceMetrics;
		final boolean uninstalling = debugManager.prepareShutdown();

		/*
		 * Disable PRE / POST and config handling before restoration.
		 */
		if (chatboxConfigHandler != null) {
			chatboxConfigHandler.deactivate();
		}

		if (chatRebuildCoordinator != null) {
			chatRebuildCoordinator.deactivate();
		}

		if (fontConfigHandler != null) {
			fontConfigHandler.deactivate();
		}

		if (chatboxHotkey != null) {
			chatboxHotkey.deactivate();
		}

		fontLayoutService = null;
		chatboxResizeService = null;
		chatRebuildCoordinator = null;
		chatboxHotkey = null;
		privateChatOverlay = null;
		privateChatLayout = null;
		fontMeasurementService = null;
		chatboxConfigHandler = null;
		fontConfigHandler = null;

		if (shutdownPrivateChatOverlay != null) {
			overlayManager.remove(shutdownPrivateChatOverlay);
		}

		debugManager.deactivate();

		if (shutdownPerformanceMetrics != null) {
			shutdownPerformanceMetrics.recordRefreshChat(PerformanceMetrics.RefreshReason.SHUTDOWN);
		}

		// Restore native presentation on the client thread.
		clientThread.invokeLater(() -> {
			if (shutdownPrivateChatLayout != null) {
				shutdownPrivateChatLayout.restoreNative();
			}

			final ChatboxResizeService.ScrollBaseline scrollBaseline = shutdownResizeService != null
					? shutdownResizeService.captureScrollBaseline()
					: null;

			if (shutdownResizeService != null) {
				shutdownResizeService.restoreNativeSize();
			}

			if (shutdownLayoutService != null) {
				shutdownLayoutService.restoreNativePresentation();
				shutdownLayoutService.reset();
			}

			client.refreshChat();

			if (shutdownResizeService != null) {
				shutdownResizeService.restoreScrollBaseline(scrollBaseline);
			}

			debugManager.finishShutdown(uninstalling);

			if (shutdownPerformanceMetrics != null) {
				shutdownPerformanceMetrics.reportNow();
			}
		});

		performanceMetrics = null;

		log.debug("[Chat XL] Plugin Terminated.");
	}

	/**
	 * ================================================================
	 * GAME STATE
	 * ================================================================
	 */
	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		if (event == null || event.getGameState() != GameState.LOGGED_IN) {
			return;
		}

		if (chatRebuildCoordinator != null) {
			chatRebuildCoordinator.onLoggedIn();
		}

		debugManager.onLoggedIn();
	}

	/**
	 * ================================================================
	 * CANVAS SIZE
	 * ================================================================
	 */
	@Subscribe
	public void onCanvasSizeChanged(CanvasSizeChanged event) {
		if (event == null) {
			return;
		}

		if (chatRebuildCoordinator != null) {
			chatRebuildCoordinator.onCanvasSizeChanged();
		}
	}

	/**
	 * ================================================================
	 * INTERFACE LIFECYCLE
	 * ================================================================
	 */
	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event) {
		if (event == null) {
			return;
		}

		if (chatRebuildCoordinator != null) {
			chatRebuildCoordinator.onInterfaceChanged();
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event) {
		if (event == null) {
			return;
		}

		if (chatRebuildCoordinator != null) {
			chatRebuildCoordinator.onInterfaceChanged();
		}
	}

	/**
	 * ================================================================
	 * CHAT CONTROLS
	 * ================================================================
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event) {
		if (event == null || chatboxResizeService == null) {
			return;
		}

		if (!chatboxResizeService.onChatControlClicked(event.getWidget())) {
			return;
		}

		clientThread.invokeLater(() -> {
			if (chatboxResizeService != null) {
				chatboxResizeService.finishChatControlClick();
			}
		});
	}

	/**
	 * ================================================================
	 * CHAT COMMANDS
	 * ================================================================
	 */
	@Subscribe
	public void onCommandExecuted(CommandExecuted event) {
		if (event == null) {
			return;
		}

		final String command = event.getCommand();
		if ("clear".equalsIgnoreCase(command) || "cls".equalsIgnoreCase(command)) {
			clientThread.invokeLater(this::clearChatHistory);
			return;
		}

		debugManager.onCommandExecuted(event);
	}

	private void clearChatHistory() {
		boolean removed = false;

		for (ChatMessageType messageType : ChatMessageType.values()) {
			final ChatLineBuffer lineBuffer = client.getChatLineMap().get(messageType.getType());
			if (lineBuffer == null) {
				continue;
			}

			final MessageNode[] lines = lineBuffer.getLines().clone();

			for (MessageNode line : lines) {
				if (line == null) {
					continue;
				}

				lineBuffer.removeMessageNode(line);
				removed = true;
			}
		}

		if (removed) {
			client.refreshChat();
		}
	}

	/**
	 * ================================================================
	 * CONFIGURATION
	 * ================================================================
	 */
	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		debugManager.onConfigChanged(event);

		if (privateChatLayout != null) {
			privateChatLayout.onConfigChanged(event);
		}

		if (chatboxConfigHandler != null && chatboxConfigHandler.onConfigChanged(event)) {
			return;
		}

		if (fontConfigHandler != null) {
			fontConfigHandler.onConfigChanged(event);
		}
	}

	/**
	 * ================================================================
	 * CONFIGURATION PROVIDER
	 * ================================================================
	 */
	@Provides
	Configurations provideConfig(ConfigManager configManager) {
		return configManager.getConfig(Configurations.class);
	}

	/**
	 * ================================================================
	 * CHAT CONSTRUCTION
	 * ================================================================
	 */
	@Subscribe
	public void onScriptPreFired(ScriptPreFired event) {
		debugManager.onChatboxScriptPreFired(event);

		if (chatboxResizeService != null) {
			chatboxResizeService.onScriptPreFired(event, config.chatboxWidth(), config.chatboxHeight());
		}

		debugManager.onFontScriptPreFired(event);

		if (fontLayoutService == null) {
			return;
		}

		final boolean metricsEnabled = performanceMetrics != null && performanceMetrics.isEnabled();

		final long started = metricsEnabled
				? System.nanoTime()
				: 0L;

		fontLayoutService.onScriptPreFired(event);

		if (metricsEnabled && event != null) {
			performanceMetrics.recordPre(
					event.getScriptId(),
					System.nanoTime() - started);
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event) {
		debugManager.onChatboxScriptPostFired(event);

		if (fontLayoutService != null) {
			final boolean metricsEnabled = performanceMetrics != null && performanceMetrics.isEnabled();

			final long started = metricsEnabled
					? System.nanoTime()
					: 0L;

			fontLayoutService.onScriptPostFired(event);

			if (metricsEnabled && event != null) {
				performanceMetrics.recordPost(
						event.getScriptId(),
						System.nanoTime() - started);
			}
		}

		if (chatboxResizeService != null) {
			chatboxResizeService.onScriptPostFired(event, config.chatboxWidth(), config.chatboxHeight());
		}

		if (chatRebuildCoordinator != null) {
			chatRebuildCoordinator.onScriptPostFired(event);
		}

		debugManager.onFontScriptPostFired(event);
		debugManager.reportPerformanceIfDue();
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event) {
		boolean widthChanged = false;
		boolean heightChanged = false;

		if (privateChatLayout != null) {
			/*
			 * Resolve movable split-PM placement and effective width before the
			 * render-boundary rebuild. rebuildpmbox and FontMeasurementService then
			 * see the constrained host width during the same native reconstruction.
			 */
			final PrivateChatLayout.Result privateResult = privateChatLayout.sync();
			widthChanged |= privateResult.isWidthChanged();
		}

		if (chatboxResizeService != null) {
			final ChatboxResizeService.LiveRefresh refresh = chatboxResizeService.consumeLiveRefresh();
			if (refresh != null) {
				widthChanged |= refresh.isWidthChanged();
				heightChanged |= refresh.isHeightChanged();
			}
		}

		if (chatRebuildCoordinator != null && (widthChanged || heightChanged)) {
			/*
			 * Coalesce chatbox and split-PM width changes into one refreshChat().
			 * The coordinator rebuilds retained presentation only and never feeds the
			 * result back through the geometry commit path that previously flickered.
			 */
			chatRebuildCoordinator.refreshLiveGeometry(widthChanged, heightChanged);
		}
	}
}

package com.bigboldchat.input;

import com.bigboldchat.Configurations;
import com.bigboldchat.chatbox.ChatboxResizeService;

import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.KeyManager;
import net.runelite.client.util.HotkeyListener;

/**
 * Owns the chatbox hotkey lifecycle.
 */
public final class ChatboxHotkey {
	private final ClientThread clientThread;
	private final ChatboxResizeService resizeService;
	private final KeyManager keyManager;
	private final Runnable clearChat;
	private final HotkeyListener visibilityHotkeyListener;
	private final HotkeyListener clearHotkeyListener;

	private volatile boolean active;

	public ChatboxHotkey(
			ClientThread clientThread,
			Configurations config,
			ChatboxResizeService resizeService,
			KeyManager keyManager,
			Runnable clearChat) {
		this.clientThread = clientThread;
		this.resizeService = resizeService;
		this.keyManager = keyManager;
		this.clearChat = clearChat;
		this.visibilityHotkeyListener = new HotkeyListener(config::hideChatboxHotkey) {
			@Override
			public void hotkeyPressed() {
				if (!active) {
					return;
				}

				clientThread.invokeLater(() -> {
					if (active) {
						resizeService.toggleChatPresentation();
					}
				});
			}
		};

		/*
		 * Route the hotkey through the same clear action used by ::clear / ::cls so
		 * keyboard and command behavior cannot drift apart.
		 */
		this.clearHotkeyListener = new HotkeyListener(config::clearChatHotkey) {
			@Override
			public void hotkeyPressed() {
				if (!active) {
					return;
				}

				clientThread.invokeLater(() -> {
					if (active) {
						ChatboxHotkey.this.clearChat.run();
					}
				});
			}
		};
	}

	public void activate() {
		if (active) {
			return;
		}

		active = true;
		keyManager.registerKeyListener(visibilityHotkeyListener);
		keyManager.registerKeyListener(clearHotkeyListener);
	}

	public void deactivate() {
		if (!active) {
			return;
		}

		active = false;
		keyManager.unregisterKeyListener(visibilityHotkeyListener);
		keyManager.unregisterKeyListener(clearHotkeyListener);
	}
}

package com.bigboldchat.chat;

import com.bigboldchat.config.ChatFont;
import com.bigboldchat.debug.PerformanceMetrics;
import com.bigboldchat.fonts.ChatFontProfile;
import com.bigboldchat.fonts.ChatFontRegistry;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.FontTypeFace;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;

/**
 * Measures chat text, wrapping, row allocation, and presentation geometry.
 *
 * Produces ConstructionMeasurement values consumed by FontLayoutService.
 * This service does not mutate widgets or script stacks.
 */
public final class FontMeasurementService {
	static final int GAME_BODY_SCRIPT = 199;
	static final int CHAT_BODY_SCRIPT = 203;
	static final int CHANNEL_BODY_SCRIPT = 4483;

	/*
	 * Native Script 4483 rank-icon geometry:
	 *      [channel] +1px [icon] +1px [username]:
	 */
	private static final int RANK_ICON_GAP = 1;

	/*
	 * Native OS separation between:
	 *      [username] -> [message body]
	 */
	private static final int BODY_GAP = 3;

	/*
	 * Separation between text and scrollbar.
	 */
	private static final int SCROLLBAR_PADDING = 3;

	private final Client client;
	private final ChatTextNormalizer textNormalizer;

	// Optional performance instrumentation; null when disabled.
	private final PerformanceMetrics performanceMetrics;

	/*
	 * Cache resolved fonts for the current plugin session.
	 * Failed resolutions are retried on the next request.
	 */
	private final Map<Integer, FontTypeFace> fontCache = new HashMap<>();

	public FontMeasurementService(Client client) {
		this(client, new ChatTextNormalizer(), null);
	}

	public FontMeasurementService(Client client, PerformanceMetrics performanceMetrics) {
		this(client, new ChatTextNormalizer(performanceMetrics), performanceMetrics);
	}

	public FontMeasurementService(
			Client client,
			ChatTextNormalizer textNormalizer,
			PerformanceMetrics performanceMetrics) {
		this.client = client;
		this.textNormalizer = textNormalizer != null
				? textNormalizer
				: new ChatTextNormalizer(performanceMetrics);
		this.performanceMetrics = performanceMetrics;
	}

	boolean supportsScript(int scriptId) {
		return scriptId == GAME_BODY_SCRIPT || scriptId == CHAT_BODY_SCRIPT || scriptId == CHANNEL_BODY_SCRIPT;
	}

	ConstructionMeasurement measure(int scriptId, ChatFont selectedChatFont, ChatFontProfile fontProfile) {
		if (!supportsScript(scriptId) || selectedChatFont == null || fontProfile == null) {
			return null;
		}

		final Object[] objectStack = client.getObjectStack();
		final int objectStackSize = client.getObjectStackSize();

		final int bodyIndex = findBodyIndex(objectStack, objectStackSize);
		if (bodyIndex < 0) {
			return null;
		}

		final String rawBody = (String) objectStack[bodyIndex];
		final String semanticBody = textNormalizer.normalizeSemantic(rawBody);
		if (semanticBody == null) {
			return null;
		}

		/*
		 * FontID 1446 renders ':' incorrectly.
		 *
		 * Keep native text unchanged for correlation and replace ':' only in
		 * the selected text that Chat XL measures and renders.
		 */
		final boolean replaceMalformedColons = selectedChatFont == ChatFont.VERDANA_13_BOLD;

		final String visibleRawBodyText = textNormalizer.renderText(rawBody);

		final String selectedRawBodyText = replaceMalformedColons
				? replaceVerdana13BoldColons(visibleRawBodyText)
				: visibleRawBodyText;

		// Preserve inline images while measuring wrapping.
		final String measurementBody = textNormalizer.measureSemantic(rawBody);
		final String selectedMeasurementBody = textNormalizer.measureSemantic(selectedRawBodyText);
		if (measurementBody == null || selectedMeasurementBody == null) {
			return null;
		}

		final int[] intStack = client.getIntStack();
		final int intStackSize = client.getIntStackSize();
		if (intStack == null || intStackSize < 11 || intStackSize > intStack.length) {
			return null;
		}

		/*
		 * Common trailing Script 199 / 203 / 4483 construction payload:
		 *
		 * [0]  row / order
		 * [1]  line widget
		 * [2]  parent widget
		 * [3]  right boundary
		 * [4]  left boundary
		 * [5]  vertical / line-height construction input
		 * [6]  row Y
		 * [7]  unknown - preserve native
		 * [8]  sender / prefix width
		 * [9]  color
		 * [10] shadow
		 */
		final int rowValueIndex = intStackSize - 11;
		final int lineWidgetIndex = intStackSize - 10;
		final int parentWidgetIndex = intStackSize - 9;
		final int rightBoundaryIndex = intStackSize - 8;
		final int leftBoundaryIndex = intStackSize - 7;
		final int verticalValueIndex = intStackSize - 6;
		final int rowYIndex = intStackSize - 5;
		final int argument7Index = intStackSize - 4;
		final int senderWidthIndex = intStackSize - 3;
		final int colorIndex = intStackSize - 2;
		final int shadowIndex = intStackSize - 1;
		final int lineWidgetId = intStack[lineWidgetIndex];
		final int parentWidgetId = intStack[parentWidgetIndex];
		final int rightBoundary = intStack[rightBoundaryIndex];
		final int leftBoundary = intStack[leftBoundaryIndex];
		final int nativeLineHeight = intStack[verticalValueIndex];
		final int nativeRowY = intStack[rowYIndex];
		final int nativeArgument7 = intStack[argument7Index];
		final int nativeSenderWidth = intStack[senderWidthIndex];

		if (nativeLineHeight <= 0) {
			return null;
		}

		final Widget lineWidget = client.getWidget(lineWidgetId);
		if (lineWidget == null) {
			return null;
		}

		final FontTypeFace nativeFont = resolveFont(FontID.PLAIN_12);
		final FontTypeFace selectedFont = resolveFont(selectedChatFont.getFontId());
		final ChatFontProfile nativeFontProfile = ChatFontRegistry.get(ChatFont.PLAIN_12);
		if (nativeFont == null || selectedFont == null || nativeFontProfile == null) {
			return null;
		}

		final List<String> rawPrefixComponents = scriptId == GAME_BODY_SCRIPT
				? new ArrayList<>()
				: findPrefixComponents(objectStack, bodyIndex);

		/*
		 * Script 199 is the ordinary prefix-less GAME / system-message
		 * constructor.
		 *
		 * Script 203 requires a textual prefix.
		 *
		 * Script 4483 can legitimately provide empty title / sender
		 * components for Clan / Guest Clan system messages.
		 */
		if (scriptId == CHAT_BODY_SCRIPT && rawPrefixComponents.isEmpty()) {
			return null;
		}

		final int lineX = lineWidget.getOriginalX();

		int nativePrefixWidth = 0;
		int selectedPrefixLayoutWidth = 0;

		ChannelPrefixLayout nativeChannelLayout = null;
		ChannelPrefixLayout selectedChannelLayout = null;

		int nativeBodyX;
		int selectedBodyX;

		/*
		 * Script 203 keeps its native/raw prefix for correlation while the
		 * selected presentation may use a separately spaced raw prefix.
		 *
		 * This is primarily used by Friends Chat, where the rank icon is inline
		 * markup inside the same prefix widget as the channel name and username.
		 */
		String selectedRawPrefixText = null;

		if (scriptId == GAME_BODY_SCRIPT) {
			/*
			 * Script 199 is prefix-less and uses the full construction span.
			 * Preserve its native horizontal geometry.
			 */
			nativeBodyX = leftBoundary;
			selectedBodyX = leftBoundary;
		} else if (scriptId == CHAT_BODY_SCRIPT) {
			final String rawPrefix = rawPrefixComponents.get(rawPrefixComponents.size() - 1);

			// Measure native geometry from the unmodified prefix.
			nativePrefixWidth = nativeFont.getTextWidth(normalizeRawForMeasurement(rawPrefix));

			/*
			 * Keep the raw Friends Chat prefix for correlation and build a separate
			 * rendered prefix with configured inline-icon spacing.
			 */
			selectedRawPrefixText = isFriendsChatPrefix(rawPrefix)
					? applyInlineIconUsernameSpacing(rawPrefix, fontProfile.getFriendsChatPlayerIconSpacing(), '\u00A0')
					: rawPrefix;

			/*
			 * Replace malformed FontID 1446 colons in the selected prefix only.
			 */
			if (replaceMalformedColons) {
				selectedRawPrefixText = replaceVerdana13BoldColons(selectedRawPrefixText);
			}

			selectedPrefixLayoutWidth = selectedFont.getTextWidth(normalizeRawForMeasurement(selectedRawPrefixText));

			nativeBodyX = lineX + nativePrefixWidth + BODY_GAP;
			selectedBodyX = lineX + selectedPrefixLayoutWidth + BODY_GAP;
		} else {
			nativeChannelLayout = measureChannelPrefixLayout(
					nativeFont,
					rawPrefixComponents,
					intStack,
					intStackSize,
					lineX,
					false,
					0,
					0,
					nativeFontProfile.getAccountBuildIconPadding(),
					0);

			selectedChannelLayout = measureChannelPrefixLayout(
					selectedFont,
					rawPrefixComponents,
					intStack,
					intStackSize,
					lineX,
					replaceMalformedColons,
					fontProfile.getRankIconRightAdjustment(),
					fontProfile.getRankIconSizeAdjustment(),
					fontProfile.getAccountBuildIconPadding(),
					fontProfile.getChannelAccountBuildIconSpacing());

			if (nativeChannelLayout == null || selectedChannelLayout == null) {
				return null;
			}

			nativeBodyX = nativeChannelLayout.bodyX;
			selectedBodyX = selectedChannelLayout.bodyX;
		}

		final boolean splitPrivate = isSplitPrivate(parentWidgetId);
		final int rightPadding = splitPrivate
				? 0
				: SCROLLBAR_PADDING;
		final int selectedRightBoundary = splitPrivate
				? splitPrivateRightBoundary(leftBoundary, rightBoundary)
				: rightBoundary;
		final int nativeBodyWidth = rightBoundary - nativeBodyX;
		final int selectedBodyWidth = selectedRightBoundary - selectedBodyX - rightPadding;
		if (nativeBodyWidth <= 0 || selectedBodyWidth <= 0) {
			return null;
		}

		final int nativeLines = calculateWrappedLineCount(nativeFont, measurementBody, nativeBodyWidth);
		final int selectedLines = calculateWrappedLineCount(selectedFont, selectedMeasurementBody, selectedBodyWidth);
		if (nativeLines <= 0 || selectedLines <= 0) {
			return null;
		}

		// Apply the selected profile's line-height adjustment.
		final int lineHeightAdjustment = fontProfile.getLineHeightAdjustment();
		final int selectedLineHeight = Math.max(1, nativeLineHeight + lineHeightAdjustment);

		final int rowYOffset = fontProfile.getRowYOffset();

		// Apply PRIVATE_CHAT_GAP to Split Private's bottom-relative row Y.
		final int privateChatGap = isSplitPrivate(parentWidgetId)
				? fontProfile.getPrivateChatGap()
				: 0;

		final int selectedRowY = nativeRowY + rowYOffset + privateChatGap;

		// Compensate construction height for native and selected wrapped-line counts.
		final int desiredHeight = selectedLines * selectedLineHeight;
		final int injectedValue = ceilDiv(desiredHeight, nativeLines);
		if (injectedValue <= 0) {
			return null;
		}

		final int allocatedHeight = nativeLines * injectedValue;
		final ConstructionMeasurement measurement = new ConstructionMeasurement();

		measurement.scriptId = scriptId;
		measurement.semanticBody = semanticBody;
		measurement.selectedRawBodyText = selectedRawBodyText;
		measurement.selectedChatFont = selectedChatFont;
		measurement.selectedFontId = selectedChatFont.getFontId();
		measurement.rawPrefixComponents = new ArrayList<>(rawPrefixComponents);
		// Script 203 keeps rendered raw prefix separately from native raw components used for correlation.
		measurement.selectedRawPrefixText = selectedRawPrefixText;
		measurement.rowValueIndex = rowValueIndex;
		measurement.verticalValueIndex = verticalValueIndex;
		measurement.rowYIndex = rowYIndex;
		measurement.argument7Index = argument7Index;
		measurement.senderWidthIndex = senderWidthIndex;
		measurement.lineWidgetId = lineWidgetId;
		measurement.parentWidgetId = parentWidgetId;
		measurement.leftBoundary = leftBoundary;
		measurement.rightBoundary = rightBoundary;
		measurement.lineX = lineX;
		measurement.nativeLineHeight = nativeLineHeight;
		measurement.lineHeightAdjustment = lineHeightAdjustment;
		measurement.selectedLineHeight = selectedLineHeight;
		measurement.nativeRowY = nativeRowY;
		measurement.rowYOffset = rowYOffset;
		measurement.selectedRowY = selectedRowY;
		measurement.channelTextYOffset = fontProfile.getChannelTextYOffset();
		measurement.rankIconRightAdjustment = fontProfile.getRankIconRightAdjustment();
		measurement.rankIconSizeAdjustment = fontProfile.getRankIconSizeAdjustment();
		measurement.rankIconYOffset = fontProfile.getChannelRankIconYOffset();
		measurement.accountBuildIconPadding = fontProfile.getAccountBuildIconPadding();
		measurement.nativeArgument7 = nativeArgument7;
		measurement.nativeSenderWidth = nativeSenderWidth;
		measurement.nativeColor = intStack[colorIndex];
		measurement.nativeShadow = intStack[shadowIndex];
		measurement.nativePrefixWidth = nativePrefixWidth;
		measurement.selectedPrefixLayoutWidth = selectedPrefixLayoutWidth;
		measurement.nativeChannelLayout = nativeChannelLayout;
		measurement.selectedChannelLayout = selectedChannelLayout;
		measurement.nativeBodyX = nativeBodyX;
		measurement.nativeBodyWidth = nativeBodyWidth;
		measurement.selectedBodyX = selectedBodyX;
		measurement.selectedBodyWidth = selectedBodyWidth;
		measurement.nativeLines = nativeLines;
		measurement.selectedLines = selectedLines;
		measurement.desiredHeight = desiredHeight;
		measurement.injectedValue = injectedValue;
		measurement.allocatedHeight = allocatedHeight;

		return measurement;
	}

	/*
	 * ================================================================
	 * PRIVATE CHAT
	 * ================================================================
	 */
	private boolean isSplitPrivate(int parentWidgetId) {
		return WidgetUtil.componentToInterface(parentWidgetId) == InterfaceID.PM_CHAT;
	}

	private int splitPrivateRightBoundary(int leftBoundary, int nativeRightBoundary) {
		final Widget pmHost = activeSplitPrivateHost();
		if (pmHost == null || pmHost.getWidth() <= 0) {
			return nativeRightBoundary;
		}

		/*
		 * REBUILDPMBOX continues to expose RuneScape's native construction
		 * boundary even when ChatXL has constrained the movable PM host. Measure
		 * selected wrapping against the host's effective width while preserving
		 * the native boundary above for native-line compensation and correlation.
		 */
		return leftBoundary + pmHost.getWidth();
	}

	private Widget activeSplitPrivateHost() {
		final int topLevel = client.getTopLevelInterfaceId();
		if (topLevel == InterfaceID.TOPLEVEL_OSRS_STRETCH) {
			return client.getWidget(InterfaceID.ToplevelOsrsStretch.PM_CONTAINER);
		}
		if (topLevel == InterfaceID.TOPLEVEL_PRE_EOC) {
			return client.getWidget(InterfaceID.ToplevelPreEoc.PM_CONTAINER);
		}
		return null;
	}

	/*
	 * ================================================================
	 * CHANNEL / RANK-ICON MEASUREMENT
	 * ================================================================
	 */
	private ChannelPrefixLayout measureChannelPrefixLayout(
			FontTypeFace font,
			List<String> rawPrefixComponents,
			int[] intStack,
			int intStackSize,
			int lineX,
			boolean replaceMalformedColons,
			int rankIconRightAdjustment,
			int rankIconSizeAdjustment,
			int accountBuildIconPadding,
			int inlineIconUsernameSpacing) {
		if (font == null || rawPrefixComponents == null || intStack == null) {
			return null;
		}

		final ChannelPrefixLayout layout = new ChannelPrefixLayout();

		layout.titleX = lineX;

		final String rawTitleText = rawPrefixComponents.size() > 0
				? rawPrefixComponents.get(0)
				: "";

		layout.titleText = textNormalizer.normalizeSemantic(rawTitleText);

		layout.renderedTitleText = replaceMalformedColons
				? replaceVerdana13BoldColons(rawTitleText)
				: rawTitleText;

		final String rawSenderText = rawPrefixComponents.size() > 1
				? rawPrefixComponents.get(1)
				: "";

		/*
		 * Preserve the native sender semantic for correlation.
		 */
		layout.senderText = textNormalizer.normalizeSemantic(rawSenderText);

		/*
		 * The rendered sender may contain additional visible spacing after the
		 * final inline account/build icon.
		 *
		 * Example:
		 *
		 *     native:   <img=2>Username:
		 *     selected: <img=2> Username:
		 */
		layout.renderedSenderText = applyInlineIconUsernameSpacing(rawSenderText, inlineIconUsernameSpacing, ' ');

		if (replaceMalformedColons) {
			layout.renderedSenderText = replaceVerdana13BoldColons(layout.renderedSenderText);
		}

		if (layout.titleText == null) {
			layout.titleText = "";
		}

		if (layout.senderText == null) {
			layout.senderText = "";
		}

		layout.hasTitle = !layout.titleText.isEmpty();
		layout.hasSender = !layout.senderText.isEmpty();

		if (layout.hasTitle) {
			layout.titleWidth = font.getTextWidth(normalizeRawForMeasurement(layout.renderedTitleText));
		}

		if (layout.hasSender) {
			layout.senderWidth = font.getTextWidth(normalizeRawForMeasurement(layout.renderedSenderText));
		}

		/*
		 * Read optional rank sprite ID, width, and height
		 * immediately before the common Script-4483 payload.
		 */
		final int commonPayloadStart = intStackSize - 11;
		if (layout.hasSender && commonPayloadStart >= 3) {
			final int spriteIdCandidate = intStack[commonPayloadStart - 3];
			final int widthCandidate = intStack[commonPayloadStart - 2];
			final int heightCandidate = intStack[commonPayloadStart - 1];
			if (spriteIdCandidate >= 0
					&& widthCandidate > 0
					&& widthCandidate <= 32
					&& heightCandidate > 0
					&& heightCandidate <= 32) {
				layout.rankIconSpriteId = spriteIdCandidate;
				layout.rankIconWidth = Math.max(1, widthCandidate + rankIconSizeAdjustment);
				layout.rankIconHeight = Math.max(1, heightCandidate + rankIconSizeAdjustment);
			}
		}

		/*
		 * Inline account/build icons are measured as part of sender text.
		 *
		 * CHANNEL_ACCOUNT_BUILD_ICON_SPACING controls icon-to-name spacing.
		 * ACCOUNT_BUILD_ICON_PADDING reserves additional sender layout width.
		 */
		if (layout.hasSender && hasAccountBuildIcon(rawSenderText)) {
			layout.senderWidth += accountBuildIconPadding;
		}

		int cursor = lineX;

		if (layout.hasTitle) {
			cursor += layout.titleWidth;
		}

		if (layout.hasSender) {
			if (layout.rankIconWidth > 0) {
				/*
				 * Native:
				 *
				 * title -> 1px -> icon -> 1px -> sender
				 */
				if (layout.hasTitle) {
					cursor += RANK_ICON_GAP;
				}

				layout.rankIconX = cursor;
				cursor += layout.rankIconWidth;
				cursor += RANK_ICON_GAP;

				/*
				 * Enforce minimum spacing after the final inline image before the username.
				 *
				 * The caller supplies the spacing character. Existing whitespace counts
				 * toward the minimum, and consecutive inline images are not separated.
				 */
				cursor += rankIconRightAdjustment;
			} else if (layout.hasTitle) {
				cursor += BODY_GAP;
			}

			layout.senderX = cursor;
			cursor += layout.senderWidth;
			cursor += BODY_GAP;
		} else if (layout.hasTitle) {
			cursor += BODY_GAP; // Title-only Clan / Guest Clan system message.
		}

		layout.bodyX = cursor; // If both title and sender are empty, the body naturally begins at lineX.
		return layout;
	}

	/*
	 * ================================================================
	 * VERDANA 13 BOLD CORRECTION
	 * ================================================================
	 */

	/*
	 * FontID 1446 renders ':' incorrectly.
	 *
	 * This helper is used only for selected Verdana 13 Bold text.
	 * Native text remains unchanged for widget correlation.
	 */
	private String replaceVerdana13BoldColons(String text) {
		if (text == null || text.isEmpty()) {
			return text;
		}

		return text.replace(':', '-');
	}

	/*
	 * ================================================================
	 * FONT RESOLUTION
	 * ================================================================
	 */

	private FontTypeFace resolveFont(int fontId) {
		final FontTypeFace cachedFont = fontCache.get(fontId);
		if (cachedFont != null) {
			if (performanceMetrics != null) {
				performanceMetrics.recordFontCacheHit();
			}

			return cachedFont;
		}

		final long started = performanceMetrics != null && performanceMetrics.isEnabled()
				? System.nanoTime()
				: 0L;

		try {
			final Widget probe = client.getWidget(InterfaceID.Chatbox.INPUT);
			if (probe == null) {
				return null;
			}

			final int originalFontId = probe.getFontId();
			final FontTypeFace resolvedFont;

			try {
				probe.setFontId(fontId);

				resolvedFont = probe.getFont();
			} finally {
				probe.setFontId(originalFontId);
			}

			if (resolvedFont != null) {
				fontCache.put(fontId, resolvedFont);
			}

			return resolvedFont;
		} finally {
			if (performanceMetrics != null && performanceMetrics.isEnabled()) {
				performanceMetrics.recordFontCacheMiss(System.nanoTime() - started);
			}
		}
	}

	/*
	 * ================================================================
	 * OBJECT-STACK EXTRACTION
	 * ================================================================
	 */
	private int findBodyIndex(Object[] stack, int size) {
		if (stack == null || size <= 0) {
			return -1;
		}

		final int safeSize = Math.min(size, stack.length);
		for (int i = safeSize - 1; i >= 0; i--) {
			if (stack[i] instanceof String && !((String) stack[i]).isEmpty()) {
				return i;
			}
		}

		return -1;
	}

	private List<String> findPrefixComponents(Object[] stack, int bodyIndex) {
		final List<String> result = new ArrayList<>();
		if (stack == null || bodyIndex < 0) {
			return result;
		}

		final int safeSize = Math.min(bodyIndex, stack.length);
		for (int i = 0; i < safeSize; i++) {
			final Object value = stack[i];
			if (value instanceof String) {
				result.add((String) value);
			}
		}

		return result;
	}

	private boolean hasAccountBuildIcon(String rawSenderText) {
		if (rawSenderText == null || rawSenderText.isEmpty()) {
			return false;
		}

		return rawSenderText.toLowerCase(Locale.ROOT).contains("<img=");
	}

	/*
	 * Add visible spacing between the final inline image tag and the
	 * username that follows it.
	 *
	 * The caller supplies the actual spacing character because Chat XL uses
	 * different spacing characters for the two supported inline-icon cases:
	 *
	 *     Friends Chat player/rank icon:
	 *         \u00A0  non-breaking space
	 *
	 *     Clan / Guest Clan account-build icon:
	 *         \u0020  normal space
	 *
	 * If multiple inline images occur before the username, only the final
	 * image receives the username gap:
	 *
	 *     <img=67><img=2>PlayerName:
	 *
	 * becomes:
	 *
	 *     <img=67><img=2> PlayerName:
	 *
	 * rather than inserting spacing between the consecutive icons.
	 *
	 * Existing whitespace immediately after the final image counts toward
	 * the configured minimum, which keeps repeated processing idempotent.
	 */
	private String applyInlineIconUsernameSpacing(String rawText, int spacing, char spacingCharacter) {
		if (rawText == null || rawText.isEmpty() || spacing <= 0) {
			return rawText;
		}

		final String lower = rawText.toLowerCase(Locale.ROOT);
		final int imageStart = lower.lastIndexOf("<img=");
		if (imageStart < 0) {
			return rawText;
		}

		final int imageEnd = rawText.indexOf('>', imageStart);
		if (imageEnd < 0 || imageEnd >= rawText.length() - 1) {
			return rawText;
		}

		int existingSpacing = 0;
		for (int i = imageEnd + 1; i < rawText.length(); i++) {
			final char ch = rawText.charAt(i);
			if (ch == ' ' || ch == '\u00A0' || ch == '\t') {
				existingSpacing++;
				continue;
			}

			break;
		}

		final int spacingToAdd = Math.max(0, spacing - existingSpacing);
		if (spacingToAdd == 0) {
			return rawText;
		}

		final StringBuilder gap = new StringBuilder(spacingToAdd);
		for (int i = 0; i < spacingToAdd; i++) {
			gap.append(spacingCharacter);
		}

		return rawText.substring(0, imageEnd + 1) + gap + rawText.substring(imageEnd + 1);
	}

	/*
	 * Script 203 is used by several chat surfaces.
	 *
	 * Friends Chat is identified by its bracketed combined prefix:
	 *
	 *     [Friends Chat] <img=rank>Username:
	 */
	private boolean isFriendsChatPrefix(String rawPrefix) {
		final String semanticPrefix = textNormalizer.normalizeSemantic(rawPrefix);
		if (semanticPrefix == null || semanticPrefix.length() < 3 || semanticPrefix.charAt(0) != '[') {
			return false;
		}

		final int closingBracket = semanticPrefix.indexOf(']');
		return closingBracket > 0 && closingBracket < semanticPrefix.length() - 1;
	}

	/*
	 * ================================================================
	 * TEXT NORMALIZATION
	 * ================================================================
	 */

	private String normalizeRawForMeasurement(String text) {
		if (text == null) {
			return "";
		}

		return text.replace('\u00A0', ' ');
	}

	/*
	 * ================================================================
	 * WRAPPING / HEIGHT
	 * ================================================================
	 */
	private int calculateWrappedLineCount(FontTypeFace font, String text, int maxWidth) {
		if (font == null || maxWidth <= 0 || text == null || text.isEmpty()) {
			return 1;
		}

		final String normalized = text
				.replace("\r\n", "\n")
				.replace('\r', '\n');
		final String[] explicitLines = normalized.split("\n", -1);
		int totalLines = 0;

		for (String explicitLine : explicitLines) {
			totalLines += calculateSingleParagraphLines(font, explicitLine, maxWidth);
		}

		return Math.max(1, totalLines);
	}

	int calculateSingleParagraphLines(FontTypeFace font, String text, int maxWidth) {
		if (text == null || text.isEmpty()) {
			return 1;
		}

		if (font.getTextWidth(text) <= maxWidth) {
			return 1;
		}

		final String trimmed = text.trim();
		if (trimmed.isEmpty()) {
			return 1;
		}

		final String[] words = trimmed.split("\\s+");
		int lines = 1;
		String currentLine = "";

		for (String word : words) {
			if (word.isEmpty()) {
				continue;
			}

			/*
			 * Don't hard-wrap one uninterrupted token character by character.
			 * This applies uniformly to letters, digits, punctuation, and symbols.
			 */
			if (font.getTextWidth(word) > maxWidth) {
				if (!currentLine.isEmpty()) {
					lines++;
				}

				currentLine = word;
				continue;
			}

			if (currentLine.isEmpty()) {
				currentLine = word;
				continue;
			}

			final String candidate = currentLine + " " + word;
			if (font.getTextWidth(candidate) <= maxWidth) {
				currentLine = candidate;
			} else {
				lines++;
				currentLine = word;
			}
		}

		return Math.max(1, lines);
	}

	private int ceilDiv(int numerator, int denominator) {
		if (denominator <= 0) {
			return numerator;
		}

		return (numerator + denominator - 1) / denominator;
	}

	/*
	 * ================================================================
	 * RESULT TYPES
	 * ================================================================
	 */
	static final class ChannelPrefixLayout {
		String titleText = ""; // Native semantic title used for correlation.
		String renderedTitleText = ""; // Exact title text rendered after correlation.
		String senderText = ""; // Native semantic sender used for correlation.
		String renderedSenderText = ""; // Exact selected raw sender markup rendered after correlation.

		boolean hasTitle;
		boolean hasSender;

		int titleX;
		int titleWidth;
		int rankIconSpriteId = -1;
		int rankIconX = -1;
		int rankIconWidth;
		int rankIconHeight;
		int senderX;
		int senderWidth;
		int bodyX;
	}

	static final class ConstructionMeasurement {
		int scriptId;

		String semanticBody; // Native semantic body used for correlation.
		String selectedRawBodyText; // Exact selected raw body rendered after correlation.

		ChatFont selectedChatFont;
		int selectedFontId;

		List<String> rawPrefixComponents;
		String selectedRawPrefixText; // Exact selected raw Script-203 prefix rendered in POST.

		int rowValueIndex;
		int verticalValueIndex;
		int rowYIndex;
		int argument7Index;
		int senderWidthIndex;
		int lineWidgetId;
		int parentWidgetId;
		int leftBoundary;
		int rightBoundary;
		int lineX;
		int nativeLineHeight;
		int lineHeightAdjustment;
		int selectedLineHeight;
		int nativeRowY;
		int rowYOffset;
		int selectedRowY;
		int channelTextYOffset;
		int rankIconRightAdjustment;
		int rankIconSizeAdjustment;
		int rankIconYOffset;
		int accountBuildIconPadding;
		int nativeArgument7;
		int nativeSenderWidth;
		int nativeColor;
		int nativeShadow;
		int nativePrefixWidth;
		int selectedPrefixLayoutWidth;

		ChannelPrefixLayout nativeChannelLayout;
		ChannelPrefixLayout selectedChannelLayout;

		int nativeBodyX;
		int nativeBodyWidth;
		int selectedBodyX;
		int selectedBodyWidth;
		int nativeLines;
		int selectedLines;
		int desiredHeight;
		int injectedValue;
		int allocatedHeight;
	}
}

package com.bigboldchat.chat;

import com.bigboldchat.Configurations;
import com.bigboldchat.config.ChatFont;
import com.bigboldchat.debug.PerformanceMetrics;
import com.bigboldchat.fonts.ChatFontProfile;
import com.bigboldchat.fonts.ChatFontRegistry;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

import net.runelite.api.Client;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetUtil;

/**
 * Applies Chat XL construction geometry and widget presentation.
 *
 * PRE injects measured construction values.
 * POST correlates row widgets and applies selected presentation.
 * FINALIZE applies queued component-specific Y offsets.
 *
 * FontMeasurementService supplies the ConstructionMeasurement consumed here.
 */
public final class FontLayoutService {
	/*
	 * Script used to apply queued component-specific Y offsets.
	 */
	private static final int CHAT_FINALIZE_SCRIPT = 72;
	private static final int BODY_TEXT_Y_ALIGNMENT = WidgetTextAlignment.BOTTOM;
	private static final int PREFIX_TEXT_Y_ALIGNMENT = WidgetTextAlignment.BOTTOM;

	private final Client client;
	private final Configurations config;
	private final FontMeasurementService measurementService;
	private final ChatTextNormalizer textNormalizer;

	// Optional performance instrumentation; null when disabled.
	private final PerformanceMetrics performanceMetrics;

	/*
	 * Active font selection resolved outside the construction hot path.
	 *
	 * Configuration changes replace this immutable pair once, while every
	 * supported PRE construction simply snapshots the already-resolved state.
	 */
	private ActiveFontState activeFontState;

	/*
	 * One exact PRE -> POST construction pair.
	 *
	 * Nested scripts do not replace this state because only supported
	 * construction scripts create a new measurement.
	 */
	private FontMeasurementService.ConstructionMeasurement pending;

	/*
	 * Exact profile paired with the pending PRE -> POST construction.
	 *
	 * This snapshots activeFontState for the construction so POST cannot
	 * observe a different profile if configuration changes between events.
	 */
	private ChatFontProfile pendingFontProfile;

	/*
	 * Widgets awaiting delayed profile-specific Y correction.
	 *
	 * Text entries retain expected semantic text; sprite entries retain
	 * their expected sprite ID as identity guards.
	 */
	private final IdentityHashMap<Widget, PendingYOffset> pendingYOffsets = new IdentityHashMap<>();

	/*
	 * Native and last-applied presentation values tracked per Widget identity.
	 *
	 * Used for compare-before-write mutation and safe native restoration.
	 */
	private final IdentityHashMap<Widget, NativeWidgetState> nativeWidgetStates = new IdentityHashMap<>();

	/*
	 * Persistent per-surface row indexes keyed by OriginalY + RelativeY.
	 *
	 * Supports direct reuse, local repair, and broad fallback when required.
	 */
	private final Map<Surface, RowCorrelationIndex> rowIndexes = new EnumMap<>(Surface.class);

	public FontLayoutService(
			Client client,
			Configurations config,
			FontMeasurementService measurementService) {
		this(
				client,
				config,
				measurementService,
				new ChatTextNormalizer(),
				null);
	}

	public FontLayoutService(
			Client client,
			Configurations config,
			FontMeasurementService measurementService,
			PerformanceMetrics performanceMetrics) {
		this(
				client,
				config,
				measurementService,
				new ChatTextNormalizer(performanceMetrics),
				performanceMetrics);
	}

	public FontLayoutService(
			Client client,
			Configurations config,
			FontMeasurementService measurementService,
			ChatTextNormalizer textNormalizer,
			PerformanceMetrics performanceMetrics) {
		this.client = client;
		this.config = config;

		this.measurementService = measurementService;
		this.textNormalizer = textNormalizer != null
				? textNormalizer
				: new ChatTextNormalizer(performanceMetrics);

		this.performanceMetrics = performanceMetrics;

		refreshActiveFontState();
	}

	/*
	 * ================================================================
	 * PRE
	 * ================================================================
	 */

	public void onScriptPreFired(ScriptPreFired event) {
		if (event == null) {
			return;
		}

		final int scriptId = event.getScriptId();

		/*
		 * Apply queued component-specific Y offsets on the finalize script.
		 */
		if (scriptId == CHAT_FINALIZE_SCRIPT) {
			applyPendingYOffsetsIfChatFinalize();
			return;
		}

		if (!measurementService.supportsScript(scriptId)) {
			return;
		}

		/*
		 * A supported PRE starts a new exact construction pair.
		 *
		 * Supported constructors are resolved by MeasurementService:
		 * Script 199 GAME/system, Script 203 chat/private/FC, and
		 * Script 4483 Clan/Guest Clan.
		 */
		pending = null;
		pendingFontProfile = null;

		final ActiveFontState fontState = activeFontState;
		if (fontState == null || fontState.fontProfile == null) {
			return;
		}

		final ChatFont selectedChatFont = fontState.chatFont;
		final ChatFontProfile fontProfile = fontState.fontProfile;

		final long measurementStarted = performanceMetrics != null && performanceMetrics.isEnabled()
				? System.nanoTime()
				: 0L;

		final FontMeasurementService.ConstructionMeasurement measurement =
				measurementService.measure(scriptId, selectedChatFont, fontProfile);

		if (performanceMetrics != null && performanceMetrics.isEnabled()) {
			performanceMetrics.recordMeasurement(System.nanoTime() - measurementStarted);
		}

		if (measurement == null) {
			return;
		}

		final int[] intStack = client.getIntStack();
		final int intStackSize = client.getIntStackSize();
		if (intStack == null || intStackSize <= 0 || intStackSize > intStack.length) {
			return;
		}

		/*
		 * PRE injects selected height and row Y while preserving native ARG7
		 * and sender width. Horizontal presentation is applied in POST.
		 */
		intStack[measurement.verticalValueIndex] = measurement.injectedValue;
		intStack[measurement.rowYIndex] = measurement.selectedRowY;
		intStack[measurement.argument7Index] = measurement.nativeArgument7;
		intStack[measurement.senderWidthIndex] = measurement.nativeSenderWidth;

		pending = measurement;
		pendingFontProfile = fontProfile;
	}

	/*
	 * ================================================================
	 * POST
	 * ================================================================
	 */

	public void onScriptPostFired(ScriptPostFired event) {
		if (event == null || pending == null || event.getScriptId() != pending.scriptId) {
			return;
		}

		final FontMeasurementService.ConstructionMeasurement state = pending;
		final ChatFontProfile fontProfile = pendingFontProfile;
		pending = null;
		pendingFontProfile = null;

		final Widget lineWidget = client.getWidget(state.lineWidgetId);
		if (lineWidget == null) {
			return;
		}

		final Surface surface = determineSurface(state.parentWidgetId);

		final List<Widget> rowWidgets = collectRow(lineWidget, surface);

		/*
		 * Prefer row correlation. Build the broad semantic fallback on first
		 * miss and reuse it for the remainder of this POST.
		 */
		final FallbackCorrelationContext fallbackContext = new FallbackCorrelationContext(surface);
		final Widget bodyWidget = state.semanticBody.isEmpty()
				? matchEmptyBodyRow(rowWidgets, state.nativeBodyX)
				: findTargetWidgetForLine(state.semanticBody, lineWidget, surface, rowWidgets, fallbackContext);

		if (bodyWidget == null) {
			return;
		}

		/*
		 * Script 199 GAME / system rows are prefix-less, so this naturally
		 * returns an empty list for that constructor.
		 */
		final List<Widget> prefixWidgets = findPrefixWidgetsForLine(
				state.rawPrefixComponents,
				lineWidget,
				surface,
				bodyWidget,
				rowWidgets,
				fallbackContext);

		final Widget rowAnchor = !prefixWidgets.isEmpty()
				? prefixWidgets.get(0)
				: lineWidget;

		/*
		 * Correlate the rank icon before changing row geometry.
		 */
		final Widget rankIconWidget;
		if (state.scriptId
				== FontMeasurementService.CHANNEL_BODY_SCRIPT
				&& state.nativeChannelLayout != null
				&& state.nativeChannelLayout.rankIconSpriteId >= 0) {
			rankIconWidget = findRankIconWidget(state.nativeChannelLayout, rowAnchor, rowWidgets);
		} else {
			rankIconWidget = null;
		}

		applyPrefixPresentation(state, prefixWidgets, fontProfile);
		applyBodyPresentation(state, bodyWidget, fontProfile);
		applyRankIconPresentation(state, rankIconWidget, fontProfile);
	}

	/*
	 * ================================================================
	 * PRESENTATION
	 * ================================================================
	 */

	private void applyBodyPresentation(
			FontMeasurementService.ConstructionMeasurement state,
			Widget bodyWidget,
			ChatFontProfile fontProfile) {
		if (state == null || bodyWidget == null) {
			return;
		}

		boolean changed = setFontIdIfChanged(bodyWidget, state.selectedFontId);
		changed |= setLineHeightIfChanged(bodyWidget, state.selectedLineHeight);
		changed |= setYTextAlignmentIfChanged(bodyWidget, BODY_TEXT_Y_ALIGNMENT);

		/*
		 * Correlation has already completed against the native body text.
		 * Apply the exact selected text measured by MeasurementService.
		 */
		if (state.selectedRawBodyText != null && !state.selectedRawBodyText.equals(bodyWidget.getText())) {
			changed |= setTextIfChanged(bodyWidget, state.selectedRawBodyText);
		}

		changed |= setOriginalXIfChanged(bodyWidget, state.selectedBodyX);
		changed |= setOriginalWidthIfChanged(bodyWidget, state.selectedBodyWidth);

		/*
		 * Queue component-specific body Y correction for finalize.
		 * Script 199 uses only the PRE row-Y adjustment.
		 */
		if (fontProfile != null && state.scriptId == FontMeasurementService.CHANNEL_BODY_SCRIPT) {
			queueTextYOffset(bodyWidget, fontProfile.getChannelTextYOffset());
		} else if (fontProfile != null && isFriendsChatConstruction(state)) {
			queueTextYOffset(bodyWidget, fontProfile.getFriendsChatTextYOffset());
		} else {
			pendingYOffsets.remove(bodyWidget);
		}

		revalidateWidgetIfChanged(bodyWidget, changed);
	}

	private void applyPrefixPresentation(
			FontMeasurementService.ConstructionMeasurement state,
			List<Widget> prefixWidgets,
			ChatFontProfile fontProfile) {
		if (state == null || prefixWidgets == null || prefixWidgets.isEmpty()) {
			return;
		}

		for (Widget widget : prefixWidgets) {
			if (widget == null) {
				continue;
			}

			final String semantic = textNormalizer.normalizeSemantic(widget.getText());
			if (semantic == null || semantic.isEmpty()) {
				continue;
			}

			final int previousOriginalY = widget.getOriginalY();
			final int previousRelativeY = widget.getRelativeY();

			boolean changed = setFontIdIfChanged(widget, state.selectedFontId);
			changed |= setLineHeightIfChanged(widget, state.selectedLineHeight);

			/*
			 * Script 203's prefix widget uses bottom-aligned text natively. Changing
			 * that alignment breaks ordinary one-line PM rows, so keep BOTTOM and
			 * instead move the one-line prefix widget upward when the selected body
			 * wraps. This keeps the sender on the first visual line without changing
			 * the single-line baseline RuneScape already expects.
			 */
			changed |= setOriginalHeightIfChanged(widget, state.selectedLineHeight);
			changed |= setYTextAlignmentIfChanged(widget, PREFIX_TEXT_Y_ALIGNMENT);
			final boolean prefixYChanged = applySplitPrivatePrefixWrapOffset(state, widget);
			changed |= prefixYChanged;

			/*
			 * Script 203 uses one textual prefix widget.
			 */
			if (state.scriptId == FontMeasurementService.CHAT_BODY_SCRIPT && prefixWidgets.size() == 1) {
				changed |= setOriginalWidthIfChanged(widget, state.selectedPrefixLayoutWidth);

				/*
				 * MeasurementService retains the native prefix for correlation and
				 * separately provides the exact selected text to render.
				 *
				 * This includes Friends Chat icon spacing and the Verdana 13 Bold
				 * malformed-colon replacement.
				 */
				if (state.selectedRawPrefixText != null && !state.selectedRawPrefixText.equals(widget.getText())) {
					changed |= setTextIfChanged(widget, state.selectedRawPrefixText);
				}
			}

			/*
			 * Queue channel-title and username Y corrections for finalize.
			 */
			if (state.scriptId == FontMeasurementService.CHANNEL_BODY_SCRIPT && state.selectedChannelLayout != null) {
				final FontMeasurementService.ChannelPrefixLayout channel = state.selectedChannelLayout;
				boolean recognizedChannelComponent = false;

				if (channel.hasTitle && semantic.equalsIgnoreCase(channel.titleText)) {
					changed |= setOriginalXIfChanged(widget, channel.titleX);
					changed |= setOriginalWidthIfChanged(widget, channel.titleWidth);

					if (channel.renderedTitleText != null
							&& !channel.renderedTitleText.isEmpty()
							&& !channel.renderedTitleText.equals(widget.getText())) {
						changed |= setTextIfChanged(widget, channel.renderedTitleText);
					}

					recognizedChannelComponent = true;

					if (fontProfile != null) {
						queueTextYOffset(widget, fontProfile.getChannelNameYOffset());
					}
				}

				if (channel.hasSender && semantic.equalsIgnoreCase(channel.senderText)) {
					changed |= setOriginalXIfChanged(widget, channel.senderX);
					changed |= setOriginalWidthIfChanged(widget, channel.senderWidth);

					/*
					 * Apply measured sender markup after correlation, including
					 * icon spacing and the Verdana 13 Bold colon correction.
					 */
					if (channel.renderedSenderText != null
							&& !channel.renderedSenderText.isEmpty()
							&& !channel.renderedSenderText.equals(widget.getText())) {
						changed |= setTextIfChanged(widget, channel.renderedSenderText);
					}

					recognizedChannelComponent = true;

					if (fontProfile != null) {
						queueTextYOffset(widget, fontProfile.getChannelUsernameYOffset());
					}
				}

				if (!recognizedChannelComponent || fontProfile == null) {
					pendingYOffsets.remove(widget);
				}
			} else if (state.scriptId
					== FontMeasurementService.CHAT_BODY_SCRIPT
					&& prefixWidgets.size()
					== 1
					&& fontProfile != null
					&& isFriendsChatConstruction(state)) {
				/*
				 * Friends Chat renders the channel name, inline rank icon, and
				 * username inside one prefix widget. They therefore share one
				 * vertical correction.
				 */
				queueTextYOffset(widget, fontProfile.getFriendsChatPrefixYOffset());
			} else {
				pendingYOffsets.remove(widget);
			}

			revalidateWidgetIfChanged(widget, changed);
			if (prefixYChanged) {
				notifyIndexedWidgetGeometryChanged(widget, previousOriginalY, previousRelativeY);
			}
		}
	}

	/*
	 * Split private-chat prefixes are separate one-line widgets. RuneScape places
	 * them on the row's bottom line, which is correct for a one-line message but
	 * becomes the final line after ChatXL allocates extra height for wrapping.
	 * Preserve the native bottom alignment and shift only the prefix widget upward
	 * by the selected body's additional wrapped-line height.
	 */
	private boolean applySplitPrivatePrefixWrapOffset(
			FontMeasurementService.ConstructionMeasurement state,
			Widget widget) {
		if (!isSplitPrivateConstruction(state) || widget == null) {
			return false;
		}

		final int extraHeight = Math.max(0, state.desiredHeight - state.selectedLineHeight);
		final NativeWidgetState widgetState = nativeWidgetStates.get(widget);
		final int baseOriginalY = widgetState != null
				&& widgetState.originalYCaptured
				&& widget.getOriginalY() == widgetState.appliedOriginalY
				? widgetState.nativeOriginalY
				: widget.getOriginalY();

		return setOriginalYIfChanged(widget, baseOriginalY + extraHeight);
	}

	private boolean isSplitPrivateConstruction(FontMeasurementService.ConstructionMeasurement state) {
		return state != null
				&& WidgetUtil.componentToInterface(state.parentWidgetId) == InterfaceID.PM_CHAT;
	}

	/*
	 * Identify Friends Chat by its combined bracketed Script-203 prefix:
	 *
	 *     [Friends Chat name] + optional inline rank + username
	 */
	private boolean isFriendsChatConstruction(FontMeasurementService.ConstructionMeasurement state) {
		if (state == null
				|| state.scriptId
				!= FontMeasurementService.CHAT_BODY_SCRIPT
				|| state.rawPrefixComponents == null
				|| state.rawPrefixComponents.size()
				!= 1) {
			return false;
		}

		final String semanticPrefix = textNormalizer.normalizeSemantic(state.rawPrefixComponents.get(0));
		if (semanticPrefix == null || semanticPrefix.length() < 3 || semanticPrefix.charAt(0) != '[') {
			return false;
		}

		final int closingBracket = semanticPrefix.indexOf(']');
		return closingBracket > 0 && closingBracket < semanticPrefix.length() - 1;
	}

	private void applyRankIconPresentation(
			FontMeasurementService.ConstructionMeasurement state,
			Widget rankIconWidget,
			ChatFontProfile fontProfile) {
		if (state == null || rankIconWidget == null || state.selectedChannelLayout == null) {
			return;
		}

		/*
		 * Apply selected rank-icon X, width, and height.
		 * Right-side spacing is already included in sender/body geometry.
		 */
		boolean changed = setOriginalXIfChanged(rankIconWidget, state.selectedChannelLayout.rankIconX);
		changed |= setOriginalWidthIfChanged(rankIconWidget, state.selectedChannelLayout.rankIconWidth);
		changed |= setOriginalHeightIfChanged(rankIconWidget, state.selectedChannelLayout.rankIconHeight);

		/*
		 * Queue the independent rank-icon Y correction for finalize.
		 */
		if (fontProfile != null) {
			queueSpriteYOffset(
					rankIconWidget,
					state.nativeChannelLayout.rankIconSpriteId,
					fontProfile.getChannelRankIconYOffset());
		} else {
			pendingYOffsets.remove(rankIconWidget);
		}

		revalidateWidgetIfChanged(rankIconWidget, changed);
	}

	/*
	 * Queue text Y correction with a semantic-text identity guard.
	 */
	private void queueTextYOffset(Widget widget, int yOffset) {
		if (widget == null) {
			return;
		}

		if (yOffset == 0) {
			pendingYOffsets.remove(widget);
			return;
		}

		final String semantic = textNormalizer.normalizeSemantic(widget.getText());
		if (semantic == null || semantic.isEmpty()) {
			pendingYOffsets.remove(widget);
			return;
		}

		pendingYOffsets.put(widget, PendingYOffset.forText(semantic, yOffset));
	}

	/*
	 * Queue a delayed Y correction for a separate sprite widget.
	 */
	private void queueSpriteYOffset(Widget widget, int expectedSpriteId, int yOffset) {
		if (widget == null) {
			return;
		}

		if (yOffset == 0 || expectedSpriteId < 0) {
			pendingYOffsets.remove(widget);
			return;
		}

		pendingYOffsets.put(widget, PendingYOffset.forSprite(expectedSpriteId, yOffset));
	}

	/*
	 * Apply queued Y corrections only for Script 72 under CHATBOX_MESSAGE_LINES.
	 */
	private void applyPendingYOffsetsIfChatFinalize() {
		if (pendingYOffsets.isEmpty() || !isChatFinalizeInvocation()) {
			return;
		}

		for (Widget widget : pendingYOffsets.keySet()) {
			if (widget == null) {
				continue;
			}

			final PendingYOffset pendingOffset = pendingYOffsets.get(widget);
			if (pendingOffset == null || pendingOffset.yOffset == 0 || widget.isHidden()) {
				continue;
			}

			/*
			 * Every queued correction carries a lightweight identity guard.
			 *
			 * Text components must still contain the same semantic text.
			 * Separate rank widgets must still contain the same sprite.
			 */
			if (!pendingOffset.matches(widget, textNormalizer)) {
				continue;
			}

			applySynchronizedYOffset(widget, pendingOffset.yOffset);
		}

		/*
		 * Each queued correction belongs only to this finalized reconstruction
		 * cycle. Clearing here prevents cumulative offsets on later refreshes.
		 */
		pendingYOffsets.clear();
	}

	/*
	 * Script 72 is used in more than one client/interface lifecycle.
	 *
	 * The relevant chat invocation has the CHATBOX_MESSAGE_LINES widget ID
	 * as the penultimate integer-stack argument:
	 *
	 *     [..., messageContainerId, chatMessageLinesId, mode]
	 */
	private boolean isChatFinalizeInvocation() {
		final int[] intStack = client.getIntStack();
		final int intStackSize = client.getIntStackSize();
		if (intStack == null || intStackSize < 2 || intStackSize > intStack.length) {
			return false;
		}

		final Widget chatMessageLines = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
		if (chatMessageLines == null) {
			return false;
		}

		final int parentWidgetId = intStack[intStackSize - 2];
		return parentWidgetId == chatMessageLines.getId();
	}

	/**
	 * Applies a vertical offset while keeping OriginalY and RelativeY synchronized.
	 */
	@SuppressWarnings("deprecation")
	void applySynchronizedYOffset(Widget widget, int yOffset) {
		if (widget == null || yOffset == 0) {
			return;
		}

		final int previousOriginalY = widget.getOriginalY();
		final int previousRelativeY = widget.getRelativeY();
		final int adjustedY = previousOriginalY + yOffset;

		boolean changed = setOriginalYIfChanged(widget, adjustedY);
		changed |= setRelativeYIfChanged(widget, adjustedY);
		if (changed) {
			notifyIndexedWidgetGeometryChanged(widget, previousOriginalY, previousRelativeY);
		}
	}

	/*
	 * Refresh the selected font/profile pair only when configuration changes.
	 *
	 * This intentionally sits outside the supported construction hot path.
	 * PRE snapshots this state once and POST consumes that exact snapshot.
	 */
	public void refreshActiveFontState() {
		final ChatFont configuredFont = config != null
				? config.chatFont()
				: null;

		final ChatFont selectedChatFont = configuredFont != null
				? configuredFont
				: ChatFont.PLAIN_12;

		final ChatFontProfile fontProfile = ChatFontRegistry.get(selectedChatFont);
		if (fontProfile == null) {
			activeFontState = null;
			return;
		}

		final ActiveFontState current = activeFontState;
		if (current != null && current.chatFont == selectedChatFont && current.fontProfile == fontProfile) {
			return;
		}

		activeFontState = new ActiveFontState(selectedChatFont, fontProfile);
	}

	/*
	 * Package-private test seams.
	 *
	 * These expose only the state required by FontLayoutServiceTest and keep
	 * the test suite free of Java reflection. They do not alter runtime
	 * behavior or lifecycle ownership.
	 */
	ChatFont activeChatFontForTesting() {
		return activeFontState != null
				? activeFontState.chatFont
				: null;
	}

	ChatFontProfile activeFontProfileForTesting() {
		return activeFontState != null
				? activeFontState.fontProfile
				: null;
	}

	ChatFontProfile pendingFontProfileForTesting() {
		return pendingFontProfile;
	}

	void setPendingFontProfileForTesting(ChatFontProfile fontProfile) {
		pendingFontProfile = fontProfile;
	}

	/*
	 * ================================================================
	 * IDEMPOTENT WIDGET MUTATION / CONDITIONAL REVALIDATION
	 * ================================================================
	 */

	boolean setFontIdIfChanged(Widget widget, int fontId) {
		if (widget == null || widget.getFontId() == fontId) {
			return false;
		}

		final NativeWidgetState state = nativeState(widget);
		final int currentFontId = widget.getFontId();
		if (!state.fontIdCaptured || currentFontId != state.appliedFontId) {
			state.nativeFontId = currentFontId;

			state.fontIdCaptured = true;
		}

		state.appliedFontId = fontId;
		widget.setFontId(fontId);
		recordWidgetMutation();

		return true;
	}

	private boolean setLineHeightIfChanged(Widget widget, int lineHeight) {
		if (widget == null || widget.getLineHeight() == lineHeight) {
			return false;
		}

		final NativeWidgetState state = nativeState(widget);
		final int currentLineHeight = widget.getLineHeight();
		if (!state.lineHeightCaptured || currentLineHeight != state.appliedLineHeight) {
			state.nativeLineHeight = currentLineHeight;

			state.lineHeightCaptured = true;
		}

		state.appliedLineHeight = lineHeight;
		widget.setLineHeight(lineHeight);
		recordWidgetMutation();

		return true;
	}

