	private NativeWidgetState nativeState(Widget widget) {
		return nativeWidgetStates.computeIfAbsent(widget, ignored -> new NativeWidgetState());
	}

	private boolean sameText(String left, String right) {
		return left == null
				? right == null
				: left.equals(right);
	}

	private void recordWidgetMutation() {
		if (performanceMetrics != null) {
			performanceMetrics.recordWidgetMutation();
		}
	}

	void revalidateWidgetIfChanged(Widget widget, boolean changed) {
		if (widget == null || !changed) {
			return;
		}

		widget.revalidate();

		if (performanceMetrics != null) {
			performanceMetrics.recordRevalidate();
		}
	}

	/*
	 * ================================================================
	 * ROW CORRELATION
	 * ================================================================
	 */

	List<Widget> collectRow(Widget lineWidget, Surface surface) {
		if (lineWidget == null || surface == null) {
			return Collections.emptyList();
		}

		final RowCorrelationIndex rowIndex = rowIndexes.computeIfAbsent(
				surface, key ->
						new RowCorrelationIndex(client, key, performanceMetrics));

		final List<Widget> result = rowIndex.findRow(lineWidget);

		if (performanceMetrics != null) {
			performanceMetrics.recordRowSearches(result.size());
		}

		return result;
	}

	private void observeWidgetFromSurfaceScan(Surface surface, Widget root, Widget widget) {
		if (surface == null || root == null || widget == null) {
			return;
		}

		final RowCorrelationIndex rowIndex = rowIndexes.get(surface);
		if (rowIndex != null) {
			rowIndex.observeSurfaceWidget(root, widget);
		}
	}

	private void notifyIndexedWidgetGeometryChanged(Widget widget, int previousOriginalY, int previousRelativeY) {
		if (widget == null || rowIndexes.isEmpty()) {
			return;
		}

		for (RowCorrelationIndex rowIndex : rowIndexes.values()) {
			if (rowIndex != null) {
				rowIndex.onWidgetGeometryChangedByChatXl(widget, previousOriginalY, previousRelativeY);
			}
		}
	}

	private boolean containsIdentity(List<Widget> widgets, Widget target) {
		if (widgets == null || target == null) {
			return false;
		}

		for (Widget widget : widgets) {
			if (widget == target) {
				return true;
			}
		}

		return false;
	}

	private void removeIdentity(List<Widget> widgets, Widget target) {
		if (widgets == null || target == null) {
			return;
		}

		for (int i = widgets.size() - 1; i >= 0; i--) {
			if (widgets.get(i) == target) {
				widgets.remove(i);
			}
		}
	}

	private Widget matchRow(List<Widget> rowWidgets, String targetText, Widget excludedWidget) {
		if (rowWidgets == null || rowWidgets.isEmpty() || targetText == null) {
			return null;
		}

		Widget match = null;
		int matches = 0;

		for (Widget widget : rowWidgets) {
			if (widget == null || widget == excludedWidget) {
				continue;
			}

			final String semantic = textNormalizer.normalizeSemantic(widget.getText());
			if (semantic == null || !semantic.equalsIgnoreCase(targetText)) {
				continue;
			}

			match = widget;
			matches++;

			if (matches > 1) {
				return null;
			}
		}

		return matches == 1
				? match
				: null;
	}

	private Widget matchEmptyBodyRow(List<Widget> rowWidgets, int nativeBodyX) {
		if (rowWidgets == null || rowWidgets.isEmpty()) {
			return null;
		}

		Widget match = null;
		int matches = 0;

		for (Widget widget : rowWidgets) {
			if (widget == null || widget.getOriginalX() != nativeBodyX) {
				continue;
			}

			final String semantic = textNormalizer.normalizeSemantic(widget.getText());
			if (semantic == null || !semantic.isEmpty()) {
				continue;
			}

			match = widget;
			matches++;

			if (matches > 1) {
				return null;
			}
		}

		return matches == 1
				? match
				: null;
	}

	/*
	 * ================================================================
	 * BODY CORRELATION
	 * ================================================================
	 */

	Widget findTargetWidgetForLine(
			String targetText,
			Widget lineWidget,
			Surface surface,
			List<Widget> rowWidgets,
			FallbackCorrelationContext fallbackContext) {
		if (targetText == null || lineWidget == null || surface == null || fallbackContext == null) {
			return null;
		}

		final Widget rowMatch = matchRow(rowWidgets, targetText, null);
		if (rowMatch != null) {
			return rowMatch;
		}

		final List<Widget> matches = fallbackContext.findMatches(targetText);
		if (matches.isEmpty()) {
			return null;
		}

		/*
		 * Strongest match:
		 *
		 * same OriginalY + same RelativeY.
		 */
		for (Widget widget : matches) {
			if (widget.getOriginalY() == lineWidget.getOriginalY()
					&& widget.getRelativeY() == lineWidget.getRelativeY()) {
				return widget;
			}
		}

		/*
		 * Next strongest:
		 *
		 * unique OriginalY.
		 */
		Widget originalYMatch = null;
		int originalYMatches = 0;
		for (Widget widget : matches) {
			if (widget.getOriginalY() == lineWidget.getOriginalY()) {
				originalYMatch = widget;
				originalYMatches++;
			}
		}

		if (originalYMatches == 1) {
			return originalYMatch;
		}

		/*
		 * Next:
		 *
		 * unique RelativeY.
		 */
		Widget relativeYMatch = null;
		int relativeYMatches = 0;
		for (Widget widget : matches) {
			if (widget.getRelativeY() == lineWidget.getRelativeY()) {
				relativeYMatch = widget;
				relativeYMatches++;
			}
		}

		if (relativeYMatches == 1) {
			return relativeYMatch;
		}

		/*
		 * Final conservative fallback:
		 *
		 * exactly one semantic match on the entire surface.
		 */
		return matches.size() == 1
				? matches.get(0)
				: null;
	}

	/*
	 * ================================================================
	 * PREFIX CORRELATION
	 * ================================================================
	 */

	private List<Widget> findPrefixWidgetsForLine(
			List<String> rawPrefixComponents,
			Widget lineWidget,
			Surface surface,
			Widget bodyWidget,
			List<Widget> rowWidgets,
			FallbackCorrelationContext fallbackContext) {
		if (rawPrefixComponents == null
				|| rawPrefixComponents.isEmpty()
				|| lineWidget == null
				|| surface == null
				|| bodyWidget == null
				|| fallbackContext == null) {
			return Collections.emptyList();
		}

		final List<Widget> result = new ArrayList<>();

		for (String rawPrefix : rawPrefixComponents) {
			final String targetText = textNormalizer.normalizeSemantic(rawPrefix);
			if (targetText == null || targetText.isEmpty()) {
				continue;
			}

			final Widget rowMatch = matchRow(rowWidgets, targetText, bodyWidget);
			if (rowMatch != null && !containsIdentity(result, rowMatch)) {
				result.add(rowMatch);
				continue;
			}

			final List<Widget> matches = fallbackContext.findMatches(targetText);
			if (matches.isEmpty()) {
				continue;
			}

			Widget selected = null;

			/*
			 * Prefer the exact body row.
			 */
			for (Widget candidate : matches) {
				if (candidate == bodyWidget || containsIdentity(result, candidate)) {
					continue;
				}

				if (candidate.getOriginalY() == bodyWidget.getOriginalY()
						&& candidate.getRelativeY() == bodyWidget.getRelativeY()) {
					if (selected != null) {
						selected = null;
						break;
					}

					selected = candidate;
				}
			}

			if (selected == null) {
				/*
				 * Then prefer a unique OriginalY match.
				 */
				int originalYMatches = 0;

				for (Widget candidate : matches) {
					if (candidate == bodyWidget || containsIdentity(result, candidate)) {
						continue;
					}

					if (candidate.getOriginalY() == bodyWidget.getOriginalY()) {
						selected = candidate;

						originalYMatches++;
					}
				}

				if (originalYMatches != 1) {
					selected = null;
				}
			}

			if (selected == null) {
				/*
				 * Then prefer a unique RelativeY match.
				 */
				int relativeYMatches = 0;

				for (Widget candidate : matches) {
					if (candidate == bodyWidget || containsIdentity(result, candidate)) {
						continue;
					}

					if (candidate.getRelativeY() == bodyWidget.getRelativeY()) {
						selected = candidate;
						relativeYMatches++;
					}
				}

				if (relativeYMatches != 1) {
					selected = null;
				}
			}

			if (selected == null) {
				/*
				 * Final conservative fallback:
				 *
				 * exactly one remaining semantic match.
				 */
				Widget onlyRemaining = null;

				int remaining = 0;

				for (Widget candidate : matches) {
					if (candidate == bodyWidget || containsIdentity(result, candidate)) {
						continue;
					}

					onlyRemaining = candidate;
					remaining++;
				}

				if (remaining == 1) {
					selected = onlyRemaining;
				}
			}

			if (selected != null && !containsIdentity(result, selected)) {
				result.add(selected);
			}
		}

		return result;
	}

	/*
	 * ================================================================
	 * RANK ICON CORRELATION
	 * ================================================================
	 */

	Widget findRankIconWidget(
			FontMeasurementService.ChannelPrefixLayout nativeLayout,
			Widget rowAnchor,
			List<Widget> rowWidgets) {
		if (nativeLayout == null || rowAnchor == null || nativeLayout.rankIconSpriteId < 0) {
			return null;
		}

		if (performanceMetrics != null) {
			performanceMetrics.recordRankSearch();
		}

		/*
		 * First inspect the already-collected row.
		 *
		 * This remains the common path. The diagnostic counters below classify
		 * why this strict row-first lookup failed without changing its matching
		 * criteria.
		 */
		final Widget rowMatch = findRankIconWidgetInRow(nativeLayout, rowAnchor, rowWidgets);
		if (rowMatch != null) {
			return rowMatch;
		}

		final Widget root = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
		if (root == null) {
			if (performanceMetrics != null) {
				performanceMetrics.recordRankFallback();
				performanceMetrics.recordRankFallbackMiss();
			}

			return null;
		}

		/*
		 * Retry a missed rank lookup across the row index's shallow scan domain:
		 * root plus immediate dynamic/static/nested children.
		 */
		final Widget shallowMatch = findRankIconWidgetShallow(
				root,
				nativeLayout.rankIconSpriteId,
				nativeLayout.rankIconX,
				rowAnchor.getOriginalY(),
				rowAnchor.getRelativeY());

		if (shallowMatch != null) {
			if (performanceMetrics != null) {
				performanceMetrics.recordRankShallowRecovery();
			}

			observeWidgetFromSurfaceScan(Surface.CHATBOX, root, shallowMatch);

			return shallowMatch;
		}

		/*
		 * Preserve the recursive tree search as the final correctness fallback.
		 * RankFallback therefore continues to mean that the full-tree path was
		 * actually required.
		 */
		if (performanceMetrics != null) {
			performanceMetrics.recordRankFallback();
		}

		final Widget fallbackMatch = findRankIconWidgetRecursive(
				root,
				nativeLayout.rankIconSpriteId,
				nativeLayout.rankIconX,
				rowAnchor.getOriginalY(),
				rowAnchor.getRelativeY());

		if (performanceMetrics != null) {
			if (fallbackMatch != null) {
				performanceMetrics.recordRankFallbackHit();
			} else {
				performanceMetrics.recordRankFallbackMiss();
			}
		}

		/*
		 * Add a recursively found rank widget to the persistent row index.
		 */
		if (fallbackMatch != null) {
			observeWidgetFromSurfaceScan(Surface.CHATBOX, root, fallbackMatch);
		}

		return fallbackMatch;
	}

	private Widget findRankIconWidgetInRow(
			FontMeasurementService.ChannelPrefixLayout nativeLayout,
			Widget rowAnchor,
			List<Widget> rowWidgets) {
		boolean spriteMatched = false;
		boolean xMatched = false;

		if (rowWidgets == null || rowWidgets.isEmpty()) {
			if (performanceMetrics != null) {
				performanceMetrics.recordRankRowNoSprite();
			}

			return null;
		}

		for (Widget widget : rowWidgets) {
			if (widget == null) {
				continue;
			}

			if (performanceMetrics != null) {
				performanceMetrics.recordRankNodesExamined(1);
			}

			if (widget.getSpriteId() != nativeLayout.rankIconSpriteId) {
				continue;
			}

			spriteMatched = true;

			if (widget.getOriginalX() != nativeLayout.rankIconX) {
				continue;
			}

			xMatched = true;

			if (widget.getOriginalY() != rowAnchor.getOriginalY()
					&& widget.getRelativeY() != rowAnchor.getRelativeY()) {
				continue;
			}

			return widget;
		}

		if (performanceMetrics != null) {
			if (!spriteMatched) {
				performanceMetrics.recordRankRowNoSprite();
			} else if (!xMatched) {
				performanceMetrics.recordRankRowXMismatch();
			} else {
				performanceMetrics.recordRankRowYMismatch();
			}
		}

		return null;
	}

	private Widget findRankIconWidgetShallow(
			Widget root,
			int spriteId,
			int originalX,
			int originalY,
			int relativeY) {
		if (root == null) {
			return null;
		}

		Widget match = findRankIconWidgetCandidate(root, spriteId, originalX, originalY, relativeY);
		if (match != null) {
			return match;
		}

		match = findRankIconWidgetInShallowArray(root.getDynamicChildren(), spriteId, originalX, originalY, relativeY);
		if (match != null) {
			return match;
		}

		match = findRankIconWidgetInShallowArray(root.getStaticChildren(), spriteId, originalX, originalY, relativeY);
		if (match != null) {
			return match;
		}

		return findRankIconWidgetInShallowArray(root.getNestedChildren(), spriteId, originalX, originalY, relativeY);
	}

	private Widget findRankIconWidgetInShallowArray(
			Widget[] widgets,
			int spriteId,
			int originalX,
			int originalY,
			int relativeY) {
		if (widgets == null) {
			return null;
		}

		for (Widget widget : widgets) {
			final Widget match = findRankIconWidgetCandidate(widget, spriteId, originalX, originalY, relativeY);
			if (match != null) {
				return match;
			}
		}

		return null;
	}

	private Widget findRankIconWidgetCandidate(
			Widget widget,
			int spriteId,
			int originalX,
			int originalY,
			int relativeY) {
		if (widget == null) {
			return null;
		}

		if (performanceMetrics != null) {
			performanceMetrics.recordRankNodesExamined(1);
		}

		return widget.getSpriteId() == spriteId
				&& widget.getOriginalX() == originalX
				&& (widget.getOriginalY() == originalY
				|| widget.getRelativeY() == relativeY)
				? widget
				: null;
	}

	private Widget findRankIconWidgetRecursive(
			Widget widget,
			int spriteId,
			int originalX,
			int originalY,
			int relativeY) {
		if (widget == null) {
			return null;
		}

		if (performanceMetrics != null) {
			performanceMetrics.recordRankNodesExamined(1);
		}

		if (widget.getSpriteId()
				== spriteId
				&& widget.getOriginalX()
				== originalX
				&& (widget.getOriginalY() == originalY || widget.getRelativeY() == relativeY)) {
			return widget;
		}

		final Widget[] dynamicChildren = widget.getDynamicChildren();
		if (dynamicChildren != null) {
			for (Widget child : dynamicChildren) {
				final Widget result = findRankIconWidgetRecursive(child, spriteId, originalX, originalY, relativeY);
				if (result != null) {
					return result;
				}
			}
		}

		final Widget[] staticChildren = widget.getStaticChildren();
		if (staticChildren != null) {
			for (Widget child : staticChildren) {
				final Widget result = findRankIconWidgetRecursive(child, spriteId, originalX, originalY, relativeY);
				if (result != null) {
					return result;
				}
			}
		}

		final Widget[] nestedChildren = widget.getNestedChildren();
		if (nestedChildren != null) {
			for (Widget child : nestedChildren) {
				final Widget result = findRankIconWidgetRecursive(child, spriteId, originalX, originalY, relativeY);
				if (result != null) {
					return result;
				}
			}
		}

		return null;
	}

	/*
	 * ================================================================
	 * FALLBACK CORRELATION
	 * ================================================================
	 */

	final class FallbackCorrelationContext {
		private final Surface surface;

		private Map<String, List<Widget>> widgetsBySemantic;

		FallbackCorrelationContext(Surface surface) {
			this.surface = surface;
		}

		List<Widget> findMatches(String targetText) {
			if (targetText == null || targetText.isEmpty() || surface == null) {
				return Collections.emptyList();
			}

			if (performanceMetrics != null) {
				performanceMetrics.recordFallbackSearch();
			}

			if (widgetsBySemantic == null) {
				buildIndex();

				if (performanceMetrics != null) {
					performanceMetrics.recordFallbackBuild();
				}
			} else if (performanceMetrics != null) {
				performanceMetrics.recordFallbackReuse();
			}

			final List<Widget> matches = widgetsBySemantic.get(semanticKey(targetText));
			return matches != null
					? matches
					: Collections.emptyList();
		}

		private void buildIndex() {
			widgetsBySemantic = new HashMap<>();

			final Widget root = surface == Surface.SPLIT_PRIVATE
					? client.getWidget(InterfaceID.PM_CHAT, 0)
					: client.getWidget(InterfaceID.Chatbox.SCROLLAREA);

			if (root == null) {
				return;
			}

			if (performanceMetrics != null) {
				performanceMetrics.recordSurfaceSearch();
			}

			indexWidget(root, root);
			indexWidgets(root, root.getDynamicChildren());
			indexWidgets(root, root.getStaticChildren());
			indexWidgets(root, root.getNestedChildren());
		}

		private void indexWidgets(Widget root, Widget[] widgets) {
			if (widgets == null) {
				return;
			}

			for (Widget widget : widgets) {
				indexWidget(root, widget);
			}
		}

		private void indexWidget(Widget root, Widget widget) {
			if (widget == null) {
				return;
			}

			if (performanceMetrics != null) {
				performanceMetrics.recordWidgetsExamined(1);
			}

			/*
			 * A complete fallback scan has already paid the enumeration cost.
			 * Teach the persistent row index about every widget encountered,
			 * including textless sprite widgets such as channel rank icons.
			 */
			observeWidgetFromSurfaceScan(surface, root, widget);

			final String semantic = textNormalizer.normalizeSemantic(widget.getText());
			if (semantic == null || semantic.isEmpty()) {
				return;
			}

			widgetsBySemantic.computeIfAbsent(semanticKey(semantic), ignored -> new ArrayList<>()).add(widget);
		}

		private String semanticKey(String text) {
			return text.toLowerCase(Locale.ROOT);
		}
	}

	/*
	 * ================================================================
	 * SURFACE
	 * ================================================================
	 */

	private Surface determineSurface(int parentWidgetId) {
		return WidgetUtil.componentToInterface(parentWidgetId) == InterfaceID.PM_CHAT
				? Surface.SPLIT_PRIVATE
				: Surface.CHATBOX;
	}

	/*
	 * ================================================================
	 * LIFECYCLE
	 * ================================================================
	 */

	@SuppressWarnings("deprecation")
	public void restoreNativePresentation() {
		if (nativeWidgetStates.isEmpty()) {
			return;
		}

		for (Map.Entry<Widget, NativeWidgetState> entry : nativeWidgetStates.entrySet()) {
			final Widget widget = entry.getKey();
			final NativeWidgetState state = entry.getValue();
			if (widget == null || state == null) {
				continue;
			}

			boolean changed = false;

			/*
			 * Restore a field only when it still equals Chat XL's last-applied value.
			 */
			if (state.fontIdCaptured
					&& widget.getFontId()
					== state.appliedFontId
					&& widget.getFontId()
					!= state.nativeFontId) {
				widget.setFontId(state.nativeFontId);
				changed = true;
			}

			if (state.lineHeightCaptured
					&& widget.getLineHeight()
					== state.appliedLineHeight
					&& widget.getLineHeight()
					!= state.nativeLineHeight) {
				widget.setLineHeight(state.nativeLineHeight);
				changed = true;
			}

			if (state.yTextAlignmentCaptured
					&& widget.getYTextAlignment()
					== state.appliedYTextAlignment
					&& widget.getYTextAlignment()
					!= state.nativeYTextAlignment) {
				widget.setYTextAlignment(state.nativeYTextAlignment);
				changed = true;
			}

			if (state.textCaptured
					&& sameText(widget.getText(), state.appliedText)
					&& !sameText(widget.getText(), state.nativeText)) {
				widget.setText(state.nativeText);
				changed = true;
			}

			if (state.originalXCaptured
					&& widget.getOriginalX()
					== state.appliedOriginalX
					&& widget.getOriginalX()
					!= state.nativeOriginalX) {
				widget.setOriginalX(state.nativeOriginalX);
				changed = true;
			}

			if (state.originalYCaptured
					&& widget.getOriginalY()
					== state.appliedOriginalY
					&& widget.getOriginalY()
					!= state.nativeOriginalY) {
				widget.setOriginalY(state.nativeOriginalY);
				changed = true;
			}

			if (state.relativeYCaptured
					&& widget.getRelativeY()
					== state.appliedRelativeY
					&& widget.getRelativeY()
					!= state.nativeRelativeY) {
				widget.setRelativeY(state.nativeRelativeY);
				changed = true;
			}

			if (state.originalWidthCaptured
					&& widget.getOriginalWidth()
					== state.appliedOriginalWidth
					&& widget.getOriginalWidth()
					!= state.nativeOriginalWidth) {
				widget.setOriginalWidth(state.nativeOriginalWidth);
				changed = true;
			}

			if (state.originalHeightCaptured
					&& widget.getOriginalHeight()
					== state.appliedOriginalHeight
					&& widget.getOriginalHeight()
					!= state.nativeOriginalHeight) {
				widget.setOriginalHeight(state.nativeOriginalHeight);
				changed = true;
			}

			if (changed) {
				widget.revalidate();
			}
		}

		nativeWidgetStates.clear();
	}

	public void reset() {
		pending = null;
		pendingFontProfile = null;
		pendingYOffsets.clear();
		rowIndexes.clear();
	}

	/*
	 * Native and last-applied presentation values captured per field
	 * for one Widget identity.
	 */
	private static final class NativeWidgetState {
		private boolean fontIdCaptured;
		private int nativeFontId;
		private int appliedFontId;

		private boolean lineHeightCaptured;
		private int nativeLineHeight;
		private int appliedLineHeight;

		private boolean yTextAlignmentCaptured;
		private int nativeYTextAlignment;
		private int appliedYTextAlignment;

		private boolean textCaptured;
		private String nativeText;
		private String appliedText;

		private boolean originalXCaptured;
		private int nativeOriginalX;
		private int appliedOriginalX;

		private boolean originalYCaptured;
		private int nativeOriginalY;
		private int appliedOriginalY;

		private boolean relativeYCaptured;
		private int nativeRelativeY;
		private int appliedRelativeY;

		private boolean originalWidthCaptured;
		private int nativeOriginalWidth;
		private int appliedOriginalWidth;

		private boolean originalHeightCaptured;
		private int nativeOriginalHeight;
		private int appliedOriginalHeight;
	}

	/*
	 * Immutable configured font/profile pair.
	 */
	private static final class ActiveFontState {
		private final ChatFont chatFont;
		private final ChatFontProfile fontProfile;

		private ActiveFontState(ChatFont chatFont, ChatFontProfile fontProfile) {
			this.chatFont = chatFont;
			this.fontProfile = fontProfile;
		}
	}

	/*
	 * One delayed component-specific Y correction.
	 *
	 * Text corrections retain expected semantic text.
	 * Sprite corrections retain an expected sprite ID.
	 *
	 * Exactly one guard is populated for each instance.
	 */
	private static final class PendingYOffset {
		private final String expectedSemanticText;
		private final int expectedSpriteId;
		private final int yOffset;

		private PendingYOffset(String expectedSemanticText, int expectedSpriteId, int yOffset) {
			this.expectedSemanticText = expectedSemanticText;
			this.expectedSpriteId = expectedSpriteId;
			this.yOffset = yOffset;
		}

		private static PendingYOffset forText(String expectedSemanticText, int yOffset) {
			return new PendingYOffset(expectedSemanticText, -1, yOffset);
		}

		private static PendingYOffset forSprite(int expectedSpriteId, int yOffset) {
			return new PendingYOffset(null, expectedSpriteId, yOffset);
		}

		private boolean matches(Widget widget, ChatTextNormalizer textNormalizer) {
			if (widget == null) {
				return false;
			}

			if (expectedSpriteId >= 0) {
				return widget.getSpriteId() == expectedSpriteId;
			}

			if (expectedSemanticText == null) {
				return false;
			}

			final String currentSemanticText = textNormalizer.normalizeSemantic(widget.getText());
			return currentSemanticText != null && currentSemanticText.equalsIgnoreCase(expectedSemanticText);
		}
	}

	enum Surface {
		CHATBOX,
		SPLIT_PRIVATE
	}
}

package com.bigboldchat.chat;

import com.bigboldchat.chat.FontLayoutService.Surface;
import com.bigboldchat.debug.PerformanceMetrics;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * Persistent shallow row index for one chat surface.
 *
 * Indexes the root and immediate dynamic/static/nested children by RowKey,
 * supports local repair, and watches Chat XL-adjusted widgets for row changes.
 */
final class RowCorrelationIndex {
	private final Client client;
	private final Surface surface;
	private final PerformanceMetrics performanceMetrics;

	private Widget indexedRoot;

	private Map<RowKey, List<Widget>> widgetsByRow;
	private IdentityHashMap<Widget, RowKey> rowByWidget;

	private final IdentityHashMap<Widget, WatchedRowMove> watchedMoves = new IdentityHashMap<>();
	private final Map<RowKey, List<Widget>> watchedWidgetsByPreviousRow = new HashMap<>();

	RowCorrelationIndex(Client client, Surface surface, PerformanceMetrics performanceMetrics) {
		this.client = client;
		this.surface = surface;
		this.performanceMetrics = performanceMetrics;
	}

	List<Widget> findRow(Widget lineWidget) {
		if (lineWidget == null || surface == null) {
			return Collections.emptyList();
		}

		final Widget root = surface == Surface.SPLIT_PRIVATE
				? client.getWidget(InterfaceID.PM_CHAT, 0)
				: client.getWidget(InterfaceID.Chatbox.SCROLLAREA);

		if (root == null) {
			clear();
			return Collections.emptyList();
		}

		final RowKey targetRow = RowKey.of(lineWidget);

		boolean rebuilt = false;
		boolean repaired = false;

		if (widgetsByRow == null || rowByWidget == null || indexedRoot != root) {
			build(root);
			rebuilt = true;
		} else {
			repaired |= repairWatchedWidgetsForRow(targetRow); // Repair watched widgets that returned to this row.

			final RowKey indexedAnchorRow = rowByWidget.get(lineWidget);
			if (indexedAnchorRow == null) {
				/*
				 * A new line-widget object appeared after the last index
				 * build. We cannot discover its sibling candidates without
				 * enumerating the surface once.
				 */
				build(root);
				rebuilt = true;
			} else if (!indexedAnchorRow.equals(targetRow)) {
				// Re-key the moved anchor row and its known siblings.
				repaired |= repairRow(indexedAnchorRow);
			}
		}

		if (!rebuilt) {
			/*
			 * Validate only the requested bucket. Outgoing recycled
			 * candidates are moved to their current row without touching
			 * unrelated rows or walking the complete surface.
			 */
			repaired |= repairRow(targetRow);
		}

		List<Widget> candidates = widgetsByRow.get(targetRow);

		/*
		 * The exact line widget must be present in its requested bucket.
		 * If not, local knowledge is insufficient and one complete build
		 * remains the conservative correctness fallback.
		 */
		if (!rebuilt && !containsIdentity(candidates, lineWidget)) {
			build(root);
			rebuilt = true;
			candidates = widgetsByRow.get(targetRow);
		}

		if (performanceMetrics != null) {
			if (rebuilt) {
				performanceMetrics.recordRowIndexBuild();
			} else if (repaired) {
				performanceMetrics.recordRowIndexRepair();
			} else {
				performanceMetrics.recordRowIndexReuse();
			}
		}

		return candidates != null
				? candidates
				: Collections.emptyList();
	}

	private boolean repairRow(RowKey indexedRow) {
		if (indexedRow == null || widgetsByRow == null || rowByWidget == null) {
			return false;
		}

		final List<Widget> indexedWidgets = widgetsByRow.get(indexedRow);
		if (indexedWidgets == null || indexedWidgets.isEmpty()) {
			return false;
		}

		final List<Widget> snapshot = new ArrayList<>(indexedWidgets);

		boolean repaired = false;

		for (Widget widget : snapshot) {
			if (widget == null) {
				continue;
			}

			recordRowWidgetExamined();

			final RowKey currentRow = RowKey.of(widget);
			final RowKey recordedRow = rowByWidget.get(widget);
			if (recordedRow == null) {
				/*
				 * This should not occur for a healthy index. Keep the
				 * reverse mapping internally consistent without a scan.
				 */
				rowByWidget.put(widget, currentRow);

				if (!indexedRow.equals(currentRow)) {
					removeWidgetFromRow(widget, indexedRow);
					addWidgetToRow(widget, currentRow);
					repaired = true;
				}

				continue;
			}

			if (!recordedRow.equals(currentRow)) {
				moveIndexedWidget(widget, recordedRow, currentRow);
				reconcileWatchedMoveAfterExternalGeometryChange(widget, currentRow);
				repaired = true;
			}
		}

		return repaired;
	}

	private boolean repairWatchedWidgetsForRow(RowKey requestedRow) {
		if (requestedRow == null || rowByWidget == null) {
			return false;
		}

		final List<Widget> watchedWidgets = watchedWidgetsByPreviousRow.get(requestedRow);
		if (watchedWidgets == null || watchedWidgets.isEmpty()) {
			return false;
		}

		final List<Widget> snapshot = new ArrayList<>(watchedWidgets);

		boolean repaired = false;

		for (Widget widget : snapshot) {
			if (widget == null) {
				continue;
			}

			final WatchedRowMove watchedMove = watchedMoves.get(widget);
			if (watchedMove == null || !requestedRow.equals(watchedMove.previousRow)) {
				removeWatchedMove(widget);
				continue;
			}

			final RowKey recordedRow = rowByWidget.get(widget);
			if (recordedRow == null) {
				removeWatchedMove(widget);
				continue;
			}

			recordRowWidgetExamined();

			final RowKey currentRow = RowKey.of(widget);
			if (!recordedRow.equals(currentRow)) {
				moveIndexedWidget(widget, recordedRow, currentRow);
				repaired = true;
			}

			// Stop watching once the widget leaves the Chat XL-adjusted row.
			if (!watchedMove.adjustedRow.equals(currentRow)) {
				removeWatchedMove(widget);
			}
		}

		return repaired;
	}

	void observeSurfaceWidget(Widget root, Widget widget) {
		if (root == null
				|| widget == null
				|| indexedRoot != root
				|| widgetsByRow == null
				|| rowByWidget == null) {
			return;
		}

		final RowKey currentRow = RowKey.of(widget);
		final RowKey recordedRow = rowByWidget.get(widget);
		if (recordedRow == null) {
			addWidgetToRow(widget, currentRow);
			rowByWidget.put(widget, currentRow);
			return;
		}

		if (!recordedRow.equals(currentRow)) {
			moveIndexedWidget(widget, recordedRow, currentRow);
			reconcileWatchedMoveAfterExternalGeometryChange(widget, currentRow);
		}
	}

	void onWidgetGeometryChangedByChatXl(Widget widget, int previousOriginalY, int previousRelativeY) {
		if (widget == null || rowByWidget == null) {
			return;
		}

		final RowKey previousRow = new RowKey(previousOriginalY, previousRelativeY);
		final RowKey recordedRow = rowByWidget.get(widget);
		if (recordedRow == null) {
			return;
		}

		final RowKey adjustedRow = RowKey.of(widget);
		if (!recordedRow.equals(adjustedRow)) {
			moveIndexedWidget(widget, recordedRow, adjustedRow);
		}

		if (!previousRow.equals(adjustedRow)) {
			watchMove(widget, previousRow, adjustedRow);
		}
	}

	private void moveIndexedWidget(Widget widget, RowKey oldRow, RowKey newRow) {
		if (widget == null || newRow == null || rowByWidget == null || widgetsByRow == null) {
			return;
		}

		if (oldRow != null) {
			removeWidgetFromRow(widget, oldRow);
		}

		addWidgetToRow(widget, newRow);
		rowByWidget.put(widget, newRow);
	}

	private void addWidgetToRow(Widget widget, RowKey row) {
		if (widget == null || row == null || widgetsByRow == null) {
			return;
		}

		final List<Widget> widgets = widgetsByRow.computeIfAbsent(row, ignored -> new ArrayList<>());
		if (!containsIdentity(widgets, widget)) {
			widgets.add(widget);
		}
	}

	private void removeWidgetFromRow(Widget widget, RowKey row) {
		if (widget == null || row == null || widgetsByRow == null) {
			return;
		}

		final List<Widget> widgets = widgetsByRow.get(row);
		if (widgets == null) {
			return;
		}

		removeIdentity(widgets, widget);

		if (widgets.isEmpty()) {
			widgetsByRow.remove(row);
		}
	}

	private void watchMove(Widget widget, RowKey previousRow, RowKey adjustedRow) {
		if (widget == null || previousRow == null || adjustedRow == null) {
			return;
		}

		removeWatchedMove(widget);
		watchedMoves.put(widget, new WatchedRowMove(previousRow, adjustedRow));

		final List<Widget> watchedWidgets = watchedWidgetsByPreviousRow.computeIfAbsent(
				previousRow, ignored -> new ArrayList<>());
		if (!containsIdentity(watchedWidgets, widget)) {
			watchedWidgets.add(widget);
		}
	}

	private void reconcileWatchedMoveAfterExternalGeometryChange(Widget widget, RowKey currentRow) {
		final WatchedRowMove watchedMove = watchedMoves.get(widget);
		if (watchedMove == null || currentRow == null) {
			return;
		}

		if (!watchedMove.adjustedRow.equals(currentRow)) {
			removeWatchedMove(widget);
		}
	}

	private void removeWatchedMove(Widget widget) {
		if (widget == null) {
			return;
		}

		final WatchedRowMove watchedMove = watchedMoves.remove(widget);
		if (watchedMove == null) {
			return;
		}

		final List<Widget> watchedWidgets = watchedWidgetsByPreviousRow.get(watchedMove.previousRow);
		if (watchedWidgets == null) {
			return;
		}

		removeIdentity(watchedWidgets, widget);

		if (watchedWidgets.isEmpty()) {
			watchedWidgetsByPreviousRow.remove(watchedMove.previousRow);
		}
	}

	private void build(Widget root) {
		indexedRoot = root;
		widgetsByRow = new HashMap<>();
		rowByWidget = new IdentityHashMap<>();

		indexWidget(root);
		indexWidgets(root.getDynamicChildren());
		indexWidgets(root.getStaticChildren());
		indexWidgets(root.getNestedChildren());
		pruneWatchedMovesAfterBuild();
	}

	private void indexWidgets(Widget[] widgets) {
		if (widgets == null) {
			return;
		}

		for (Widget widget : widgets) {
			indexWidget(widget);
		}
	}

	private void indexWidget(Widget widget) {
		if (widget == null) {
			return;
		}

		recordRowWidgetExamined();

		final RowKey row = RowKey.of(widget);
		addWidgetToRow(widget, row);
		rowByWidget.put(widget, row);
	}

	private void pruneWatchedMovesAfterBuild() {
		if (watchedMoves.isEmpty() || rowByWidget == null) {
			return;
		}

		final List<Widget> watchedWidgets = new ArrayList<>(watchedMoves.keySet());

		for (Widget widget : watchedWidgets) {
			final WatchedRowMove watchedMove = watchedMoves.get(widget);
			final RowKey indexedRow = rowByWidget.get(widget);
			if (watchedMove == null || indexedRow == null || !watchedMove.adjustedRow.equals(indexedRow)) {
				removeWatchedMove(widget);
			}
		}
	}

	private void clear() {
		indexedRoot = null;
		widgetsByRow = null;
		rowByWidget = null;

		watchedMoves.clear();
		watchedWidgetsByPreviousRow.clear();
	}

	private void recordRowWidgetExamined() {
		if (performanceMetrics != null) {
			performanceMetrics.recordWidgetsExamined(1);
		}
	}

	private boolean containsIdentity(List<Widget> widgets, Widget target) {
		if (widgets == null || target == null) {
			return false;
		}

		for (Widget widget : widgets) {
			if (widget == target) {
				return true;
			}
		}

		return false;
	}

	private void removeIdentity(List<Widget> widgets, Widget target) {
		if (widgets == null || target == null) {
			return;
		}

		for (int i = widgets.size() - 1; i >= 0; i--) {
			if (widgets.get(i) == target) {
				widgets.remove(i);
			}
		}
	}

	private static final class WatchedRowMove {
		private final RowKey previousRow;
		private final RowKey adjustedRow;

		private WatchedRowMove(RowKey previousRow, RowKey adjustedRow) {
			this.previousRow = previousRow;
			this.adjustedRow = adjustedRow;
		}
	}

	private static final class RowKey {
		private final int originalY;
		private final int relativeY;

		private RowKey(int originalY, int relativeY) {
			this.originalY = originalY;
			this.relativeY = relativeY;
		}

		private static RowKey of(Widget widget) {
			return new RowKey(widget.getOriginalY(), widget.getRelativeY());
		}

		@Override
		public boolean equals(Object other) {
			if (this == other) {
				return true;
			}

			if (!(other instanceof RowKey)) {
				return false;
			}

			final RowKey rowKey = (RowKey) other;
			return originalY == rowKey.originalY && relativeY == rowKey.relativeY;
		}

		@Override
		public int hashCode() {
			int result = originalY;
			result = 31 * result + relativeY;

			return result;
		}
	}
}

package com.bigboldchat.chat;

import com.bigboldchat.debug.PerformanceMetrics;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

import net.runelite.client.util.Text;

/**
 * Normalizes chat text for semantic comparison and font measurement.
 */
public final class ChatTextNormalizer {
	private static final Pattern LINE_BREAK_PATTERN = Pattern.compile("<br\\s*/?>", Pattern.CASE_INSENSITIVE);
	private static final Pattern IMAGE_PATTERN = Pattern.compile("<img=(\\d+)>", Pattern.CASE_INSENSITIVE);
	private static final Pattern AT_PATTERN = Pattern.compile("<at>", Pattern.CASE_INSENSITIVE);

	// Optional performance instrumentation; null when unavailable.
	private final PerformanceMetrics performanceMetrics;

	public ChatTextNormalizer() {
		this(null);
	}

	public ChatTextNormalizer(PerformanceMetrics performanceMetrics) {
		this.performanceMetrics = performanceMetrics;
	}

	String normalizeSemantic(String text) {
		final long started = performanceMetrics != null && performanceMetrics.isEnabled()
				? System.nanoTime()
				: 0L;

		try {
			if (text == null) {
				return null;
			}

			/*
			 * Most chat text contains no markup.
			 */
			if (text.indexOf('<') < 0) {
				final String normalized = text.indexOf('\u00A0') >= 0
						? text.replace('\u00A0', ' ')
						: text;

				return normalized.trim();
			}

			final String withLineBreaks = LINE_BREAK_PATTERN.matcher(text).replaceAll("\n");
			final String withVisibleAtCharacters = AT_PATTERN.matcher(withLineBreaks).replaceAll("@");
			final String semantic = Text.removeTags(withVisibleAtCharacters).replace('\u00A0', ' ').trim();
			if (!semantic.isEmpty()) {
				return semantic;
			}

			// Keep image-only messages identifiable after markup is removed.
			return extractImages(withVisibleAtCharacters);
		} finally {
			if (performanceMetrics != null && performanceMetrics.isEnabled()) {
				performanceMetrics.recordNormalization(System.nanoTime() - started);
			}
		}
	}

	String measureSemantic(String text) {
		final long started = performanceMetrics != null && performanceMetrics.isEnabled()
				? System.nanoTime()
				: 0L;

		try {
			if (text == null) {
				return null;
			}

			/*
			 * Keep inline image markup for font measurement.
			 */
			if (text.indexOf('<') < 0) {
				final String normalized = text.indexOf('\u00A0') >= 0
						? text.replace('\u00A0', ' ')
						: text;

				return normalized.trim();
			}

			final String withLineBreaks = LINE_BREAK_PATTERN.matcher(text).replaceAll("\n");
			final String withVisibleAtCharacters = AT_PATTERN.matcher(withLineBreaks).replaceAll("@");
			return withVisibleAtCharacters.replace('\u00A0', ' ').trim();
		} finally {
			if (performanceMetrics != null && performanceMetrics.isEnabled()) {
				performanceMetrics.recordNormalization(
						System.nanoTime()
								- started);
			}
		}
	}

	String renderText(String text) {
		if (text == null || text.indexOf('<') < 0) {
			return text;
		}

		return AT_PATTERN.matcher(text).replaceAll("@");
	}

	/*
	 * HELPERS
	 */

	private String extractImages(String text) {
		if (text == null || text.isEmpty()) {
			return "";
		}

		final Matcher matcher = IMAGE_PATTERN.matcher(text);
		final StringBuilder images = new StringBuilder();
		while (matcher.find()) {
			images.append("<img=").append(matcher.group(1)).append('>');
		}

		return images.toString();
	}
}

package com.bigboldchat.config;

import com.bigboldchat.chat.FontLayoutService;
import com.bigboldchat.debug.PerformanceMetrics;

import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.events.ConfigChanged;

/**
 * Owns chat-font configuration changes.
 */
public final class FontConfigHandler {
	private static final String CONFIG_GROUP = "bigboldchat";
	private static final String FONT_KEY = "chatFont";

	private final Client client;
	private final ClientThread clientThread;
	private final FontLayoutService layoutService;
	private final PerformanceMetrics performanceMetrics;

	private volatile boolean active = true;

	public FontConfigHandler(
			Client client,
			ClientThread clientThread,
			FontLayoutService layoutService,
			PerformanceMetrics performanceMetrics) {
		this.client = client;
		this.clientThread = clientThread;
		this.layoutService = layoutService;
		this.performanceMetrics = performanceMetrics;
	}

	public boolean onConfigChanged(ConfigChanged event) {
		if (!active || event == null || !CONFIG_GROUP.equals(event.getGroup()) || !FONT_KEY.equals(event.getKey())) {
			return false;
		}

		if (layoutService != null) {
			layoutService.refreshActiveFontState();
			layoutService.reset();
		}

		if (performanceMetrics != null) {
			performanceMetrics.recordRefreshChat(PerformanceMetrics.RefreshReason.FONT_CHANGED);
		}

		clientThread.invokeLater(() -> {
			if (active) {
				client.refreshChat();
			}
		});

		return true;
	}

	public void deactivate() {
		active = false;
	}
}

package com.bigboldchat.config;

import com.bigboldchat.chatbox.ChatRebuildCoordinator;

import net.runelite.client.events.ConfigChanged;

/**
 * Owns chatbox configuration changes.
 */
public final class ChatboxConfigHandler {
	private static final String CONFIG_GROUP = "bigboldchat";
	private static final String WIDTH_KEY = "chatboxWidth";
	private static final String HEIGHT_KEY = "chatboxHeight";
	private static final String BUTTONS_KEY = "hideChatboxButtons";

	private final ChatRebuildCoordinator rebuildCoordinator;

	private volatile boolean active = true;

	public ChatboxConfigHandler(ChatRebuildCoordinator rebuildCoordinator) {
		this.rebuildCoordinator = rebuildCoordinator;
	}

	public boolean onConfigChanged(ConfigChanged event) {
		if (!active || event == null || !CONFIG_GROUP.equals(event.getGroup())) {
			return false;
		}

		if (BUTTONS_KEY.equals(event.getKey())) {
			if (rebuildCoordinator != null) {
				rebuildCoordinator.onButtonsChanged();
			}
			return true;
		}

		if (!WIDTH_KEY.equals(event.getKey()) && !HEIGHT_KEY.equals(event.getKey())) {
			return false;
		}

		if (rebuildCoordinator != null) {
			rebuildCoordinator.onConfiguredSizeChanged();
		}

		return true;
	}

	public void deactivate() {
		active = false;
	}
}

