public enum ChatboxLayout {
	FIXED,
	RESIZABLE_CLASSIC,
	RESIZABLE_MODERN,
	UNKNOWN
}

package com.bigboldchat.chatbox;

import com.bigboldchat.debug.PerformanceMetrics;
import com.bigboldchat.layout.ChatboxBounds;
import com.bigboldchat.layout.SideContainerLayout;

import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetSizeMode;

/**
 * Owns resizable-layout chatbox geometry and presentation.
 */
public final class ChatboxResizeService {
	/*
	 * Native chat view values.
	 */
	private static final int CHAT_VIEW_ALL = 0;
	private static final int CHAT_VIEW_HIDDEN = 1337;

	/*
	 * Native chat visibility lifecycle.
	 */
	static final int CHAT_VISIBILITY = 923;

	/*
	 * Native chat and top-level relayout helpers.
	 */
	private static final int CHAT_ONCHATTRANSMIT = 663;
	private static final int TOPLEVEL_RELAYOUT = 1972;

	private static final int[] CHAT_CONTROL_IDS = {
			InterfaceID.Chatbox.CHAT_ALL,
			InterfaceID.Chatbox.CHAT_GAME,
			InterfaceID.Chatbox.CHAT_PUBLIC,
			InterfaceID.Chatbox.CHAT_PRIVATE,
			InterfaceID.Chatbox.CHAT_FRIENDSCHAT,
			InterfaceID.Chatbox.CHAT_CLAN,
			InterfaceID.Chatbox.CHAT_TRADE
	};

	private static final int[] CHAT_CONTROL_GRAPHIC_IDS = {
			InterfaceID.Chatbox.CHAT_ALL_GRAPHIC,
			InterfaceID.Chatbox.CHAT_GAME_GRAPHIC,
			InterfaceID.Chatbox.CHAT_PUBLIC_GRAPHIC,
			InterfaceID.Chatbox.CHAT_PRIVATE_GRAPHIC,
			InterfaceID.Chatbox.CHAT_FRIENDSCHAT_GRAPHIC,
			InterfaceID.Chatbox.CHAT_CLAN_GRAPHIC,
			InterfaceID.Chatbox.CHAT_TRADE_GRAPHIC
	};

	private final Client client;
	private final PerformanceMetrics performanceMetrics;
	private final ChatboxControlsLayout controlsLayout;
	private final ChatboxBackgroundService backgroundService;
	private final SideContainerLayout sideContainerLayout;

	private boolean resizedLayoutApplied;
	private boolean foregroundSuppressionActive;
	private boolean foregroundSuppressionOverridden;
	private boolean manualSuppressionActive;
	private boolean suppressionOwnsHiddenView;
	private boolean chatControlClickPending;
	private boolean chatboxButtonsHidden;
	private boolean liveWidthChanged;
	private boolean liveHeightChanged;
	private boolean liveWidthRefreshPending;
	private boolean liveHeightRefreshPending;

	private int liveDepth;
	private int lastVisibleChatView = CHAT_VIEW_ALL;
	private int lastVisibleChatGraphic = -1;

	private ScrollBaseline liveBaseline;

	public ChatboxResizeService(Client client, PerformanceMetrics performanceMetrics) {
		this.client = client;
		this.performanceMetrics = performanceMetrics;
		this.controlsLayout = new ChatboxControlsLayout(client);
		this.backgroundService = new ChatboxBackgroundService(client);
		this.sideContainerLayout = new SideContainerLayout(client);
	}

	/*
	 * ================================================================
	 * LAYOUT
	 * ================================================================
	 */
	ChatboxLayout getLayout() {
		final int topLevel = client.getTopLevelInterfaceId();
		if (topLevel == InterfaceID.TOPLEVEL) {
			return ChatboxLayout.FIXED;
		}

		if (topLevel == InterfaceID.TOPLEVEL_OSRS_STRETCH) {
			return ChatboxLayout.RESIZABLE_CLASSIC;
		}

		if (topLevel == InterfaceID.TOPLEVEL_PRE_EOC) {
			return ChatboxLayout.RESIZABLE_MODERN;
		}

		return ChatboxLayout.UNKNOWN;
	}

	private Widget getSlot(ChatboxLayout layout) {
		switch (layout) {
			case RESIZABLE_CLASSIC:
				return client.getWidget(InterfaceID.ToplevelOsrsStretch.CHAT_CONTAINER);
			case RESIZABLE_MODERN:
				return client.getWidget(InterfaceID.ToplevelPreEoc.CHAT_CONTAINER);
			case FIXED:
				return client.getWidget(InterfaceID.Toplevel.CHAT_CONTAINER);
			default:
				return null;
		}
	}

	/*
	 * ================================================================
	 * SCRIPT LIFECYCLE
	 * ================================================================
	 */
	public ResizeResult onScriptPreFired(ScriptPreFired event, int width, int height) {
		if (event == null) {
			return ResizeResult.NOT_APPLIED;
		}

		final int scriptId = event.getScriptId();

		/*
		 * Discard any queued plugin refresh so a native
		 * rebuild never causes a duplicate refresh.
		 */
		if (scriptId == CHAT_ONCHATTRANSMIT || scriptId == ScriptID.SPLITPM_CHANGED) {
			liveWidthRefreshPending = false;
			liveHeightRefreshPending = false;
		}

		if (scriptId == ScriptID.TOPLEVEL_RESIZE_CUSTOMISE) {
			sideContainerLayout.beginNativeLayout();
		}

		if (scriptId == TOPLEVEL_RELAYOUT) {
			beginLiveScroll();

			final ResizeResult result = applySize(width, height);
			if (result.isApplied()) {
				/*
				 * Native relayout can fire repeatedly while an interface is moving. Track
				 * only real geometry changes so one render-boundary refresh can rebuild
				 * retained rows without feeding geometry back through the commit queue.
				 */
				liveWidthChanged |= result.isWidthChanged();
				liveHeightChanged |= result.isHeightChanged();
			}

			return result;
		}

		if (scriptId == ScriptID.SPLITPM_CHANGED) {
			return applySize(width, height);
		}

		if (scriptId == ScriptID.BUILD_CHATBOX) {
			return applySize(width, height);
		}

		return ResizeResult.NOT_APPLIED;
	}

	public ResizeResult onScriptPostFired(ScriptPostFired event, int width, int height) {
		if (event == null) {
			return ResizeResult.NOT_APPLIED;
		}

		final int scriptId = event.getScriptId();
		if (scriptId == CHAT_VISIBILITY) {
			rememberVisibleChatView();
			syncChatAreaVisibility();
			recordMutations(controlsLayout.syncHidden(chatboxButtonsHidden));
		}

		if (scriptId == ScriptID.TOPLEVEL_RESIZE_CUSTOMISE) {
			sideContainerLayout.endNativeLayout();
		}

		if (scriptId == TOPLEVEL_RELAYOUT) {
			finishLiveScroll();
			return ResizeResult.NOT_APPLIED;
		}

		if (scriptId == ScriptID.TOPLEVEL_REDRAW
				|| scriptId == ScriptID.TOPLEVEL_RESIZE_CUSTOMISE
				|| scriptId == ScriptID.MESSAGE_LAYER_OPEN) {
			return applySize(width, height);
		}

		return ResizeResult.NOT_APPLIED;
	}

	/*
	 * ================================================================
	 * CHATBOX GEOMETRY
	 * ================================================================
	 */
	public ResizeResult applySize(int width, int height) {
		final long started = performanceMetrics != null && performanceMetrics.isEnabled()
				? System.nanoTime()
				: 0L;
		final ChatboxLayout layout = getLayout();
		final Widget chatArea = client.getWidget(InterfaceID.Chatbox.CHATAREA);

		recordMutations(controlsLayout.syncHidden(chatboxButtonsHidden));

		if (layout == ChatboxLayout.FIXED || layout == ChatboxLayout.UNKNOWN) {
			syncChatPresentation(false);
			sideContainerLayout.reset();
			resizedLayoutApplied = false;
			return ResizeResult.NOT_APPLIED;
		}

		final Widget slot = getSlot(layout);
		final Widget universe = client.getWidget(InterfaceID.Chatbox.UNIVERSE);
		if (slot == null || universe == null || chatArea == null) {
			recordMissingWidgets();
			return ResizeResult.NOT_APPLIED;
		}

		/*
		 * Ignore transient layout swaps before UNIVERSE mounts under the active chat container.
		 */
		final Widget parent = universe.getParent();
		if (parent == null || parent.getId() != slot.getId()) {
			return ResizeResult.NOT_APPLIED;
		}

		if (layout == ChatboxLayout.RESIZABLE_MODERN) {
			final SideContainerLayout.Result sideResult = sideContainerLayout.apply(slot, width, height);

			recordMutations(sideResult.getMutations());
			recordRevalidates(sideResult.getRevalidates());
		} else {
			sideContainerLayout.reset();
		}

		/*
		 * Clamp live geometry without changing configured dimensions.
		 */
		final ChatboxBounds.Result effective = ChatboxBounds.resolve(client, slot, width, height, chatboxButtonsHidden);
		final int effectiveWidth = effective.getWidth();
		final int effectiveHeight = effective.getHeight();
		final int effectiveBodyHeight = ChatboxGeometry.bodyHeight(effectiveHeight, chatboxButtonsHidden);
		final boolean widthChanged = slot.getWidth() != effectiveWidth
				|| universe.getWidth() != effectiveWidth || chatArea.getWidth() != effectiveWidth;
		final boolean heightChanged = slot.getHeight() != effectiveHeight
				|| universe.getHeight() != effectiveHeight || chatArea.getHeight() != effectiveBodyHeight;
		final boolean controlsChanged = !controlsLayout.matches(effectiveWidth);

		if (widthChanged || heightChanged || controlsChanged) {
			applyGeometry(
					slot, universe, chatArea, effectiveWidth, effectiveHeight, effectiveBodyHeight, controlsChanged);
		}

		final ChatboxBackgroundService.Result backgroundResult =
				backgroundService.apply(chatArea, effectiveWidth, effectiveBodyHeight);

		recordMutations(backgroundResult.getMutations());
		recordRevalidates(backgroundResult.getRevalidates());

		syncChatPresentation(backgroundService.isOpaque() && effective.isForegroundOverlap());

		resizedLayoutApplied = true;

		recordApply(started, widthChanged, heightChanged);

		return new ResizeResult(true, widthChanged, heightChanged);
	}

	private void applyGeometry(
			Widget slot,
			Widget universe,
			Widget chatArea,
			int width,
			int height,
			int bodyHeight,
			boolean controlsChanged) {
		if (slot.getWidth() != width || slot.getHeight() != height) {
			slot.setSize(width, height);
			recordMutation();

			slot.revalidate();
			recordRevalidate();
		}

		if (universe.getWidth() != width || universe.getHeight() != height) {
			universe.setSize(width, height, WidgetSizeMode.ABSOLUTE, WidgetSizeMode.ABSOLUTE);
			universe.setForcedPosition(0, 0);
			recordMutation();

			universe.revalidate();
			recordRevalidate();
		}

		final int bodyMargin = Math.max(0, height - bodyHeight);
		if (chatArea.getOriginalWidth() != width
				|| chatArea.getOriginalHeight() != bodyMargin || chatArea.getHeightMode() != WidgetSizeMode.MINUS) {
			chatArea.setSize(width, bodyMargin, chatArea.getWidthMode(), WidgetSizeMode.MINUS);
			recordMutation();
		}

		if (controlsChanged) {
			recordMutations(controlsLayout.apply(width));
		}

		recordRevalidates(ChatboxWidgets.revalidateChildren(universe));
	}

	/*
	 * ================================================================
	 * SCROLL BASELINE
	 * ================================================================
	 */
	private void beginLiveScroll() {
		if (liveDepth++ != 0) {
			return;
		}

		liveBaseline = captureScrollBaseline();
		liveWidthChanged = false;
		liveHeightChanged = false;
	}

	private void finishLiveScroll() {
		if (liveDepth <= 0) {
			return;
		}

		liveDepth--;
		if (liveDepth != 0) {
			return;
		}

		final ScrollBaseline baseline = liveBaseline;
		final boolean widthChanged = liveWidthChanged;
		final boolean heightChanged = liveHeightChanged;
		liveBaseline = null;
		liveWidthChanged = false;
		liveHeightChanged = false;

		if (widthChanged || heightChanged) {
			restoreScrollBaseline(baseline, true);

			/*
			 * Defer reconstruction until the render boundary.
			 */
			liveWidthRefreshPending |= widthChanged;
			liveHeightRefreshPending |= heightChanged;
		}
	}

	public LiveRefresh consumeLiveRefresh() {
		if (liveDepth != 0 || !liveWidthRefreshPending && !liveHeightRefreshPending) {
			return null;
		}

		final LiveRefresh refresh = new LiveRefresh(liveWidthRefreshPending, liveHeightRefreshPending);

		liveWidthRefreshPending = false;
		liveHeightRefreshPending = false;
		return refresh;
	}

	public ScrollBaseline captureScrollBaseline() {
		final Widget scrollArea = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
		if (scrollArea == null) {
			return null;
		}

		final int scrollY = Math.max(0, scrollArea.getScrollY());
		final int height = Math.max(0, scrollArea.getHeight());
		final int bottom = Math.max(0, scrollArea.getScrollHeight() - height);
		final ScrollPosition position;

		if (bottom == 0 || scrollY >= bottom) {
			position = ScrollPosition.BOTTOM;
		} else if (scrollY == 0) {
			position = ScrollPosition.TOP;
		} else {
			position = ScrollPosition.MIDDLE;
		}

		return new ScrollBaseline(position, scrollY + height);
	}

	public void restoreScrollBaseline(ScrollBaseline baseline) {
		restoreScrollBaseline(baseline, false);
	}

	void restoreRebuildScroll(ScrollBaseline baseline) {
		restoreScrollBaseline(baseline, true);
	}

	private void restoreScrollBaseline(ScrollBaseline baseline, boolean reanchor) {
		if (baseline == null) {
			return;
		}

		final Widget scrollArea = client.getWidget(InterfaceID.Chatbox.SCROLLAREA);
		if (scrollArea == null) {
			return;
		}

		final int height = Math.max(0, scrollArea.getHeight());
		if (reanchor && baseline.position != ScrollPosition.TOP) {
			reanchorScrollBottom(scrollArea, height);
		}

		final int scrollHeight = Math.max(0, scrollArea.getScrollHeight());
		final int bottom = Math.max(0, scrollHeight - height);
		final int target;

		switch (baseline.position) {
			case TOP:
				target = 0;
				break;
			case BOTTOM:
				target = bottom;
				break;
			case MIDDLE:
				target = Math.max(0, Math.min(bottom, baseline.viewportBottom - height));
				break;
			default:
				return;
		}

		if (scrollArea.getScrollY() != target) {
			scrollArea.setScrollY(target);
		}

		client.setVarcIntValue(VarClientID.CHAT_LASTSCROLLPOS, target);
		client.setVarcIntValue(VarClientID.CHAT_LASTSCROLLSIZE, scrollArea.getScrollHeight());
	}

	private void reanchorScrollBottom(Widget scrollArea, int height) {
		final int shift = height - scrollArea.getScrollHeight();
		if (shift <= 0) {
			return;
		}

		shiftScrollChildren(scrollArea.getStaticChildren(), shift);
		shiftScrollChildren(scrollArea.getDynamicChildren(), shift);
		scrollArea.setScrollHeight(height);
		recordMutation();
	}

	private void shiftScrollChildren(Widget[] children, int shift) {
		if (children == null) {
			return;
		}

		for (Widget child : children) {
			if (child == null || child.getHeight() <= 0) {
				continue;
			}

			child.setOriginalY(child.getOriginalY() + shift);
			recordMutation();

			child.revalidate();
			recordRevalidate();
		}
	}

	/*
	 * ================================================================
	 * PRESENTATION
	 * ================================================================
	 */
	private void syncChatPresentation(boolean foregroundSuppression) {
		rememberVisibleChatView();

		if (foregroundSuppression != foregroundSuppressionActive) {
			foregroundSuppressionActive = foregroundSuppression;
			foregroundSuppressionOverridden = false;
		}

		/*
		 * Defer presentation sync during native chat-control processing.
		 */
		if (chatControlClickPending) {
			syncChatAreaVisibility();
			return;
		}

		if (isSuppressionRequested()) {
			hideNativeChatView();
			return;
		}

		restoreOwnedChatView();
		syncChatAreaVisibility();
	}

	public void setChatboxButtonsHidden(boolean hidden) {
		chatboxButtonsHidden = hidden;
		recordMutations(controlsLayout.syncHidden(hidden));
	}

	public void toggleChatPresentation() {
		if (isChatViewHidden()) {
			showChatPresentation();
			return;
		}

		rememberVisibleChatView();

		manualSuppressionActive = true;
		hideNativeChatView();
	}

	public void showChatPresentation() {
		manualSuppressionActive = false;

		if (foregroundSuppressionActive) {
			foregroundSuppressionOverridden = true;
		}

		if (!isChatViewHidden()) {
			suppressionOwnsHiddenView = false;
			rememberVisibleChatView();
			syncChatAreaVisibility();
			return;
		}

		suppressionOwnsHiddenView = false;
		setNativeChatView(lastVisibleChatView);
	}

	public boolean onChatControlClicked(Widget widget) {
		if (findChatControl(widget) == -1) {
			return false;
		}

		chatControlClickPending = true;
		return true;
	}

	public void finishChatControlClick() {
		if (!chatControlClickPending) {
			return;
		}

		chatControlClickPending = false;
		manualSuppressionActive = false;
		suppressionOwnsHiddenView = false;

		if (foregroundSuppressionActive) {
			foregroundSuppressionOverridden = !isChatViewHidden();
		}

		rememberVisibleChatView();

		if (!isChatViewHidden()) {
			rememberVisibleChatGraphic();
		}

		syncChatAreaVisibility();
	}

	private int findChatControl(Widget widget) {
		for (Widget current = widget; current != null; current = current.getParent()) {
			final int id = current.getId();

			for (int controlId : CHAT_CONTROL_IDS) {
				if (id == controlId) {
					return controlId;
				}
			}
		}

		return -1;
	}

	private void hideNativeChatView() {
		final int chatView = client.getVarcIntValue(VarClientID.CHAT_VIEW);
		if (chatView == CHAT_VIEW_HIDDEN) {
			syncChatAreaVisibility();
			return;
		}

		lastVisibleChatView = chatView;
		suppressionOwnsHiddenView = true;

		setNativeChatView(CHAT_VIEW_HIDDEN);
	}

	private void restoreOwnedChatView() {
		if (!suppressionOwnsHiddenView) {
			return;
		}

		suppressionOwnsHiddenView = false;
		setNativeChatView(lastVisibleChatView);
	}

	private void rememberVisibleChatView() {
		final int chatView = client.getVarcIntValue(VarClientID.CHAT_VIEW);
		if (chatView != CHAT_VIEW_HIDDEN) {
			lastVisibleChatView = chatView;
		}
	}

	private void rememberVisibleChatGraphic() {
		for (int graphicId : CHAT_CONTROL_GRAPHIC_IDS) {
			final Widget graphic = client.getWidget(graphicId);
			if (graphic == null) {
				continue;
			}

			final int spriteId = graphic.getSpriteId();
			if (spriteId == SpriteID.ChatTabButton.SELECTED || spriteId == SpriteID.ChatTabButton.SELECTED_HOVERED) {
				lastVisibleChatGraphic = graphicId;
				return;
			}
		}
	}

	private void syncStoredChatGraphic(boolean selected) {
		if (lastVisibleChatGraphic == -1) {
			return;
		}

		final Widget graphic = client.getWidget(lastVisibleChatGraphic);
		if (graphic == null) {
			return;
		}

		final int currentSprite = graphic.getSpriteId();
		final int targetSprite;

		if (selected) {
			targetSprite = currentSprite == SpriteID.ChatTabButton.HOVERED
					? SpriteID.ChatTabButton.SELECTED_HOVERED
					: SpriteID.ChatTabButton.SELECTED;
		} else {
			targetSprite = currentSprite == SpriteID.ChatTabButton.SELECTED_HOVERED
					? SpriteID.ChatTabButton.HOVERED
					: SpriteID.ChatTabButton.BUTTON;
		}

		if (currentSprite == targetSprite) {
			return;
		}

		graphic.setSpriteId(targetSprite);
		recordMutation();
	}

	boolean isChatViewHidden() {
		return client.getVarcIntValue(VarClientID.CHAT_VIEW) == CHAT_VIEW_HIDDEN;
	}

	private void setNativeChatView(int chatView) {
		final int currentChatView = client.getVarcIntValue(VarClientID.CHAT_VIEW);
		if (currentChatView == chatView) {
			syncChatAreaVisibility();
			return;
		}

		if (chatView == CHAT_VIEW_HIDDEN) {
			rememberVisibleChatGraphic();
		}

		client.setVarcIntValue(VarClientID.CHAT_VIEW, chatView);

		if (performanceMetrics != null) {
			performanceMetrics.recordRefreshChat(PerformanceMetrics.RefreshReason.OTHER);
		}

		client.refreshChat();

		syncChatAreaVisibility();
		syncStoredChatGraphic(chatView != CHAT_VIEW_HIDDEN);
	}

	private void syncChatAreaVisibility() {
		setChatAreaHidden(isChatViewHidden());
	}

	private void setChatAreaHidden(boolean hidden) {
		final Widget chatArea = client.getWidget(InterfaceID.Chatbox.CHATAREA);
		if (chatArea == null || chatArea.isSelfHidden() == hidden) {
			return;
		}

		chatArea.setHidden(hidden);
		recordMutation();
	}

	private boolean isSuppressionRequested() {
		return manualSuppressionActive || foregroundSuppressionActive && !foregroundSuppressionOverridden;
	}

	private void resetChatPresentation() {
		chatControlClickPending = false;
		manualSuppressionActive = false;
		foregroundSuppressionActive = false;
		foregroundSuppressionOverridden = false;

		restoreOwnedChatView();
		syncChatAreaVisibility();
	}

	/*
	 * ================================================================
	 * RESTORATION
	 * ================================================================
	 */
	public void restoreNativeSize() {
		resetChatPresentation();
		recordMutations(controlsLayout.restoreHidden());

		final boolean wasApplied = resizedLayoutApplied;
		final ChatboxLayout layout = getLayout();

		if (layout == ChatboxLayout.FIXED || layout == ChatboxLayout.UNKNOWN) {
			sideContainerLayout.reset();
			resizedLayoutApplied = false;
			return;
		}

		if (layout == ChatboxLayout.RESIZABLE_MODERN) {
			final SideContainerLayout.Result sideResult = sideContainerLayout.restoreNative();

			recordMutations(sideResult.getMutations());
			recordRevalidates(sideResult.getRevalidates());
		} else {
			sideContainerLayout.reset();
		}

		final Widget slot = getSlot(layout);
		final Widget universe = client.getWidget(InterfaceID.Chatbox.UNIVERSE);
		if (slot == null || universe == null) {
			resizedLayoutApplied = false;
			return;
		}

		slot.setSize(ChatboxGeometry.NATIVE_WIDTH, ChatboxGeometry.NATIVE_SLOT_HEIGHT);
		slot.setForcedPosition(-1, -1);
		recordMutation();

		slot.revalidate();
		recordRevalidate();

		restoreNativeUniverse(universe);

		final Widget chatArea = client.getWidget(InterfaceID.Chatbox.CHATAREA);
		if (chatArea != null) {
			chatArea.setSize(
					ChatboxGeometry.NATIVE_WIDTH,
					ChatboxGeometry.NATIVE_TAB_HEIGHT,
					chatArea.getWidthMode(),
					WidgetSizeMode.MINUS);
			recordMutation();
		}

		recordMutations(controlsLayout.restoreNative());
		recordRevalidates(ChatboxWidgets.revalidateChildren(universe));

		final ChatboxBackgroundService.Result backgroundResult = backgroundService.restore(chatArea);

		recordMutations(backgroundResult.getMutations());
		recordRevalidates(backgroundResult.getRevalidates());

		resizedLayoutApplied = false;

		if (wasApplied && performanceMetrics != null) {
			performanceMetrics.recordResizeRestore();
		}
	}

	@SuppressWarnings("deprecation")
	private void restoreNativeUniverse(Widget universe) {
		universe.setSize(0, 0, WidgetSizeMode.MINUS, WidgetSizeMode.MINUS);
		universe.setForcedPosition(-1, -1);
		recordMutation();

		universe.revalidate();
		recordRevalidate();

		universe.setWidth(ChatboxGeometry.NATIVE_WIDTH);
		universe.setHeight(ChatboxGeometry.NATIVE_SLOT_HEIGHT);
		recordMutation();
	}

	/*
	 * ================================================================
	 * PERFORMANCE HELPERS
	 * ================================================================
	 */
	private void recordApply(long started, boolean widthChanged, boolean heightChanged) {
		if (performanceMetrics == null || !performanceMetrics.isEnabled()) {
			return;
		}

		performanceMetrics.recordResizeApply(System.nanoTime() - started, widthChanged, heightChanged);
	}

	private void recordMissingWidgets() {
		if (performanceMetrics != null) {
			performanceMetrics.recordResizeMissingWidgets();
		}
	}

	private void recordMutation() {
		if (performanceMetrics != null) {
			performanceMetrics.recordWidgetMutation();
		}
	}

	private void recordMutations(int count) {
		if (performanceMetrics == null || count <= 0) {
			return;
		}

		for (int i = 0; i < count; i++) {
			performanceMetrics.recordWidgetMutation();
		}
	}

	private void recordRevalidate() {
		if (performanceMetrics != null) {
			performanceMetrics.recordRevalidate();
		}
	}

	private void recordRevalidates(int count) {
		if (performanceMetrics == null || count <= 0) {
			return;
		}

		for (int i = 0; i < count; i++) {
			performanceMetrics.recordRevalidate();
		}
	}

	private enum ScrollPosition {
		TOP,
		BOTTOM,
		MIDDLE
	}

	public static final class ScrollBaseline {
		private final ScrollPosition position;
		private final int viewportBottom;

		private ScrollBaseline(ScrollPosition position, int viewportBottom) {
			this.position = position;
			this.viewportBottom = viewportBottom;
		}
	}

	public static final class LiveRefresh {
		private final boolean widthChanged;
		private final boolean heightChanged;

		private LiveRefresh(boolean widthChanged, boolean heightChanged) {
			this.widthChanged = widthChanged;
			this.heightChanged = heightChanged;
		}

		public boolean isWidthChanged() {
			return widthChanged;
		}

		public boolean isHeightChanged() {
			return heightChanged;
		}
	}

	public static final class ResizeResult {
		private static final ResizeResult NOT_APPLIED =
				new ResizeResult(false, false, false);

		private final boolean applied;
		private final boolean widthChanged;
		private final boolean heightChanged;

		private ResizeResult(boolean applied, boolean widthChanged, boolean heightChanged) {
			this.applied = applied;
			this.widthChanged = widthChanged;
			this.heightChanged = heightChanged;
		}

		public boolean isApplied() {
			return applied;
		}

		public boolean isWidthChanged() {
			return widthChanged;
		}

		public boolean isHeightChanged() {
			return heightChanged;
		}
	}
}

package com.bigboldchat.chatbox;

import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * Targeted widget-tree helpers for the chatbox.
 */
final class ChatboxWidgets {
	private ChatboxWidgets() {
	}

	/**
	 * Revalidate mounted chatbox descendants without walking nested
	 * interfaces or descending through the scroll area.
	 *
	 * @return number of widgets revalidated
	 */
	static int revalidateChildren(Widget widget) {
		if (widget == null) {
			return 0;
		}

		return revalidateAll(widget.getStaticChildren()) + revalidateAll(widget.getDynamicChildren());
	}

	private static int revalidateAll(Widget[] children) {
		if (children == null) {
			return 0;
		}

		int count = 0;

		for (Widget child : children) {
			if (child == null) {
				continue;
			}

			child.revalidate();

			count++;

			if (child.getId() == InterfaceID.Chatbox.SCROLLAREA) {
				continue;
			}

			count += revalidateChildren(child);
		}

		return count;
	}
}

package com.bigboldchat.chatbox;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;

/**
 * Owns chat control/tab bar geometry and visibility.
 */
public final class ChatboxControlsLayout {
	private static final int TAB_NATIVE_WIDTH = 56;

	private static final int[] TAB_NATIVE_X = {
			458,
			396,
			334,
			272,
			210,
			148,
			86
	};

	private static final int[] TAB_COMPONENTS = {
			InterfaceID.Chatbox.CHAT_ALL,
			InterfaceID.Chatbox.CHAT_GAME,
			InterfaceID.Chatbox.CHAT_PUBLIC,
			InterfaceID.Chatbox.CHAT_PRIVATE,
			InterfaceID.Chatbox.CHAT_FRIENDSCHAT,
			InterfaceID.Chatbox.CHAT_CLAN,
			InterfaceID.Chatbox.CHAT_TRADE
	};

	private final Client client;

	private Widget hiddenControls;
	private boolean nativeControlsHidden;

	public ChatboxControlsLayout(Client client) {
		this.client = client;
	}

	/**
	 * Apply the control bar width and native-width tab positions.
	 *
	 * @return number of widget fields mutated
	 */
	int apply(int width) {
		int mutations = 0;

		final Widget controls = client.getWidget(InterfaceID.Chatbox.CONTROLS);
		final Widget background = client.getWidget(InterfaceID.Chatbox.CONTROLS_BACKGROUND_GRAPHIC);

		if (controls != null && controls.getOriginalWidth() != width) {
			controls.setOriginalWidth(width);
			mutations++;
		}

		if (background != null && background.getOriginalWidth() != width) {
			background.setOriginalWidth(width);
			mutations++;
		}

		final Widget[] tabs = getReadyTabs();
		if (tabs == null) {
			return mutations;
		}

		final int widthDelta = width - ChatboxGeometry.NATIVE_WIDTH;
		final int tabCount = tabs.length;

		for (int i = 0; i < tabCount; i++) {
			final Widget tab = tabs[i];
			final int targetX = spreadX(i, widthDelta, tabCount);

			if (tab.getOriginalWidth() != TAB_NATIVE_WIDTH) {
				tab.setOriginalWidth(TAB_NATIVE_WIDTH);
				mutations++;
			}

			if (tab.getOriginalX() != targetX) {
				tab.setOriginalX(targetX);
				mutations++;
			}
		}

		return mutations;
	}

	int syncHidden(boolean hidden) {
		final Widget controls = client.getWidget(InterfaceID.Chatbox.CONTROLS);
		if (controls == null) {
			return 0;
		}

		if (!hidden) {
			return restoreHidden(controls);
		}

		if (hiddenControls != controls) {
			hiddenControls = controls;
			nativeControlsHidden = controls.isSelfHidden();
		}

		if (controls.isSelfHidden()) {
			return 0;
		}

		controls.setHidden(true);
		return 1;
	}

	int restoreHidden() {
		final Widget controls = client.getWidget(InterfaceID.Chatbox.CONTROLS);
		return restoreHidden(controls);
	}

	int restoreNative() {
		return apply(ChatboxGeometry.NATIVE_WIDTH);
	}

	boolean matches(int width) {
		final Widget controls = client.getWidget(InterfaceID.Chatbox.CONTROLS);
		final Widget background = client.getWidget(InterfaceID.Chatbox.CONTROLS_BACKGROUND_GRAPHIC);

		if (controls != null && controls.getWidth() != width) {
			return false;
		}

		if (background != null && background.getWidth() != width) {
			return false;
		}

		final Widget[] tabs = getReadyTabs();
		if (tabs == null) {
			return true;
		}

		final int widthDelta = width - ChatboxGeometry.NATIVE_WIDTH;
		final int tabCount = tabs.length;

		for (int i = 0; i < tabCount; i++) {
			final Widget tab = tabs[i];
			if (tab.getOriginalWidth() != TAB_NATIVE_WIDTH || tab.getOriginalX() != spreadX(i, widthDelta, tabCount)) {
				return false;
			}
		}

		return true;
	}

	private int restoreHidden(Widget controls) {
		if (hiddenControls == null) {
			return 0;
		}

		if (controls != hiddenControls) {
			hiddenControls = null;
			return 0;
		}

		int mutations = 0;
		if (controls.isSelfHidden() != nativeControlsHidden) {
			controls.setHidden(nativeControlsHidden);
			mutations++;
		}

		hiddenControls = null;
		return mutations;
	}

	private Widget[] getReadyTabs() {
		final Widget[] tabs = new Widget[TAB_COMPONENTS.length];

		for (int i = 0; i < TAB_COMPONENTS.length; i++) {
			final Widget tab = client.getWidget(TAB_COMPONENTS[i]);
			if (tab == null || tab.getXPositionMode() != WidgetPositionMode.ABSOLUTE_RIGHT) {
				return null;
			}

			tabs[i] = tab;
		}

		return tabs;
	}

	private static int spreadX(int index, int widthDelta, int tabCount) {
		return TAB_NATIVE_X[index] + widthDelta * (tabCount - index) / tabCount;
	}
}

package com.bigboldchat.chatbox;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.api.widgets.WidgetType;

/**
 * Owns resizable chatbox background and frame geometry.
 *
 * Opaque chat stretches the parchment while preserving its baked bevel.
 * Transparent chat redistributes its gradient bands across the chat body.
 */
final class ChatboxBackgroundService {
	private static final int BAKED_BORDER = 8;
	private static final int CORNER_BLEED_TRIM = 1;
	private static final int CORNER_SIZE = 32;
	private static final int BORDER_OFFSET = 12;

	private static final int[] BORDER_SPRITES = {
			SpriteID.V2StoneBorders.SIDE_PANEL_CORNER_TOP_LEFT,
			SpriteID.V2StoneBorders.SIDE_PANEL_CORNER_TOP_RIGHT,
			SpriteID.V2StoneBorders.SIDE_PANEL_CORNER_BOTTOM_LEFT,
			SpriteID.V2StoneBorders.SIDE_PANEL_CORNER_BOTTOM_RIGHT,
			SpriteID.V2StoneBorders.SIDE_PANEL_EDGE_TOP,
			SpriteID.V2StoneBorders.SIDE_PANEL_EDGE_LEFT,
			SpriteID.V2StoneBorders.SIDE_PANEL_EDGE_BOTTOM,
			SpriteID.V2StoneBorders.SIDE_PANEL_EDGE_RIGHT
	};

	private final Client client;

	private Widget[] borderPieces;
	private Widget trimmedBackground;
	private Widget zoomedBody;
	private int zoomedBodyOriginalWidth;
	private int zoomedBodyOriginalHeight;
	private int zoomedBodyWidthMode;
	private int zoomedBodyHeightMode;
	private boolean zoomedBodySpriteTiling;

	ChatboxBackgroundService(Client client) {
		this.client = client;
	}

	boolean isOpaque() {
		final Widget background = client.getWidget(InterfaceID.Chatbox.CHAT_BACKGROUND);
		return background != null && isParchment(getBackgroundBody(background));
	}

	/*
	 * ================================================================
	 * BACKGROUND
	 * ================================================================
	 */

	Result apply(Widget chatArea, int width, int bodyHeight) {
		final Result result = new Result();
		final Widget background = client.getWidget(InterfaceID.Chatbox.CHAT_BACKGROUND);
		if (background == null) {
			result.add(syncFrame(chatArea, null));
			return result;
		}

		final Widget body = getBackgroundBody(background);
		if (isParchment(body)) {
			result.add(zoomParchment(body, width, bodyHeight));
			result.add(trimBackground(background));
			result.add(syncFrame(chatArea, body));
			return result;
		}

		result.add(restoreZoom(body));
		result.add(restoreTrim(background));
		result.add(stackGradientBands(background, bodyHeight));
		result.add(removeFrame(chatArea));

		return result;
	}

	Result restore(Widget chatArea) {
		final Result result = new Result();
		final Widget background = client.getWidget(InterfaceID.Chatbox.CHAT_BACKGROUND);
		final Widget body = background != null
				? getBackgroundBody(background)
				: null;

		result.add(removeFrame(chatArea));

		if (background == null) {
			trimmedBackground = null;
			zoomedBody = null;
			return result;
		}

		result.add(restoreTrim(background));
		result.add(restoreZoom(body));

		if (!isParchment(body)) {
			result.add(stackGradientBands(background, ChatboxGeometry.NATIVE_BODY_HEIGHT));
		}

		return result;
	}

	private Result zoomParchment(Widget body, int targetWidth, int targetHeight) {
		final Result result = new Result();
		final int overscanX = bevelOverscan(targetWidth, ChatboxGeometry.NATIVE_WIDTH);
		final int overscanY = bevelOverscan(targetHeight, ChatboxGeometry.NATIVE_BODY_HEIGHT);
		final int width = targetWidth + overscanX * 2;
		final int height = targetHeight + overscanY * 2;
		final int x = body.getOriginalX() - overscanX;
		final int y = body.getOriginalY() - overscanY;
		boolean changed = false;

		if (zoomedBody != body) {
			rememberZoomState(body);
		}

		if (body.getOriginalWidth() != width || body.getOriginalHeight() != height
				|| body.getWidthMode() != WidgetSizeMode.ABSOLUTE || body.getHeightMode() != WidgetSizeMode.ABSOLUTE) {
			body.setSize(width, height, WidgetSizeMode.ABSOLUTE, WidgetSizeMode.ABSOLUTE);
			result.mutations++;
			changed = true;
		}

		if (body.getRelativeX() != x || body.getRelativeY() != y) {
			body.setForcedPosition(x, y);
			result.mutations++;
			changed = true;
		}

		if (body.getSpriteTiling()) {
			body.setSpriteTiling(false);
			result.mutations++;
			changed = true;
		}

		if (changed) {
			body.revalidate();
			result.revalidates++;
		}

		return result;
	}

	private Result trimBackground(Widget background) {
		final Result result = new Result();
		boolean changed = false;

		if (background.getOriginalWidth() != CORNER_BLEED_TRIM || background.getOriginalHeight() != CORNER_BLEED_TRIM) {
			background.setSize(CORNER_BLEED_TRIM, CORNER_BLEED_TRIM);
			result.mutations++;
			changed = true;
		}

		if (background.getRelativeX() != 0 || background.getRelativeY() != CORNER_BLEED_TRIM) {
			background.setForcedPosition(0, CORNER_BLEED_TRIM);
			result.mutations++;
			changed = true;
		}

		if (changed) {
			background.revalidate();
			result.revalidates++;
		}

		trimmedBackground = background;
		return result;
	}

	private Result restoreTrim(Widget background) {
		final Result result = new Result();

		if (trimmedBackground != background) {
			trimmedBackground = null;
			return result;
		}

		background.setSize(0, 0);
		background.setForcedPosition(-1, -1);
		background.revalidate();

		result.mutations += 2;
		result.revalidates++;
		trimmedBackground = null;

		return result;
	}

	private Result restoreZoom(Widget currentBody) {
		final Result result = new Result();

		if (zoomedBody == null) {
			return result;
		}

		if (zoomedBody != currentBody) {
			clearZoomState();
			return result;
		}

		zoomedBody.setSize(zoomedBodyOriginalWidth, zoomedBodyOriginalHeight, zoomedBodyWidthMode, zoomedBodyHeightMode);
		zoomedBody.setForcedPosition(-1, -1);
		zoomedBody.setSpriteTiling(zoomedBodySpriteTiling);
		zoomedBody.revalidate();

		result.mutations += 3;
		result.revalidates++;
		clearZoomState();

		return result;
	}

	private void rememberZoomState(Widget body) {
		zoomedBody = body;
		zoomedBodyOriginalWidth = body.getOriginalWidth();
		zoomedBodyOriginalHeight = body.getOriginalHeight();
		zoomedBodyWidthMode = body.getWidthMode();
		zoomedBodyHeightMode = body.getHeightMode();
		zoomedBodySpriteTiling = body.getSpriteTiling();
	}

	private void clearZoomState() {
		zoomedBody = null;
	}

	private Result stackGradientBands(Widget background, int targetHeight) {
		final Result result = new Result();
		final Widget[] bands = background.getDynamicChildren();
		if (bands == null
				|| bands.length == 0
				|| background.getHeight() != targetHeight
				|| targetHeight < bands.length) {
			return result;
		}

		final int bandHeight = targetHeight / bands.length;

		for (int i = 0; i < bands.length; i++) {
			final Widget band = bands[i];
			if (band == null || band.getHeightMode() != WidgetSizeMode.ABSOLUTE) {
				continue;
			}

			final int y = bandHeight * i;
			final int height = i == bands.length - 1
					? targetHeight - y
					: bandHeight;

			boolean changed = false;

			if (band.getOriginalY() != y) {
				band.setOriginalY(y);
				result.mutations++;
				changed = true;
			}

			if (band.getOriginalHeight() != height) {
				band.setOriginalHeight(height);
				result.mutations++;
				changed = true;
			}

			if (changed) {
				band.revalidate();
				result.revalidates++;
			}
		}

		return result;
	}

	private static int bevelOverscan(int target, int nativeSize) {
		final int denominator = nativeSize - 2 * BAKED_BORDER;
		if (denominator <= 0) {
			return BAKED_BORDER;
		}

		return (BAKED_BORDER * target + denominator - 1) / denominator;
	}

	private static Widget getBackgroundBody(Widget background) {
		final Widget[] dynamic = background.getDynamicChildren();

		return dynamic != null && dynamic.length > 0
				? dynamic[0]
				: null;
	}

	private static boolean isParchment(Widget body) {
		return body != null && body.getType() == WidgetType.GRAPHIC;
	}

	/*
	 * ================================================================
	 * FRAME
	 * ================================================================
	 */

	private Result syncFrame(Widget chatArea, Widget parchment) {
		final Result result = new Result();

		if (chatArea == null) {
			borderPieces = null;
			return result;
		}

		if (parchment == null) {
			result.add(syncFrameVisibility(true));
			return result;
		}

		if (!framePresent(chatArea)) {
			result.add(removeFrame(chatArea));
			result.add(createFrame(chatArea));
		}

		if (borderPieces == null) {
			return result;
		}

		final int width = chatArea.getWidth();
		final int height = chatArea.getHeight();
		final int innerWidth = Math.max(0, width - 2 * CORNER_SIZE);
		final int innerHeight = Math.max(0, height - 2 * CORNER_SIZE);

		final int[][] rectangles = {
				{0, 0, CORNER_SIZE, CORNER_SIZE},
				{width - CORNER_SIZE, 0, CORNER_SIZE, CORNER_SIZE},
				{0, height - CORNER_SIZE, CORNER_SIZE, CORNER_SIZE},
				{width - CORNER_SIZE, height - CORNER_SIZE, CORNER_SIZE, CORNER_SIZE},
				{CORNER_SIZE, -BORDER_OFFSET - 1, innerWidth, CORNER_SIZE},
				{-BORDER_OFFSET - 1, CORNER_SIZE, CORNER_SIZE, innerHeight},
				{CORNER_SIZE, height - CORNER_SIZE + BORDER_OFFSET, innerWidth, CORNER_SIZE},
				{width - CORNER_SIZE + BORDER_OFFSET, CORNER_SIZE, CORNER_SIZE, innerHeight}
		};

		for (int i = 0; i < borderPieces.length; i++) {
			final Widget piece = borderPieces[i];
			final int[] rectangle = rectangles[i];
			boolean changed = false;

			if (piece.getOriginalX() != rectangle[0]) {
				piece.setOriginalX(rectangle[0]);
				result.mutations++;
				changed = true;
			}

			if (piece.getOriginalY() != rectangle[1]) {
				piece.setOriginalY(rectangle[1]);
				result.mutations++;
				changed = true;
			}

			if (piece.getOriginalWidth() != rectangle[2] || piece.getOriginalHeight() != rectangle[3]) {
				piece.setSize(rectangle[2], rectangle[3]);
				result.mutations++;
				changed = true;
			}

			if (changed) {
				piece.revalidate();
				result.revalidates++;
			}
		}

		result.add(syncFrameVisibility(parchment.isSelfHidden()));
		return result;
	}

	private Result createFrame(Widget chatArea) {
		final Result result = new Result();

		borderPieces = new Widget[BORDER_SPRITES.length];

		for (int i = 0; i < BORDER_SPRITES.length; i++) {
			final Widget piece = chatArea.createChild(-1, WidgetType.GRAPHIC);

			piece.setSpriteId(BORDER_SPRITES[i]);
			piece.setSpriteTiling(true);
			borderPieces[i] = piece;
			result.mutations++;
		}

		return result;
	}

	private Result removeFrame(Widget chatArea) {
		final Result result = new Result();

		if (borderPieces == null) {
			return result;
		}

		final Widget[] children = chatArea != null
				? chatArea.getChildren()
				: null;

		if (children != null) {
			for (Widget piece : borderPieces) {
				if (piece == null) {
					continue;
				}

				final int index = piece.getIndex();
				if (index >= 0 && index < children.length && children[index] == piece) {
					children[index] = null;
					result.mutations++;
				}
			}
		}

		borderPieces = null;
		return result;
	}

	private Result syncFrameVisibility(boolean hidden) {
		final Result result = new Result();

		if (borderPieces == null) {
			return result;
		}

		for (Widget piece : borderPieces) {
			if (piece != null && piece.isSelfHidden() != hidden) {
				piece.setHidden(hidden);
				result.mutations++;
			}
		}

		return result;
	}

	private boolean framePresent(Widget chatArea) {
		if (borderPieces == null) {
			return false;
		}

		final Widget[] children = chatArea.getChildren();
		if (children == null) {
			return false;
		}

		for (Widget piece : borderPieces) {
			if (piece == null) {
				return false;
			}

			final int index = piece.getIndex();
			if (index < 0 || index >= children.length || children[index] != piece) {
				return false;
			}
		}

		return true;
	}

	static final class Result {
		private int mutations;
		private int revalidates;

		int getMutations() {
			return mutations;
		}

		int getRevalidates() {
			return revalidates;
		}

		private void add(Result other) {
			if (other == null) {
				return;
			}

			mutations += other.mutations;
			revalidates += other.revalidates;
		}
	}
}

package com.bigboldchat.chatbox;

import com.bigboldchat.Configurations;
import com.bigboldchat.debug.PerformanceMetrics;

import net.runelite.api.Client;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.client.callback.ClientThread;

/**
 * Coalesces chatbox geometry commits and native chat rebuilds.
 */
public final class ChatRebuildCoordinator {
	private final Client client;
	private final ClientThread clientThread;
	private final Configurations config;
	private final ChatboxResizeService resizeService;
	private final PerformanceMetrics performanceMetrics;

	private volatile boolean active = true;
	private boolean commitQueued;
	private boolean boundsChanged;
	private boolean pendingWidthRefresh;
	private boolean pendingHeightRefresh;
	private boolean forceRefreshAfterCommit;
	private boolean forceRefreshTracksVisibility;
	private PerformanceMetrics.RefreshReason forceRefreshReason;
	private boolean refreshQueued;
	private boolean refreshWidthChanged;
	private boolean refreshHeightChanged;
	private boolean refreshForced;
	private boolean refreshTracksVisibility;
	private PerformanceMetrics.RefreshReason refreshReason;
	private ChatboxResizeService.ScrollBaseline refreshScrollBaseline;
	private boolean visibilityRefreshPending;
	private PerformanceMetrics.RefreshReason visibilityRefreshReason;
	private boolean refreshing;
	private int committedWidth;
	private int committedHeight;

	public ChatRebuildCoordinator(
			Client client,
			ClientThread clientThread,
			Configurations config,
			ChatboxResizeService resizeService,
			PerformanceMetrics performanceMetrics) {
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.resizeService = resizeService;
		this.performanceMetrics = performanceMetrics;
		this.committedWidth = config.chatboxWidth();
		this.committedHeight = config.chatboxHeight();
	}

	public void onStartup() {
		applyConfiguredSize(PerformanceMetrics.RefreshReason.STARTUP, true);
	}

	public void onLoggedIn() {
		applyConfiguredSize(PerformanceMetrics.RefreshReason.OTHER, true);
	}

	public void onConfiguredSizeChanged() {
		if (!active) {
			return;
		}

		queueCommit(false, false, false);
	}

	public void onButtonsChanged() {
		if (!active) {
			return;
		}

		queueCommit(true, false, false);
	}

	public void onCanvasSizeChanged() {
		if (!active) {
			return;
		}

		queueCommit(true, false, false);
	}

	public void onInterfaceChanged() {
		if (!active) {
			return;
		}

		queueCommit(true, false, false);
	}

	public void onLayoutChanged(ChatboxResizeService.ResizeResult result) {
		if (!active || refreshing || result == null || !result.isApplied()
				|| !result.isWidthChanged() && !result.isHeightChanged()) {
			return;
		}

		/*
		 * Script-driven layout changes apply geometry synchronously so the
		 * native relayout sees it. Reapply once after that script stack settles,
		 * then refresh presentation against the stable effective dimensions.
		 */
		queueCommit(true, result.isWidthChanged(), result.isHeightChanged());
	}

	public void refreshLiveGeometry(boolean widthChanged, boolean heightChanged) {
		if (!active || refreshing || resizeService == null || !widthChanged && !heightChanged) {
			return;
		}

		final ChatboxResizeService.ScrollBaseline scrollBaseline = resizeService.captureScrollBaseline();

		/*
		 * Live geometry is already authoritative. Rebuild retained rows only;
		 * sending this path through the geometry commit queue previously made
		 * ChatXL fight RuneScape's native relayout and caused visible oscillation.
		 * The same rebuild now serves chatbox and independently-sized split-PM
		 * width changes, so callers coalesce both reasons before reaching here.
		 */
		refreshing = true;
		try {
			if (performanceMetrics != null) {
				/*
				 * A single rebuild may satisfy both axes. Classify it as a width refresh
				 * when wrapping is involved, otherwise as a height-only refresh.
				 */
				final PerformanceMetrics.RefreshReason reason = widthChanged
						? PerformanceMetrics.RefreshReason.WIDTH_CHANGED
						: PerformanceMetrics.RefreshReason.HEIGHT_CHANGED;

				performanceMetrics.recordRefreshChat(reason);
			}

			client.refreshChat();
			resizeService.restoreRebuildScroll(scrollBaseline);
		} finally {
			refreshing = false;
		}
	}

	public void onScriptPostFired(ScriptPostFired event) {
		if (!active || event == null || event.getScriptId() != ChatboxResizeService.CHAT_VISIBILITY
				|| resizeService == null || resizeService.isChatViewHidden()) {
			return;
		}

		final PerformanceMetrics.RefreshReason reason;
		synchronized (this) {
			if (!visibilityRefreshPending) {
				return;
			}

			visibilityRefreshPending = false;
			reason = visibilityRefreshReason;
			visibilityRefreshReason = null;
		}

		queueForcedCommit(reason, false);
	}

	public synchronized void deactivate() {
		active = false;
		commitQueued = false;
		boundsChanged = false;
		pendingWidthRefresh = false;
		pendingHeightRefresh = false;
		forceRefreshAfterCommit = false;
		forceRefreshTracksVisibility = false;
		forceRefreshReason = null;
		refreshQueued = false;
		refreshWidthChanged = false;
		refreshHeightChanged = false;
		refreshForced = false;
		refreshTracksVisibility = false;
		refreshReason = null;
		refreshScrollBaseline = null;
		visibilityRefreshPending = false;
		visibilityRefreshReason = null;
	}

	private void applyConfiguredSize(PerformanceMetrics.RefreshReason reason, boolean trackVisibility) {
		if (!active || resizeService == null || config == null) {
			return;
		}

		resizeService.setChatboxButtonsHidden(config.hideChatboxButtons());

		final int width = config.chatboxWidth();
		final int height = config.chatboxHeight();
		final ChatboxResizeService.ScrollBaseline scrollBaseline = resizeService.captureScrollBaseline();
		final ChatboxResizeService.ResizeResult result = resizeService.applySize(width, height);
		if (result != null && result.isApplied()) {
			committedWidth = width;
			committedHeight = height;
		} else if (resizeService.getLayout() != ChatboxLayout.FIXED) {
			queueForcedCommit(reason, trackVisibility);
		}

		/*
		 * Retained rows need one native rebuild even when
		 * configured  geometry already matches the mounted chatbox.
		 */
		queueRefresh(
				result != null && result.isWidthChanged(),
				result != null && result.isHeightChanged(),
				true, reason, trackVisibility, scrollBaseline);
	}

	private synchronized void queueCommit(boolean boundsChanged, boolean widthRefresh, boolean heightRefresh) {
		if (!active) {
			return;
		}

		this.boundsChanged |= boundsChanged;
		pendingWidthRefresh |= widthRefresh;
		pendingHeightRefresh |= heightRefresh;
		if (commitQueued) {
			return;
		}

		commitQueued = true;
		clientThread.invokeLater(this::drainCommit);
	}

	private synchronized void queueForcedCommit(PerformanceMetrics.RefreshReason reason, boolean trackVisibility) {
		if (!active) {
			return;
		}

		boundsChanged = true;
		forceRefreshAfterCommit = true;
		forceRefreshTracksVisibility |= trackVisibility;
		if (reason != null) {
			forceRefreshReason = reason;
		}

		if (commitQueued) {
			return;
		}

		commitQueued = true;
		clientThread.invokeLater(this::drainCommit);
	}

	private void drainCommit() {
		final boolean reapplyBounds;
		final boolean widthRefresh;
		final boolean heightRefresh;
		final boolean forceRefresh;
		final boolean trackVisibility;
		final PerformanceMetrics.RefreshReason forcedReason;
		synchronized (this) {
			commitQueued = false;
			reapplyBounds = boundsChanged;
			widthRefresh = pendingWidthRefresh;
			heightRefresh = pendingHeightRefresh;
			forceRefresh = forceRefreshAfterCommit;
			trackVisibility = forceRefreshTracksVisibility;
			forcedReason = forceRefreshReason;
			boundsChanged = false;
			pendingWidthRefresh = false;
			pendingHeightRefresh = false;
		}

		if (!active || resizeService == null || config == null) {
			return;
		}

		resizeService.setChatboxButtonsHidden(config.hideChatboxButtons());

		final int width = config.chatboxWidth();
		final int height = config.chatboxHeight();
		final boolean widthChanged = width != committedWidth;
		final boolean heightChanged = height != committedHeight;
		if (!widthChanged
				&& !heightChanged
				&& !reapplyBounds
				&& !widthRefresh
				&& !heightRefresh
				&& !forceRefresh) {
			return;
		}

		final ChatboxResizeService.ScrollBaseline scrollBaseline = resizeService.captureScrollBaseline();
		final ChatboxResizeService.ResizeResult result = resizeService.applySize(width, height);
		if (result == null || !result.isApplied()) {
			if (resizeService.getLayout() == ChatboxLayout.FIXED) {
				clearForcedCommit();
			}
			return;
		}

		committedWidth = width;
		committedHeight = height;

		if (forceRefresh) {
			clearForcedCommit();
		}

		queueRefresh(
				widthRefresh || result.isWidthChanged(),
				heightRefresh || result.isHeightChanged(),
				forceRefresh, forcedReason, trackVisibility, scrollBaseline);
	}

	private synchronized void clearForcedCommit() {
		forceRefreshAfterCommit = false;
		forceRefreshTracksVisibility = false;
		forceRefreshReason = null;
	}

	private synchronized void queueRefresh(
			boolean widthChanged, boolean heightChanged, boolean forced, PerformanceMetrics.RefreshReason reason,
			boolean trackVisibility, ChatboxResizeService.ScrollBaseline scrollBaseline) {
		if (!active || (!forced && !widthChanged && !heightChanged)) {
			return;
		}

		refreshWidthChanged |= widthChanged;
		refreshHeightChanged |= heightChanged;
		refreshForced |= forced;
		refreshTracksVisibility |= trackVisibility;
		if (reason != null) {
			refreshReason = reason;
		}

		if (refreshScrollBaseline == null) {
			refreshScrollBaseline = scrollBaseline;
		}

		if (refreshQueued) {
			return;
		}

		refreshQueued = true;
		clientThread.invokeLater(this::drainRefresh);
	}

	private void drainRefresh() {
		final boolean widthChanged;
		final boolean heightChanged;
		final boolean forced;
		final boolean trackVisibility;
		final PerformanceMetrics.RefreshReason explicitReason;
		final ChatboxResizeService.ScrollBaseline scrollBaseline;
		synchronized (this) {
			refreshQueued = false;
			widthChanged = refreshWidthChanged;
			heightChanged = refreshHeightChanged;
			forced = refreshForced;
			trackVisibility = refreshTracksVisibility;
			explicitReason = refreshReason;
			scrollBaseline = refreshScrollBaseline;
			refreshWidthChanged = false;
			refreshHeightChanged = false;
			refreshForced = false;
			refreshTracksVisibility = false;
			refreshReason = null;
			refreshScrollBaseline = null;
		}

		if (!active || (!forced && !widthChanged && !heightChanged)) {
			return;
		}

		refreshing = true;
		try {
			if (performanceMetrics != null) {
				performanceMetrics.recordRefreshChat(resolveRefreshReason(widthChanged, heightChanged, explicitReason));
			}

			client.refreshChat();
			resizeService.restoreRebuildScroll(scrollBaseline);

			if (trackVisibility) {
				rememberVisibilityRefresh(explicitReason);
			}
		} finally {
			refreshing = false;
		}
	}

	private PerformanceMetrics.RefreshReason resolveRefreshReason(boolean widthChanged, boolean heightChanged,
			PerformanceMetrics.RefreshReason explicitReason) {
		if (explicitReason != null) {
			return explicitReason;
		}

		if (widthChanged) {
			return PerformanceMetrics.RefreshReason.WIDTH_CHANGED;
		}

		return heightChanged
				? PerformanceMetrics.RefreshReason.HEIGHT_CHANGED
				: PerformanceMetrics.RefreshReason.OTHER;
	}

	private synchronized void rememberVisibilityRefresh(PerformanceMetrics.RefreshReason reason) {
		if (resizeService == null || !resizeService.isChatViewHidden()) {
			visibilityRefreshPending = false;
			visibilityRefreshReason = null;
			return;
		}

		visibilityRefreshPending = true;
		visibilityRefreshReason = reason;
	}

}

package com.bigboldchat.chatbox;

/**
 * Native chatbox geometry shared by resize and restore paths.
 *
 * The resizable chat slot includes the 23-pixel
 * control/tab band beneath the 142-pixel chat body.
 */
public final class ChatboxGeometry {
	public static final int NATIVE_WIDTH = 519;
	public static final int NATIVE_BODY_HEIGHT = 142;
	public static final int NATIVE_SLOT_HEIGHT = 165;
	public static final int NATIVE_TAB_HEIGHT = NATIVE_SLOT_HEIGHT - NATIVE_BODY_HEIGHT;

	private ChatboxGeometry() {
		/*
		 * CHATBOX GEOMETRY
		 */
	}

	public static int bodyHeight(int slotHeight) {
		return Math.max(0, slotHeight - NATIVE_TAB_HEIGHT);
	}

	public static int bodyHeight(int slotHeight, boolean buttonsHidden) {
		return buttonsHidden
				? Math.max(0, slotHeight)
				: bodyHeight(slotHeight);
	}
}

package com.bigboldchat.debug;

import java.awt.Rectangle;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Deque;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import com.bigboldchat.Configurations;

import lombok.extern.slf4j.Slf4j;

import net.runelite.api.Client;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * Observer-only diagnostics for Modern side-container layout and collisions.
 */
@Slf4j
public final class SideContainerDiagnostics {
	private static final String COMMAND = "debug-inventory";
	private static final int INT_STACK_TAIL_SIZE = 16;
	private static final int MAX_LOGGED_STRING_LENGTH = 200;

	private final Client client;
	private final Configurations config;
	private final Deque<TraceFrame> traceFrames = new ArrayDeque<>();

	private boolean armed;
	private CollisionState collisionState;

	public SideContainerDiagnostics(Client client, Configurations config) {
		this.client = client;
		this.config = config;
	}

	public synchronized boolean onCommandExecuted(CommandExecuted event) {
		if (event == null || !COMMAND.equalsIgnoreCase(event.getCommand())) {
			return false;
		}

		armed = !armed;
		traceFrames.clear();
		collisionState = null;

		log.debug(
				"[Chat XL][Side Container Diagnostic] {}", armed
						? "ARMED"
						: "DISARMED");

		return true;
	}

	public synchronized void onScriptPreFired(ScriptPreFired event) {
		if (!armed || event == null) {
			return;
		}

		logCollision(event.getScriptId());

		final Snapshot current = snapshot();
		final TraceFrame parent = traceFrames.peek();
		if (parent != null) {
			logChanges(parent, current, "BEFORE_CHILD", event.getScriptId());
			parent.checkpoint = current;
		}

		final TraceFrame frame = new TraceFrame();

		frame.scriptId = event.getScriptId();
		frame.depth = traceFrames.size() + 1;
		frame.checkpoint = current;
		frame.intTailBefore = traceIntStackTail();
		frame.stringsBefore = traceObjectStackStrings();
		frame.arguments = traceScriptArguments(event);

		traceFrames.push(frame);
	}

	public synchronized void onScriptPostFired(ScriptPostFired event) {
		if (!armed || event == null || traceFrames.isEmpty()) {
			return;
		}

		final TraceFrame frame = traceFrames.peek();
		if (frame == null) {
			traceFrames.clear();
			return;
		}

		if (frame.scriptId != event.getScriptId()) {
			log.debug(
					"[Chat XL][Side Container Diagnostic]"
							+ " STACK MISMATCH"
							+ " | expectedScriptId={}"
							+ " | actualScriptId={}"
							+ " | depth={}",
					frame.scriptId,
					event.getScriptId(),
					traceFrames.size());
			traceFrames.clear();
			return;
		}

		final Snapshot current = snapshot();

		logCollision(frame.scriptId);
		logChanges(frame, current, "POST", -1);

		traceFrames.pop();

		final TraceFrame parent = traceFrames.peek();
		if (parent != null) {
			parent.checkpoint = current;
		}
	}

	public synchronized void reset() {
		traceFrames.clear();
		collisionState = null;
		armed = false;
	}

	private void logChanges(TraceFrame frame, Snapshot current, String phase, int nextScriptId) {
		if (frame == null || frame.checkpoint == null || current == null) {
			return;
		}

		final List<String> changes = compare(frame.checkpoint, current);
		if (changes.isEmpty()) {
			return;
		}

		log.debug(
				"[Chat XL][Side Container Diagnostic]"
						+ " SCRIPT"
						+ " | phase={}"
						+ " | depth={}"
						+ " | scriptId={}"
						+ " | nextScriptId={}"
						+ " | topLevel={}->{}"
						+ " | args={}"
						+ " | intTail={}"
						+ " | strings={}",
				phase,
				frame.depth,
				frame.scriptId,
				nextScriptId >= 0
						? Integer.toString(nextScriptId)
						: "-",
				frame.checkpoint.topLevel,
				current.topLevel,
				frame.arguments,
				frame.intTailBefore,
				frame.stringsBefore);

		for (String change : changes) {
			log.debug(
					"[Chat XL][Side Container Diagnostic]"
							+ " CHANGE"
							+ " | scriptId={}"
							+ " | {}",
					frame.scriptId,
					change);
		}
	}

	private List<String> compare(Snapshot before, Snapshot after) {
		final List<String> changes = new ArrayList<>();
		if (before == null || after == null) {
			return changes;
		}

		if (before.topLevel != after.topLevel) {
			changes.add("component=TOPLEVEL | id=" + before.topLevel + "->" + after.topLevel);
		}

		final Set<String> labels = new LinkedHashSet<>();

		labels.addAll(before.widgets.keySet());
		labels.addAll(after.widgets.keySet());

		for (String label : labels) {
			final WidgetState beforeState = before.widgets.get(label);
			final WidgetState afterState = after.widgets.get(label);
			final String difference = WidgetState.describeDifference(label, beforeState, afterState);
			if (difference != null) {
				changes.add(difference);
			}
		}

		return changes;
	}

	private Snapshot snapshot() {
		final Map<String, WidgetState> widgets = new LinkedHashMap<>();

		final Widget background = client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_BACKGROUND);
		final Widget staticLayer = client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_STATIC_LAYER);
		final Widget movableLayer = client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_MOVABLE_LAYER);
		final Widget container = client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_CONTAINER);

		putWidget(widgets, "SIDE_BACKGROUND", background);
		putWidget(widgets, "SIDE_STATIC_LAYER", staticLayer);
		putWidget(widgets, "SIDE_MOVABLE_LAYER", movableLayer);
		putWidget(widgets, "SIDE_CONTAINER", container);
		putWidget(widgets, "MAP_CONTAINER", client.getWidget(InterfaceID.ToplevelPreEoc.MAP_CONTAINER));
		putWidget(widgets, "ORBS", client.getWidget(InterfaceID.ToplevelPreEoc.ORBS));
		putChildren(widgets, "SIDE_STATIC", staticLayer);
		putChildren(widgets, "SIDE_MOVABLE", movableLayer);

		return new Snapshot(client.getTopLevelInterfaceId(), widgets);
	}

	private static void putWidget(Map<String, WidgetState> widgets, String label, Widget widget) {
		widgets.put(label, new WidgetState(widget));
	}

	private static void putChildren(Map<String, WidgetState> widgets, String prefix, Widget parent) {
		if (parent == null) {
			return;
		}

		putChildren(widgets, prefix + "_STATIC", parent.getStaticChildren());
		putChildren(widgets, prefix + "_DYNAMIC", parent.getDynamicChildren());
		putChildren(widgets, prefix + "_NESTED", parent.getNestedChildren());
	}

	private static void putChildren(Map<String, WidgetState> widgets, String prefix, Widget[] children) {
		if (children == null) {
			return;
		}

		for (int i = 0; i < children.length; i++) {
			putWidget(widgets, prefix + "_" + i, children[i]);
		}
	}

	private void logCollision(int scriptId) {
		final CollisionState current = CollisionState.capture(client, config);
		if (current == null || current.sameAs(collisionState)) {
			return;
		}

		collisionState = current;

		log.debug(
				"[Chat XL][Side Container Diagnostic]"
						+ " COLLISION"
						+ " | scriptId={}"
						+ " | configuredWidth={}"
						+ " | buttonLayers={}"
						+ " | staticLayer={}"
						+ " | movableLayer={}"
						+ " | staticChildren={}"
						+ " | movableChildren={}"
						+ " | background={}"
						+ " | container={}"
						+ " | desired={}"
						+ " | staticBounds={}"
						+ " | movableBounds={}"
						+ " | backgroundBounds={}"
						+ " | containerBounds={}",
				scriptId,
				current.configuredWidth,
				current.buttonLayers,
				current.staticLayerHit,
				current.movableLayerHit,
				current.staticChildHits,
				current.movableChildHits,
				current.backgroundHit,
				current.containerHit,
				describeBounds(current.desired),
				describeBounds(current.staticBounds),
				describeBounds(current.movableBounds),
				describeBounds(current.backgroundBounds),
				describeBounds(current.containerBounds));
	}

	private String traceScriptArguments(ScriptPreFired event) {
		if (event == null || event.getScriptEvent() == null || event.getScriptEvent().getArguments() == null) {
			return "[]";
		}

		final Object[] arguments = event.getScriptEvent().getArguments();
		final List<String> values = new ArrayList<>();

		for (Object argument : arguments) {
			if (argument instanceof String) {
				String value = (String) argument;
				if (value.length() > MAX_LOGGED_STRING_LENGTH) {
					value = value.substring(0, MAX_LOGGED_STRING_LENGTH) + "...";
				}

				values.add("'" + value + "'");
				continue;
			}

			if (argument instanceof Widget) {
				final Widget widget = (Widget) argument;
				values.add("Widget(id=" + widget.getId() + ", identity=" + System.identityHashCode(widget) + ")");
				continue;
			}

			values.add(String.valueOf(argument));
		}

		return values.toString();
	}

	private String traceIntStackTail() {
		final int[] stack = client.getIntStack();
		final int size = client.getIntStackSize();
		if (stack == null || size <= 0 || size > stack.length) {
			return "[]";
		}

		final int start = Math.max(0, size - INT_STACK_TAIL_SIZE);

		return Arrays.toString(Arrays.copyOfRange(stack, start, size));
	}

	private String traceObjectStackStrings() {
		final Object[] stack = client.getObjectStack();
		final int size = client.getObjectStackSize();
		if (stack == null || size <= 0 || size > stack.length) {
			return "[]";
		}

		final List<String> strings = new ArrayList<>();

		for (int i = 0; i < size; i++) {
			final Object value = stack[i];
			if (!(value instanceof String)) {
				continue;
			}

			String text = (String) value;

			text = text
					.replace("\r\n", "\\n")
					.replace('\r', '\n')
					.replace("\n", "\\n");

			if (text.length() > MAX_LOGGED_STRING_LENGTH) {
				text = text.substring(0, MAX_LOGGED_STRING_LENGTH) + "...";
			}

			strings.add("'" + text + "'");
		}

		return strings.toString();
	}

	private static String describeBounds(Rectangle bounds) {
		if (bounds == null) {
			return "-";
		}

		return "[x=" + bounds.x
				+ ", y=" + bounds.y
				+ ", width=" + bounds.width
				+ ", height=" + bounds.height
				+ "]";
	}

	private static final class CollisionState {
		private final int configuredWidth;
		private final Rectangle desired;
		private final Rectangle backgroundBounds;
		private final Rectangle staticBounds;
		private final Rectangle movableBounds;
		private final Rectangle containerBounds;
		private final boolean backgroundHit;
		private final boolean staticLayerHit;
		private final boolean movableLayerHit;
		private final boolean containerHit;
		private final int staticChildHits;
		private final int movableChildHits;
		private final int buttonLayers;

		private CollisionState(
				int configuredWidth,
				Rectangle desired,
				Rectangle backgroundBounds,
				Rectangle staticBounds,
				Rectangle movableBounds,
				Rectangle containerBounds,
				int staticChildHits,
				int movableChildHits) {
			this.configuredWidth = configuredWidth;
			this.desired = desired;
			this.backgroundBounds = backgroundBounds;
			this.staticBounds = staticBounds;
			this.movableBounds = movableBounds;
			this.containerBounds = containerBounds;
			this.backgroundHit = intersects(desired, backgroundBounds);
			this.staticLayerHit = intersects(desired, staticBounds);
			this.movableLayerHit = intersects(desired, movableBounds);
			this.containerHit = intersects(desired, containerBounds);
			this.staticChildHits = staticChildHits;
			this.movableChildHits = movableChildHits;
			this.buttonLayers = (staticChildHits > 0
					? 1
					: 0) + (movableChildHits > 0
					? 1
					: 0);
		}

		private static CollisionState capture(Client client, Configurations config) {
			if (client == null
					|| config == null
					|| client.getTopLevelInterfaceId() != InterfaceID.TOPLEVEL_PRE_EOC) {
				return null;
			}

			final Widget slot = client.getWidget(InterfaceID.ToplevelPreEoc.CHAT_CONTAINER);
			final Rectangle slotBounds = visibleBounds(slot);
			if (slotBounds == null) {
				return null;
			}

			final int configuredWidth = config.chatboxWidth();
			final Rectangle desired = new Rectangle(
					slotBounds.x, slotBounds.y, Math.max(0, configuredWidth), slotBounds.height);

			final Widget background = client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_BACKGROUND);
			final Widget staticLayer = client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_STATIC_LAYER);
			final Widget movableLayer = client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_MOVABLE_LAYER);
			final Widget container = client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_CONTAINER);

			return new CollisionState(
					configuredWidth,
					desired,
					visibleBounds(background),
					visibleBounds(staticLayer),
					visibleBounds(movableLayer),
					visibleBounds(container),
					countChildHits(desired, staticLayer),
					countChildHits(desired, movableLayer));
		}

		private boolean sameAs(CollisionState other) {
			return other != null
					&& configuredWidth == other.configuredWidth
					&& backgroundHit == other.backgroundHit
					&& staticLayerHit == other.staticLayerHit
					&& movableLayerHit == other.movableLayerHit
					&& containerHit == other.containerHit
					&& staticChildHits == other.staticChildHits
					&& movableChildHits == other.movableChildHits;
		}

		private static Rectangle visibleBounds(Widget widget) {
			if (widget == null || widget.isHidden()) {
				return null;
			}

			final Rectangle bounds = widget.getBounds();
			return bounds != null && bounds.width > 0 && bounds.height > 0
					? new Rectangle(bounds)
					: null;
		}

		private static int countChildHits(Rectangle desired, Widget parent) {
			if (desired == null || parent == null || parent.isHidden()) {
				return 0;
			}

			return countChildHits(desired, parent.getStaticChildren())
					+ countChildHits(desired, parent.getDynamicChildren())
					+ countChildHits(desired, parent.getNestedChildren());
		}

		private static int countChildHits(Rectangle desired, Widget[] children) {
			if (children == null) {
				return 0;
			}

			int hits = 0;
			for (Widget child : children) {
				final Rectangle bounds = visibleBounds(child);
				if (intersects(desired, bounds)) {
					hits++;
				}
			}

			return hits;
		}
	}

	private static final class TraceFrame {
		private int scriptId;
		private int depth;
		private Snapshot checkpoint;
		private String intTailBefore;
		private String stringsBefore;
		private String arguments;
	}

	private static final class Snapshot {
		private final int topLevel;
		private final Map<String, WidgetState> widgets;

		private Snapshot(int topLevel, Map<String, WidgetState> widgets) {
			this.topLevel = topLevel;
			this.widgets = widgets;
		}
	}

	private static final class WidgetState {
		private final boolean present;
		private final int identity;
		private final int originalX;
		private final int originalY;
		private final int originalWidth;
		private final int originalHeight;
		private final int relativeX;
		private final int relativeY;
		private final int width;
		private final int height;
		private final boolean hidden;
		private final int staticChildren;
		private final int dynamicChildren;
		private final int nestedChildren;

		private WidgetState(Widget widget) {
			if (widget == null) {
				present = false;
				identity = 0;
				originalX = 0;
				originalY = 0;
				originalWidth = 0;
				originalHeight = 0;
				relativeX = 0;
				relativeY = 0;
				width = 0;
				height = 0;
				hidden = true;
				staticChildren = 0;
				dynamicChildren = 0;
				nestedChildren = 0;
				return;
			}

			present = true;
			identity = System.identityHashCode(widget);
			originalX = widget.getOriginalX();
			originalY = widget.getOriginalY();
			originalWidth = widget.getOriginalWidth();
			originalHeight = widget.getOriginalHeight();
			relativeX = widget.getRelativeX();
			relativeY = widget.getRelativeY();
			width = widget.getWidth();
			height = widget.getHeight();
			hidden = widget.isHidden();
			staticChildren = childCount(widget.getStaticChildren());
			dynamicChildren = childCount(widget.getDynamicChildren());
			nestedChildren = childCount(widget.getNestedChildren());
		}

		private static String describeDifference(String label, WidgetState before, WidgetState after) {
			if (before == null && after == null) {
				return null;
			}

			if (before == null) {
				return "component=" + label + " | state=MISSING->" + after.describe();
			}

			if (after == null) {
				return "component=" + label + " | state=" + before.describe() + "->MISSING";
			}

			final StringBuilder difference = new StringBuilder();

			appendDifference(difference, "present", before.present, after.present);
			appendDifference(difference, "identity", before.identity, after.identity);
			appendDifference(difference, "originalX", before.originalX, after.originalX);
			appendDifference(difference, "originalY", before.originalY, after.originalY);
			appendDifference(difference, "originalWidth", before.originalWidth, after.originalWidth);
			appendDifference(difference, "originalHeight", before.originalHeight, after.originalHeight);
			appendDifference(difference, "relativeX", before.relativeX, after.relativeX);
			appendDifference(difference, "relativeY", before.relativeY, after.relativeY);
			appendDifference(difference, "width", before.width, after.width);
			appendDifference(difference, "height", before.height, after.height);
			appendDifference(difference, "hidden", before.hidden, after.hidden);
			appendDifference(difference, "staticChildren", before.staticChildren, after.staticChildren);
			appendDifference(difference, "dynamicChildren", before.dynamicChildren, after.dynamicChildren);
			appendDifference(difference, "nestedChildren", before.nestedChildren, after.nestedChildren);

			return difference.length() == 0
					? null
					: "component=" + label + " | " + difference;
		}

		private String describe() {
			if (!present) {
				return "MISSING";
			}

			return "identity="
					+ identity
					+ ", original=["
					+ originalX
					+ ","
					+ originalY
					+ ","
					+ originalWidth
					+ "x"
					+ originalHeight
					+ "]"
					+ ", relative=["
					+ relativeX
					+ ","
					+ relativeY
					+ "]"
					+ ", calculated=["
					+ width
					+ "x"
					+ height
					+ "]";
		}

		private static int childCount(Widget[] children) {
			return children != null
					? children.length
					: 0;
		}

		private static void appendDifference(StringBuilder builder, String name, int before, int after) {
			if (before == after) {
				return;
			}

			appendSeparator(builder);
			builder.append(name).append('=').append(before).append("->").append(after);
		}

		private static void appendDifference(StringBuilder builder, String name, boolean before, boolean after) {
			if (before == after) {
				return;
			}

			appendSeparator(builder);
			builder.append(name).append('=').append(before).append("->").append(after);
		}

		private static void appendSeparator(StringBuilder builder) {
			if (builder.length() > 0) {
				builder.append(", ");
			}
		}
	}

	private static boolean intersects(Rectangle first, Rectangle second) {
		return first != null && second != null && first.intersects(second);
	}
}

package com.bigboldchat.debug;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Deque;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import lombok.extern.slf4j.Slf4j;

import net.runelite.api.Client;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * Observer-only diagnostics for chatbox geometry and reconstruction.
 */
@Slf4j
public final class ChatboxDiagnostics {
	private static final String COMMAND = "debug-chatbox";

	/*
	 * Reference plugins use these native rebuild paths for resizable chat.
	 * Diagnostics observe them only; ChatXL never invokes them.
	 */
	private static final int RESIZES_CHAT = 924;
	private static final int REWRAPS_CHAT = 663;

	private static final int INT_STACK_TAIL_SIZE = 16;
	private static final int MAX_LOGGED_STRING_LENGTH = 200;

	private final Client client;
	private final Deque<ResizeTraceFrame> resizeTraceFrames = new ArrayDeque<>();

	private boolean armed;

	public ChatboxDiagnostics(Client client) {
		this.client = client;
	}

	public synchronized boolean onCommandExecuted(CommandExecuted event) {
		if (event == null || !COMMAND.equalsIgnoreCase(event.getCommand())) {
			return false;
		}

		armed = !armed;
		resizeTraceFrames.clear();

		log.debug(
				"[Chat XL][Chatbox Diagnostic] {}", armed
						? "ARMED"
						: "DISARMED");

		return true;
	}

	public synchronized void onScriptPreFired(ScriptPreFired event) {
		if (!armed || event == null) {
			return;
		}

		final ResizeSnapshot current = snapshotResizeWidgets();
		final ResizeTraceFrame parent = resizeTraceFrames.peek();
		if (parent != null) {
			logResizeChanges(parent, current, "BEFORE_CHILD", event.getScriptId());
			parent.checkpoint = current;
		}

		final ResizeTraceFrame frame = new ResizeTraceFrame();

		frame.scriptId = event.getScriptId();
		frame.depth = resizeTraceFrames.size() + 1;
		frame.checkpoint = current;
		frame.intTailBefore = traceIntStackTail();
		frame.stringsBefore = traceObjectStackStrings();
		frame.arguments = traceScriptArguments(event);

		if (isRebuildCandidate(frame.scriptId)) {
			frame.candidateEntry = current;
			logRebuildState(frame, "PRE", snapshotChatState());
		}

		resizeTraceFrames.push(frame);
	}

	public synchronized void onScriptPostFired(ScriptPostFired event) {
		if (!armed || event == null || resizeTraceFrames.isEmpty()) {
			return;
		}

		final ResizeTraceFrame frame = resizeTraceFrames.peek();
		if (frame == null) {
			resizeTraceFrames.clear();
			return;
		}

		if (frame.scriptId != event.getScriptId()) {
			log.debug(
					"[Chat XL][Chatbox Diagnostic]"
							+ " STACK MISMATCH"
							+ " | expectedScriptId={}"
							+ " | actualScriptId={}"
							+ " | depth={}",
					frame.scriptId,
					event.getScriptId(),
					resizeTraceFrames.size());
			resizeTraceFrames.clear();
			return;
		}

		final ResizeSnapshot current = snapshotResizeWidgets();

		if (isRebuildCandidate(frame.scriptId)) {
			logRebuildResult(frame, current);
		}

		logResizeChanges(frame, current, "POST", -1);

		resizeTraceFrames.pop();

		final ResizeTraceFrame parent = resizeTraceFrames.peek();
		if (parent != null) {
			parent.checkpoint = current;
		}
	}

	private static boolean isRebuildCandidate(int scriptId) {
		return scriptId == RESIZES_CHAT || scriptId == REWRAPS_CHAT;
	}

	private void logRebuildResult(ResizeTraceFrame frame, ResizeSnapshot current) {
		final ChatStateSnapshot after = snapshotChatState();

		logRebuildState(frame, "POST", after);

		final List<String> changes = compareResizeSnapshots(frame.candidateEntry, current);
		if (changes.isEmpty()) {
			log.debug(
					"[Chat XL][Chatbox Diagnostic]"
							+ " REBUILD CHANGE"
							+ " | scriptId={}"
							+ " | none",
					frame.scriptId);
			return;
		}

		for (String change : changes) {
			log.debug(
					"[Chat XL][Chatbox Diagnostic]"
							+ " REBUILD CHANGE"
							+ " | scriptId={}"
							+ " | {}",
					frame.scriptId,
					change);
		}
	}

	private void logRebuildState(ResizeTraceFrame frame, String phase, ChatStateSnapshot state) {
		log.debug(
				"[Chat XL][Chatbox Diagnostic]"
						+ " REBUILD"
						+ " | phase={}"
						+ " | depth={}"
						+ " | scriptId={}"
						+ " | args={}"
						+ " | intTail={}"
						+ " | {}",
				phase,
				frame.depth,
				frame.scriptId,
				frame.arguments,
				frame.intTailBefore,
				state.describe());
	}

	private void logResizeChanges(ResizeTraceFrame frame, ResizeSnapshot current, String phase, int nextScriptId) {
		if (frame == null || frame.checkpoint == null || current == null) {
			return;
		}

		final List<String> changes = compareResizeSnapshots(frame.checkpoint, current);
		if (changes.isEmpty()) {
			return;
		}

		log.debug(
				"[Chat XL][Chatbox Diagnostic]"
						+ " SCRIPT"
						+ " | phase={}"
						+ " | depth={}"
						+ " | scriptId={}"
						+ " | nextScriptId={}"
						+ " | topLevel={}->{}"
						+ " | args={}"
						+ " | intTail={}"
						+ " | strings={}",
				phase,
				frame.depth,
				frame.scriptId,
				nextScriptId >= 0
						? Integer.toString(nextScriptId)
						: "-",
				frame.checkpoint.topLevel,
				current.topLevel,
				frame.arguments,
				frame.intTailBefore,
				frame.stringsBefore);

		for (String change : changes) {
			log.debug(
					"[Chat XL][Chatbox Diagnostic]"
							+ " CHANGE"
							+ " | scriptId={}"
							+ " | {}",
					frame.scriptId,
					change);
		}
	}

	private List<String> compareResizeSnapshots(ResizeSnapshot before, ResizeSnapshot after) {
		final List<String> changes = new ArrayList<>();

		if (before == null || after == null) {
			return changes;
		}

		if (before.topLevel != after.topLevel) {
			changes.add("component=TOPLEVEL"
					+ " | id="
					+ before.topLevel
					+ "->"
					+ after.topLevel);
		}

		final Set<String> labels = new LinkedHashSet<>();

		labels.addAll(before.widgets.keySet());
		labels.addAll(after.widgets.keySet());

		for (String label : labels) {
			final ResizeWidgetState beforeState = before.widgets.get(label);
			final ResizeWidgetState afterState = after.widgets.get(label);
			final String difference = ResizeWidgetState.describeDifference(label, beforeState, afterState);
			if (difference != null) {
				changes.add(difference);
			}
		}

		return changes;
	}

	private ResizeSnapshot snapshotResizeWidgets() {
		final Map<String, ResizeWidgetState> widgets = new LinkedHashMap<>();

		putResizeWidget(widgets, "SLOT_FIXED", client.getWidget(InterfaceID.Toplevel.CHAT_CONTAINER));
		putResizeWidget(widgets, "SLOT_CLASSIC", client.getWidget(InterfaceID.ToplevelOsrsStretch.CHAT_CONTAINER));
		putResizeWidget(widgets, "SLOT_MODERN", client.getWidget(InterfaceID.ToplevelPreEoc.CHAT_CONTAINER));

		final Widget universe = client.getWidget(InterfaceID.Chatbox.UNIVERSE);
		final Widget chatArea = client.getWidget(InterfaceID.Chatbox.CHATAREA);
		final Widget background = client.getWidget(InterfaceID.Chatbox.CHAT_BACKGROUND);

		putResizeWidget(widgets, "UNIVERSE", universe);
		putResizeWidget(widgets, "CHATAREA", chatArea);
		putResizeWidget(widgets, "CHAT_BACKGROUND", background);
		putResizeWidget(widgets, "CHAT_BACKGROUND_BODY", firstDynamicChild(background));
		putResizeWidget(widgets, "CONTROLS", client.getWidget(InterfaceID.Chatbox.CONTROLS));
		putResizeWidget(widgets, "CONTROLS_BACKGROUND", client.getWidget(InterfaceID.Chatbox.CONTROLS_BACKGROUND_GRAPHIC));
		putResizeWidget(widgets, "SCROLLAREA", client.getWidget(InterfaceID.Chatbox.SCROLLAREA));
		putResizeWidget(widgets, "CHATSCROLLBAR", client.getWidget(InterfaceID.Chatbox.CHATSCROLLBAR));

		putResizeWidget(widgets, "TAB_ALL", client.getWidget(InterfaceID.Chatbox.CHAT_ALL));
		putResizeWidget(widgets, "TAB_GAME", client.getWidget(InterfaceID.Chatbox.CHAT_GAME));
		putResizeWidget(widgets, "TAB_PUBLIC", client.getWidget(InterfaceID.Chatbox.CHAT_PUBLIC));
		putResizeWidget(widgets, "TAB_PRIVATE", client.getWidget(InterfaceID.Chatbox.CHAT_PRIVATE));
		putResizeWidget(widgets, "TAB_FRIENDSCHAT", client.getWidget(InterfaceID.Chatbox.CHAT_FRIENDSCHAT));
		putResizeWidget(widgets, "TAB_CLAN", client.getWidget(InterfaceID.Chatbox.CHAT_CLAN));
		putResizeWidget(widgets, "TAB_TRADE", client.getWidget(InterfaceID.Chatbox.CHAT_TRADE));

		return new ResizeSnapshot(client.getTopLevelInterfaceId(), widgets);
	}

	private static void putResizeWidget(Map<String, ResizeWidgetState> widgets, String label, Widget widget) {
		widgets.put(label, new ResizeWidgetState(widget));
	}

	private static Widget firstDynamicChild(Widget widget) {
		if (widget == null) {
			return null;
		}

		final Widget[] children = widget.getDynamicChildren();
		return children != null && children.length > 0
				? children[0]
				: null;
	}

	private ChatStateSnapshot snapshotChatState() {
		return new ChatStateSnapshot(
				client.getWidget(InterfaceID.Chatbox.SCROLLAREA),
				client.getWidget(InterfaceID.Chatbox.CHATSCROLLBAR),
				client.getWidget(InterfaceID.Chatbox.CHATAREA));
	}

	private String traceScriptArguments(ScriptPreFired event) {
		if (event == null || event.getScriptEvent() == null || event.getScriptEvent().getArguments() == null) {
			return "[]";
		}

		final Object[] arguments = event.getScriptEvent().getArguments();
		final List<String> values = new ArrayList<>();

		for (Object argument : arguments) {
			if (argument instanceof String) {
				String value = (String) argument;
				if (value.length() > MAX_LOGGED_STRING_LENGTH) {
					value = value.substring(0, MAX_LOGGED_STRING_LENGTH) + "...";
				}

				values.add("'" + value + "'");
				continue;
			}

			if (argument instanceof Widget) {
				final Widget widget = (Widget) argument;
				values.add("Widget(id=" + widget.getId() + ", identity=" + System.identityHashCode(widget) + ")");
				continue;
			}

			values.add(String.valueOf(argument));
		}

		return values.toString();
	}

	private String traceIntStackTail() {
		final int[] stack = client.getIntStack();
		final int size = client.getIntStackSize();
		if (stack == null || size <= 0 || size > stack.length) {
			return "[]";
		}

		final int start = Math.max(0, size - INT_STACK_TAIL_SIZE);

		return Arrays.toString(Arrays.copyOfRange(stack, start, size));
	}

	private String traceObjectStackStrings() {
		final Object[] stack = client.getObjectStack();
		final int size = client.getObjectStackSize();
		if (stack == null || size <= 0 || size > stack.length) {
			return "[]";
		}

		final List<String> strings = new ArrayList<>();

		for (int i = 0; i < size; i++) {
			final Object value = stack[i];
			if (!(value instanceof String)) {
				continue;
			}

			String text = (String) value;

			text = text
					.replace("\r\n", "\\n")
					.replace('\r', '\n')
					.replace("\n", "\\n");

			if (text.length() > MAX_LOGGED_STRING_LENGTH) {
				text = text.substring(0, MAX_LOGGED_STRING_LENGTH) + "...";
			}

			strings.add("'" + text + "'");
		}

		return strings.toString();
	}

	public synchronized void reset() {
		resizeTraceFrames.clear();
		armed = false;
	}

	private static final class ResizeTraceFrame {
		private int scriptId;
		private int depth;

		private ResizeSnapshot checkpoint;
		private ResizeSnapshot candidateEntry;

		private String intTailBefore;
		private String stringsBefore;
		private String arguments;
	}

	private static final class ChatStateSnapshot {
		private final boolean scrollAreaPresent;
		private final int viewportHeight;
		private final int scrollHeight;
		private final int scrollY;
		private final int staticChildren;
		private final int dynamicChildren;
		private final int nestedChildren;

		private final boolean scrollbarPresent;
		private final int scrollbarX;
		private final int scrollbarY;
		private final int scrollbarWidth;
		private final int scrollbarHeight;

		private final int chatAreaDynamicChildren;
		private final ChildRange childRange;

		private ChatStateSnapshot(Widget scrollArea, Widget scrollbar, Widget chatArea) {
			scrollAreaPresent = scrollArea != null;
			viewportHeight = scrollArea != null
					? scrollArea.getHeight()
					: 0;
			scrollHeight = scrollArea != null
					? scrollArea.getScrollHeight()
					: 0;
			scrollY = scrollArea != null
					? scrollArea.getScrollY()
					: 0;
			staticChildren = scrollArea != null
					? childCount(scrollArea.getStaticChildren())
					: 0;
			dynamicChildren = scrollArea != null
					? childCount(scrollArea.getDynamicChildren())
					: 0;
			nestedChildren = scrollArea != null
					? childCount(scrollArea.getNestedChildren())
					: 0;

			scrollbarPresent = scrollbar != null;
			scrollbarX = scrollbar != null
					? scrollbar.getRelativeX()
					: 0;
			scrollbarY = scrollbar != null
					? scrollbar.getRelativeY()
					: 0;
			scrollbarWidth = scrollbar != null
					? scrollbar.getWidth()
					: 0;
			scrollbarHeight = scrollbar != null
					? scrollbar.getHeight()
					: 0;

			chatAreaDynamicChildren = chatArea != null
					? childCount(chatArea.getDynamicChildren())
					: 0;
			childRange = ChildRange.of(scrollArea);
		}

		private String describe() {
			return "scrollArea=[present="
					+ scrollAreaPresent
					+ ", height="
					+ viewportHeight
					+ ", scrollHeight="
					+ scrollHeight
					+ ", scrollY="
					+ scrollY
					+ ", static="
					+ staticChildren
					+ ", dynamic="
					+ dynamicChildren
					+ ", nested="
					+ nestedChildren
					+ "]"
					+ " | directChildY="
					+ childRange.describe()
					+ " | scrollbar=[present="
					+ scrollbarPresent
					+ ", x="
					+ scrollbarX
					+ ", y="
					+ scrollbarY
					+ ", width="
					+ scrollbarWidth
					+ ", height="
					+ scrollbarHeight
					+ "]"
					+ " | chatAreaDynamic="
					+ chatAreaDynamicChildren;
		}

		private static int childCount(Widget[] children) {
			return children != null
					? children.length
					: 0;
		}
	}

	private static final class ChildRange {
		private int count;
		private int minY = Integer.MAX_VALUE;
		private int maxY = Integer.MIN_VALUE;

		private static ChildRange of(Widget widget) {
			final ChildRange range = new ChildRange();
			if (widget == null) {
				return range;
			}

			range.add(widget.getStaticChildren());
			range.add(widget.getDynamicChildren());
			return range;
		}

		private void add(Widget[] children) {
			if (children == null) {
				return;
			}

			for (Widget child : children) {
				if (child == null) {
					continue;
				}

				count++;
				minY = Math.min(minY, child.getRelativeY());
				maxY = Math.max(maxY, child.getRelativeY());
			}
		}

		private String describe() {
			if (count == 0) {
				return "[count=0]";
			}

			return "[count=" + count + ", min=" + minY + ", max=" + maxY + "]";
		}
	}

	private static final class ResizeSnapshot {
		private final int topLevel;
		private final Map<String, ResizeWidgetState> widgets;

		private ResizeSnapshot(int topLevel, Map<String, ResizeWidgetState> widgets) {
			this.topLevel = topLevel;
			this.widgets = widgets;
		}
	}

	private static final class ResizeWidgetState {
		private final boolean present;

		private final int identity;
		private final int id;
		private final int parentId;
		private final int parentIdentity;
		private final int index;
		private final int type;

		private final int originalX;
		private final int originalY;
		private final int originalWidth;
		private final int originalHeight;

		private final int relativeX;
		private final int relativeY;

		private final int width;
		private final int height;

		private final int widthMode;
		private final int heightMode;
		private final int xPositionMode;
		private final int yPositionMode;

		private final int spriteId;
		private final boolean spriteTiling;
		private final boolean hidden;

		private final int scrollY;
		private final int scrollHeight;

		private final int staticChildren;
		private final int dynamicChildren;
		private final int nestedChildren;

		private ResizeWidgetState(Widget widget) {
			if (widget == null) {
				present = false;

				identity = 0;
				id = -1;
				parentId = -1;
				parentIdentity = 0;
				index = -1;
				type = -1;

				originalX = 0;
				originalY = 0;
				originalWidth = 0;
				originalHeight = 0;

				relativeX = 0;
				relativeY = 0;

				width = 0;
				height = 0;

				widthMode = 0;
				heightMode = 0;
				xPositionMode = 0;
				yPositionMode = 0;

				spriteId = -1;
				spriteTiling = false;
				hidden = true;

				scrollY = 0;
				scrollHeight = 0;

				staticChildren = 0;
				dynamicChildren = 0;
				nestedChildren = 0;

				return;
			}

			present = true;

			identity = System.identityHashCode(widget);
			id = widget.getId();
			parentId = widget.getParentId();

			final Widget parent = widget.getParent();

			parentIdentity = parent != null
					? System.identityHashCode(parent)
					: 0;

			index = widget.getIndex();
			type = widget.getType();

			originalX = widget.getOriginalX();
			originalY = widget.getOriginalY();
			originalWidth = widget.getOriginalWidth();
			originalHeight = widget.getOriginalHeight();

			relativeX = widget.getRelativeX();
			relativeY = widget.getRelativeY();

			width = widget.getWidth();
			height = widget.getHeight();

			widthMode = widget.getWidthMode();
			heightMode = widget.getHeightMode();
			xPositionMode = widget.getXPositionMode();
			yPositionMode = widget.getYPositionMode();

			spriteId = widget.getSpriteId();
			spriteTiling = widget.getSpriteTiling();
			hidden = widget.isHidden();

			scrollY = widget.getScrollY();
			scrollHeight = widget.getScrollHeight();

			staticChildren = childCount(widget.getStaticChildren());
			dynamicChildren = childCount(widget.getDynamicChildren());
			nestedChildren = childCount(widget.getNestedChildren());
		}

		private static String describeDifference(String label, ResizeWidgetState before, ResizeWidgetState after) {
			if (before == null && after == null) {
				return null;
			}

			if (before == null) {
				return "component=" + label + " | state=MISSING->" + after.describe();
			}

			if (after == null) {
				return "component=" + label + " | state=" + before.describe() + "->MISSING";
			}

			final StringBuilder difference = new StringBuilder();

			appendDifference(difference, "present", before.present, after.present);

			if (!before.present && !after.present) {
				return difference.length() == 0
						? null
						: "component=" + label + " | " + difference;
			}

			appendDifference(difference, "identity", before.identity, after.identity);
			appendDifference(difference, "id", before.id, after.id);
			appendDifference(difference, "parentId", before.parentId, after.parentId);
			appendDifference(difference, "parentIdentity", before.parentIdentity, after.parentIdentity);
			appendDifference(difference, "index", before.index, after.index);
			appendDifference(difference, "type", before.type, after.type);

			appendDifference(difference, "originalX", before.originalX, after.originalX);
			appendDifference(difference, "originalY", before.originalY, after.originalY);
			appendDifference(difference, "originalWidth", before.originalWidth, after.originalWidth);
			appendDifference(difference, "originalHeight", before.originalHeight, after.originalHeight);

			appendDifference(difference, "relativeX", before.relativeX, after.relativeX);
			appendDifference(difference, "relativeY", before.relativeY, after.relativeY);
			appendDifference(difference, "width", before.width, after.width);
			appendDifference(difference, "height", before.height, after.height);

			appendDifference(difference, "widthMode", before.widthMode, after.widthMode);
			appendDifference(difference, "heightMode", before.heightMode, after.heightMode);
			appendDifference(difference, "xMode", before.xPositionMode, after.xPositionMode);
			appendDifference(difference, "yMode", before.yPositionMode, after.yPositionMode);

			appendDifference(difference, "spriteId", before.spriteId, after.spriteId);
			appendDifference(difference, "spriteTiling", before.spriteTiling, after.spriteTiling);
			appendDifference(difference, "hidden", before.hidden, after.hidden);

			appendDifference(difference, "scrollY", before.scrollY, after.scrollY);
			appendDifference(difference, "scrollHeight", before.scrollHeight, after.scrollHeight);

			appendDifference(difference, "staticChildren", before.staticChildren, after.staticChildren);
			appendDifference(difference, "dynamicChildren", before.dynamicChildren, after.dynamicChildren);
			appendDifference(difference, "nestedChildren", before.nestedChildren, after.nestedChildren);

			return difference.length() == 0
					? null
					: "component=" + label + " | " + difference;
		}

		private String describe() {
			if (!present) {
				return "MISSING";
			}

			return "id="
					+ id
					+ ", identity="
					+ identity
					+ ", original=["
					+ originalX
					+ ","
					+ originalY
					+ ","
					+ originalWidth
					+ "x"
					+ originalHeight
					+ "]"
					+ ", relative=["
					+ relativeX
					+ ","
					+ relativeY
					+ "]"
					+ ", calculated=["
					+ width
					+ "x"
					+ height
					+ "]";
		}

		private static int childCount(Widget[] children) {
			return children != null
					? children.length
					: 0;
		}

		private static void appendDifference(StringBuilder builder, String name, int before, int after) {
			if (before == after) {
				return;
			}

			appendSeparator(builder);

			builder.append(name)
					.append('=')
					.append(before)
					.append("->")
					.append(after);
		}

		private static void appendDifference(StringBuilder builder, String name, boolean before, boolean after) {
			if (before == after) {
				return;
			}

			appendSeparator(builder);

			builder.append(name)
					.append('=')
					.append(before)
					.append("->")
					.append(after);
		}

		private static void appendSeparator(StringBuilder builder) {
			if (builder.length() > 0) {
				builder.append(", ");
			}
		}
	}
}

package com.bigboldchat.debug;

import java.util.Locale;

import lombok.extern.slf4j.Slf4j;

import net.runelite.api.events.CommandExecuted;

/**
 * Collects Chat XL performance metrics.
 */
@Slf4j
public final class PerformanceMetrics {
	private static final String COMMAND = "debug-performance";
	private static final long REPORT_INTERVAL_NANOS = 10_000_000_000L;

	private static final int GAME_BODY_SCRIPT = 199;
	private static final int CHAT_BODY_SCRIPT = 203;
	private static final int CHANNEL_BODY_SCRIPT = 4483;

	/*
	 * TIMINGS
	 */

	// Measure Script PRE processing time.
	private final TimingMetric pre199 = new TimingMetric();
	private final TimingMetric pre203 = new TimingMetric();
	private final TimingMetric pre4483 = new TimingMetric();

	// Measure Script POST processing time.
	private final TimingMetric post199 = new TimingMetric();
	private final TimingMetric post203 = new TimingMetric();
	private final TimingMetric post4483 = new TimingMetric();

	// Measure construction measurement time.
	private final TimingMetric measurement = new TimingMetric();

	// Measure semantic text normalization time.
	private final TimingMetric normalization = new TimingMetric();

	// Measure uncached FontTypeFace resolution time.
	private final TimingMetric fontResolution = new TimingMetric();

	// Measure chatbox geometry application time.
	private final TimingMetric resizeApply = new TimingMetric();

	/*
	 * COUNTERS
	 */

	// Count FontTypeFace cache activity.
	private long fontCacheHits;
	private long fontCacheMisses;

	// Count widgets examined during chat correlation.
	private long widgetsExamined;

	// Count full chat-surface searches.
	private long surfaceSearches;

	// Number of row searches.
	private long rowSearches;

	// Number of row-candidates searches.
	private long rowCandidates;

	// Count persistent row-index full builds, local repairs, and direct reuses.
	private long rowIndexBuilds;
	private long rowIndexRepairs;
	private long rowIndexReuses;

	// Count correlation fallback requests.
	private long fallbackSearches;

	// Count actual lazy fallback index builds.
	private long fallbackBuilds;

	// Count fallback requests served by an already-built per-POST index.
	private long fallbackReuses;

	// Count rank-icon searches, full-tree fallbacks, and examined nodes.
	private long rankSearches;
	private long rankFallbacks;
	private long rankNodesExamined;

	/*
	 * Classify strict row-first rank misses before shallow recovery.
	 */
	private long rankRowNoSprite;
	private long rankRowXMismatch;
	private long rankRowYMismatch;
	private long rankShallowRecoveries;

	/*
	 * Classify recursive fallback results.
	 */
	private long rankFallbackHits;
	private long rankFallbackMisses;

	// Count widget mutations.
	private long widgetMutations;

	// Count widget revalidation calls.
	private long revalidates;

	// Count initiated chat refreshes.
	private long refreshChatCalls;
	private long refreshStartup;
	private long refreshFontChanged;
	private long refreshShutdown;
	private long refreshWidthChanged;
	private long refreshHeightChanged;
	private long refreshOther;

	// Count chatbox-resize geometry activity.
	private long resizeApplies;
	private long resizeNoops;
	private long resizeWidthChanges;
	private long resizeHeightChanges;
	private long resizeMissingWidgets;
	private long resizeRestores;
	private long reportStartedAt;

	private boolean enabled;

	public boolean isEnabled() {
		return enabled;
	}

	public void reset() {
		enabled = false;
		resetWindow(0L);
	}

	public boolean onCommandExecuted(CommandExecuted event) {
		if (event == null || !COMMAND.equalsIgnoreCase(event.getCommand())) {
			return false;
		}

		if (enabled) {
			reportNow();
			enabled = false;
		} else {
			enabled = true;
			resetWindow(System.nanoTime());
		}

		log.debug(
				"[Chat XL][Performance] {}", enabled
						? "ARMED"
						: "DISARMED");

		return true;
	}

	/*
	 * RECORDING
	 */

	public void recordPre(int scriptId, long elapsedNanos) {
		if (!enabled) {
			return;
		}

		final TimingMetric metric = preMetric(scriptId);
		if (metric != null) {
			metric.record(elapsedNanos);
		}
	}

	public void recordPost(int scriptId, long elapsedNanos) {
		if (!enabled) {
			return;
		}

		final TimingMetric metric = postMetric(scriptId);
		if (metric != null) {
			metric.record(elapsedNanos);
		}
	}

	public void recordMeasurement(long elapsedNanos) {
		if (!enabled) {
			return;
		}

		measurement.record(elapsedNanos);
	}

	public void recordNormalization(long elapsedNanos) {
		if (!enabled) {
			return;
		}

		normalization.record(elapsedNanos);
	}

	public void recordFontCacheHit() {
		if (!enabled) {
			return;
		}

		fontCacheHits++;
	}

	public void recordFontCacheMiss(long elapsedNanos) {
		if (!enabled) {
			return;
		}

		fontCacheMisses++;
		fontResolution.record(elapsedNanos);
	}

	public void recordWidgetsExamined(int count) {
		if (!enabled) {
			return;
		}

		if (count > 0) {
			widgetsExamined += count;
		}
	}

	public void recordSurfaceSearch() {
		if (!enabled) {
			return;
		}

		surfaceSearches++;
	}

	public void recordRowSearches(int candidates) {
		if (!enabled) {
			return;
		}

		rowSearches++;

		if (candidates > 0) {
			rowCandidates += candidates;
		}
	}

	public void recordRowIndexBuild() {
		if (!enabled) {
			return;
		}

		rowIndexBuilds++;
	}

	public void recordRowIndexRepair() {
		if (!enabled) {
			return;
		}

		rowIndexRepairs++;
	}

	public void recordRowIndexReuse() {
		if (!enabled) {
			return;
		}

		rowIndexReuses++;
	}

	public void recordFallbackSearch() {
		if (!enabled) {
			return;
		}

		fallbackSearches++;
	}

	public void recordFallbackBuild() {
		if (!enabled) {
			return;
		}

		fallbackBuilds++;
	}

	public void recordFallbackReuse() {
		if (!enabled) {
			return;
		}

		fallbackReuses++;
	}

	public void recordRankSearch() {
		if (!enabled) {
			return;
		}

		rankSearches++;
	}

	public void recordRankFallback() {
		if (!enabled) {
			return;
		}

		rankFallbacks++;
	}

	public void recordRankRowNoSprite() {
		if (!enabled) {
			return;
		}

		rankRowNoSprite++;
	}

	public void recordRankRowXMismatch() {
		if (!enabled) {
			return;
		}

		rankRowXMismatch++;
	}

	public void recordRankRowYMismatch() {
		if (!enabled) {
			return;
		}

		rankRowYMismatch++;
	}

	public void recordRankShallowRecovery() {
		if (!enabled) {
			return;
		}

		rankShallowRecoveries++;
	}

	public void recordRankFallbackHit() {
		if (!enabled) {
			return;
		}

		rankFallbackHits++;
	}

	public void recordRankFallbackMiss() {
		if (!enabled) {
			return;
		}

		rankFallbackMisses++;
	}

	public void recordRankNodesExamined(int count) {
		if (!enabled) {
			return;
		}

		if (count > 0) {
			rankNodesExamined += count;
		}
	}

	public void recordWidgetMutation() {
		if (!enabled) {
			return;
		}

		widgetMutations++;
	}

	public void recordRevalidate() {
		if (!enabled) {
			return;
		}

		revalidates++;
	}

	public void recordResizeApply(long elapsedNanos, boolean widthChanged, boolean heightChanged) {
		if (!enabled) {
			return;
		}

		resizeApply.record(elapsedNanos);
		resizeApplies++;

		if (!widthChanged && !heightChanged) {
			resizeNoops++;
		}

		if (widthChanged) {
			resizeWidthChanges++;
		}

		if (heightChanged) {
			resizeHeightChanges++;
		}
	}

	public void recordResizeMissingWidgets() {
		if (!enabled) {
			return;
		}

		resizeMissingWidgets++;
	}

	public void recordResizeRestore() {
		if (!enabled) {
			return;
		}

		resizeRestores++;
	}

	public void recordRefreshChat(RefreshReason reason) {
		if (!enabled) {
			return;
		}

		refreshChatCalls++;

		if (reason == null) {
			refreshOther++;
			return;
		}

		switch (reason) {
			case STARTUP:
				refreshStartup++;
				break;
			case FONT_CHANGED:
				refreshFontChanged++;
				break;
			case SHUTDOWN:
				refreshShutdown++;
				break;
			case WIDTH_CHANGED:
				refreshWidthChanged++;
				break;
			case HEIGHT_CHANGED:
				refreshHeightChanged++;
				break;
			default:
				refreshOther++;
				break;
		}
	}

	/*
	 * REPORTING
	 */

	public void reportIfDue() {
		if (!enabled) {
			return;
		}

		final long now = System.nanoTime();
		if (now - reportStartedAt < REPORT_INTERVAL_NANOS) {
			return;
		}

		report(now);
	}

	public void reportNow() {
		if (!enabled) {
			return;
		}

		report(System.nanoTime());
	}

	private void report(long now) {
		final long elapsedNanos = now - reportStartedAt;
		if (elapsedNanos <= 0L) {
			return;
		}

		final double elapsedSeconds = elapsedNanos / 1_000_000_000.0;

		log.debug(
				"[Chat XL][Performance] Window={}",
				String.format(Locale.ROOT, "%.3fs", elapsedSeconds));

		log.debug(
				"[Chat XL][Performance] PRE"
						+ " | 199={}"
						+ " | 203={}"
						+ " | 4483={}",
				formatTiming(pre199),
				formatTiming(pre203),
				formatTiming(pre4483));

		log.debug(
				"[Chat XL][Performance] POST"
						+ " | 199={}"
						+ " | 203={}"
						+ " | 4483={}",
				formatTiming(post199),
				formatTiming(post203),
				formatTiming(post4483));

		log.debug(
				"[Chat XL][Performance] SERVICES"
						+ " | Measurement={}"
						+ " | Normalize={}"
						+ " | FontResolve={}"
						+ " | FontCacheHits={}"
						+ " | FontCacheMisses={}",
				formatTiming(measurement),
				formatTiming(normalization),
				formatTiming(fontResolution),
				fontCacheHits,
				fontCacheMisses);

		log.debug(
				"[Chat XL][Performance] CORRELATION"
						+ " | Widgets={}"
						+ " | RowSearches={}"
						+ " | RowCandidates={}"
						+ " | RowIndexBuilds={}"
						+ " | RowIndexRepairs={}"
						+ " | RowIndexReuses={}"
						+ " | SurfaceSearches={}"
						+ " | FallbackSearches={}"
						+ " | FallbackBuilds={}"
						+ " | FallbackReuses={}"
						+ " | RankSearches={}"
						+ " | RankFallbacks={}"
						+ " | RankNoSprite={}"
						+ " | RankXMismatch={}"
						+ " | RankYMismatch={}"
						+ " | RankShallowRecoveries={}"
						+ " | RankFallbackHits={}"
						+ " | RankFallbackMisses={}"
						+ " | RankNodes={}",
				widgetsExamined,
				rowSearches,
				rowCandidates,
				rowIndexBuilds,
				rowIndexRepairs,
				rowIndexReuses,
				surfaceSearches,
				fallbackSearches,
				fallbackBuilds,
				fallbackReuses,
				rankSearches,
				rankFallbacks,
				rankRowNoSprite,
				rankRowXMismatch,
				rankRowYMismatch,
				rankShallowRecoveries,
				rankFallbackHits,
				rankFallbackMisses,
				rankNodesExamined);

		log.debug(
				"[Chat XL][Performance] PRESENTATION"
						+ " | Mutations={}"
						+ " | Revalidates={}",
				widgetMutations,
				revalidates);

		log.debug(
				"[Chat XL][Performance] RESIZE"
						+ " | Apply={}"
						+ " | Applies={}"
						+ " | Noops={}"
						+ " | WidthChanges={}"
						+ " | HeightChanges={}"
						+ " | MissingWidgets={}"
						+ " | Restores={}",
				formatTiming(resizeApply),
				resizeApplies,
				resizeNoops,
				resizeWidthChanges,
				resizeHeightChanges,
				resizeMissingWidgets,
				resizeRestores);

		log.debug(
				"[Chat XL][Performance] REFRESH"
						+ " | Total={}"
						+ " | Startup={}"
						+ " | FontChanged={}"
						+ " | Shutdown={}"
						+ " | WidthChanged={}"
						+ " | HeightChanged={}"
						+ " | Other={}",
				refreshChatCalls,
				refreshStartup,
				refreshFontChanged,
				refreshShutdown,
				refreshWidthChanged,
				refreshHeightChanged,
				refreshOther);

		resetWindow(now);
	}

	/*
	 * HELPERS
	 */

	private TimingMetric preMetric(int scriptId) {
		switch (scriptId) {
			case GAME_BODY_SCRIPT:
				return pre199;
			case CHAT_BODY_SCRIPT:
				return pre203;
			case CHANNEL_BODY_SCRIPT:
				return pre4483;
			default:
				return null;
		}
	}

	private TimingMetric postMetric(int scriptId) {
		switch (scriptId) {
			case GAME_BODY_SCRIPT:
				return post199;
			case CHAT_BODY_SCRIPT:
				return post203;
			case CHANNEL_BODY_SCRIPT:
				return post4483;
			default:
				return null;
		}
	}

	private static String formatTiming(TimingMetric metric) {
		if (metric == null || metric.count == 0L) {
			return "calls=0 avg=0.000ms max=0.000ms";
		}

		return String.format(
				Locale.ROOT,
				"calls=%d avg=%.6fms max=%.6fms",
				metric.count,
				metric.averageMilliseconds(),
				metric.maxMilliseconds());
	}

	private void resetWindow(long now) {
		pre199.reset();
		pre203.reset();
		pre4483.reset();

		post199.reset();
		post203.reset();
		post4483.reset();

		measurement.reset();
		normalization.reset();
		fontResolution.reset();
		resizeApply.reset();

		fontCacheHits = 0L;
		fontCacheMisses = 0L;
		widgetsExamined = 0L;
		rowSearches = 0L;
		rowCandidates = 0L;
		rowIndexBuilds = 0L;
		rowIndexRepairs = 0L;
		rowIndexReuses = 0L;
		surfaceSearches = 0L;
		fallbackSearches = 0L;
		fallbackBuilds = 0L;
		fallbackReuses = 0L;
		rankSearches = 0L;
		rankFallbacks = 0L;
		rankRowNoSprite = 0L;
		rankRowXMismatch = 0L;
		rankRowYMismatch = 0L;
		rankShallowRecoveries = 0L;
		rankFallbackHits = 0L;
		rankFallbackMisses = 0L;
		rankNodesExamined = 0L;
		widgetMutations = 0L;
		revalidates = 0L;
		refreshChatCalls = 0L;
		refreshStartup = 0L;
		refreshFontChanged = 0L;
		refreshShutdown = 0L;
		refreshWidthChanged = 0L;
		refreshHeightChanged = 0L;
		refreshOther = 0L;
		resizeApplies = 0L;
		resizeNoops = 0L;
		resizeWidthChanges = 0L;
		resizeHeightChanges = 0L;
		resizeMissingWidgets = 0L;
		resizeRestores = 0L;
		reportStartedAt = now;
	}

	public enum RefreshReason {
		STARTUP,
		FONT_CHANGED,
		SHUTDOWN,
		WIDTH_CHANGED,
		HEIGHT_CHANGED,
		OTHER
	}

	private static final class TimingMetric {
		private long count;
		private long totalNanos;
		private long maxNanos;

		private void record(long elapsedNanos) {
			if (elapsedNanos < 0L) {
				return;
			}

			count++;
			totalNanos += elapsedNanos;

			if (elapsedNanos > maxNanos) {
				maxNanos = elapsedNanos;
			}
		}

		private double averageMilliseconds() {
			if (count == 0L) {
				return 0.0;
			}

			return totalNanos / (double) count / 1_000_000.0;
		}

		private double maxMilliseconds() {
			return maxNanos / 1_000_000.0;
		}

		private void reset() {
			count = 0L;
			totalNanos = 0L;
			maxNanos = 0L;
		}
	}
}

package com.bigboldchat.debug;

import com.bigboldchat.ChatXL;

import javax.inject.Inject;

import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.CommandExecuted;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.externalplugins.ExternalPluginManager;
import net.runelite.client.externalplugins.PluginHubManifest;

/**
 * Owns Chat XL install, update, uninstall, and debug update messages.
 */
public final class UpdateMessages {
	private static final String COMMAND = "debug-updates";
	private static final String CONFIG_GROUP = "bigboldchat";
	private static final String VERSION_CONFIG_KEY = "lastNotifiedVersion";

	private static final String INSTALL_MESSAGE = "Thank you for installing ChatXL!"
			+ " Report any issues you find to Github.";
	private static final String UNINSTALL_MESSAGE = "Thank you for using ChatXL!"
			+ " Please submit a review/issue report on Github of your experience.";
	private static final String UPDATE_MESSAGE = "Movable Split-PM host (hold Alt), Split-PM username alignment, improved chatbox collision handling, and updated hotkeys for hiding/showing chat buttons and clearing chat.";

	private final Client client;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final ExternalPluginManager externalPluginManager;

	@Inject
	public UpdateMessages(
			Client client,
			ClientThread clientThread,
			ConfigManager configManager,
			ExternalPluginManager externalPluginManager) {
		this.client = client;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.externalPluginManager = externalPluginManager;
	}

	public boolean onCommandExecuted(CommandExecuted event) {
		if (event == null || !COMMAND.equalsIgnoreCase(event.getCommand())) {
			return false;
		}

		clientThread.invokeLater(this::showUpdateTests);
		return true;
	}

	public void onLoggedIn() {
		if (client.getGameState() == GameState.LOGGED_IN) {
			showUpdateMessage();
		}
	}

	public boolean prepareShutdown() {
		final boolean uninstalling = isBeingUninstalled();
		if (uninstalling) {
			configManager.unsetConfiguration(CONFIG_GROUP, VERSION_CONFIG_KEY);
		}

		return uninstalling;
	}

	public void finishShutdown(boolean uninstalling) {
		if (uninstalling && client.getGameState() == GameState.LOGGED_IN) {
			showUninstallMessage();
		}
	}

	private void showUpdateTests() {
		showInstallMessage();

		final String currentVersion = getCurrentVersion();
		showVersionMessage(currentVersion != null
				? currentVersion
				: "3.2.1");

		showUninstallMessage();
	}

	private String getCurrentVersion() {
		final PluginHubManifest.DisplayData displayData = ExternalPluginManager.getDisplayData(ChatXL.class);
		return displayData != null
				? displayData.getVersion()
				: null;
	}

	private boolean isBeingUninstalled() {
		final String internalName = ExternalPluginManager.getInternalName(ChatXL.class);
		return internalName != null && !externalPluginManager.getInstalledExternalPlugins().contains(internalName);
	}

	private void showUpdateMessage() {
		final String previousVersion = configManager.getConfiguration(CONFIG_GROUP, VERSION_CONFIG_KEY);
		final String currentVersion = getCurrentVersion();
		if (currentVersion == null || currentVersion.equals(previousVersion)) {
			return;
		}

		if (previousVersion == null || previousVersion.isEmpty()) {
			showInstallMessage();
		} else {
			showVersionMessage(currentVersion);
		}

		configManager.setConfiguration(CONFIG_GROUP, VERSION_CONFIG_KEY, currentVersion);
	}

	private void showInstallMessage() {
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", prefix() + INSTALL_MESSAGE, null);
	}

	private void showVersionMessage(String currentVersion) {
		client.addChatMessage(
				ChatMessageType.GAMEMESSAGE, "", prefix() + "Updated to v" + currentVersion + "!", null);

		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", prefix() + UPDATE_MESSAGE, null);
	}

	private void showUninstallMessage() {
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", prefix() + UNINSTALL_MESSAGE, null);
	}

	private static String prefix() {
		return "<col=FF981F><shad=E1140A>ChatXL:</shad></col> ";
	}
}

