		addChatTest(
				ChatMessageType.CLAN_GUEST_CHAT,
				guestRank + "Player",
				"ChatXL CLAN_GUEST_CHAT test.",
				CHANNEL_NAME);
		addChatTest(
				ChatMessageType.CLAN_GUEST_MESSAGE,
				"",
				"ChatXL CLAN_GUEST_MESSAGE test.",
				CHANNEL_NAME);

		addChatTest(
				ChatMessageType.CLAN_GIM_CHAT,
				gimRank + IconID.GROUP_IRONMAN.toString() + "Player",
				"ChatXL CLAN_GIM_CHAT test.",
				CHANNEL_NAME);
		addChatTest(
				ChatMessageType.CLAN_GIM_MESSAGE,
				"",
				"ChatXL CLAN_GIM_MESSAGE test.",
				CHANNEL_NAME);
	}

	/*
	 * ================================================================
	 * TRADE / CHALLENGE
	 * ================================================================
	 */

	private void showTradeMessages() {
		addChatTest(ChatMessageType.TRADE_SENT, "Player");
		addChatTest(ChatMessageType.TRADEREQ, "Player");
		addChatTest(ChatMessageType.TRADE, "");
		addChatTest(ChatMessageType.CHALREQ_TRADE, "Player");
		addChatTest(ChatMessageType.CHALREQ_FRIENDSCHAT, "Player");
		addChatTest(ChatMessageType.CHALREQ_CLANCHAT, "Player");
	}

	/*
	 * ================================================================
	 * EXAMINE
	 * ================================================================
	 */

	private void showExamineMessages() {
		addChatTest(ChatMessageType.ITEM_EXAMINE, "");
		addChatTest(ChatMessageType.NPC_EXAMINE, "");
		addChatTest(ChatMessageType.OBJECT_EXAMINE, "");
	}

	/*
	 * ================================================================
	 * MESSAGE HELPERS
	 * ================================================================
	 */

	private void addChatTest(ChatMessageType type, String name) {
		addChatTest(type, name, type.name() + " test.", null);
	}

	private void addChatTest(ChatMessageType type, String name, String message) {
		addChatTest(type, name, message, null);
	}

	private void addChatTest(ChatMessageType type, String name, String message, String sender) {
		client.addChatMessage(type, name, message, sender);
	}

	/*
	 * ================================================================
	 * ICON HELPERS
	 * ================================================================
	 */

	private String iconTag(int iconId) {
		return iconId >= 0
				? "<img=" + iconId + ">"
				: "";
	}

	private String clanRankIcon(int spriteId) {
		final EnumComposition rankGraphics = client.getEnum(EnumID.CLAN_RANK_GRAPHIC);
		if (rankGraphics == null || rankGraphics.getKeys() == null) {
			return "";
		}

		for (int key : rankGraphics.getKeys()) {
			if (rankGraphics.getIntValue(key) != spriteId) {
				continue;
			}

			final int iconId = chatIconManager.getIconNumber(new ClanTitle(key, "ChatXL"));

			return iconTag(iconId);
		}

		return "";
	}
}

package com.bigboldchat.layout;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;

/**
 * Snapshots visible top-level interface rectangles that either constrain
 * plugin-managed geometry or occlude the chatbox as foreground content.
 */
final class InterfaceBounds {
	private final Rectangle canvas;
	private final List<Rectangle> obstacles;
	private final List<Rectangle> foregrounds;

	private InterfaceBounds(Rectangle canvas, List<Rectangle> obstacles, List<Rectangle> foregrounds) {
		this.canvas = canvas;
		this.obstacles = Collections.unmodifiableList(obstacles);
		this.foregrounds = Collections.unmodifiableList(foregrounds);
	}

	static InterfaceBounds capture(Client client) {
		final Rectangle canvas = new Rectangle(
				0, 0, Math.max(0, client.getCanvasWidth()), Math.max(0, client.getCanvasHeight()));
		final List<Rectangle> obstacles = new ArrayList<>(6);
		final List<Rectangle> foregrounds = new ArrayList<>(2);

		final int topLevel = client.getTopLevelInterfaceId();
		if (topLevel == InterfaceID.TOPLEVEL_OSRS_STRETCH) {
			add(obstacles, canvas, client.getWidget(InterfaceID.ToplevelOsrsStretch.SIDE_MENU));
			add(obstacles, canvas, client.getWidget(InterfaceID.ToplevelOsrsStretch.MAP_CONTAINER));
			add(obstacles, canvas, client.getWidget(InterfaceID.ToplevelOsrsStretch.ORBS));
			addMounted(client, foregrounds, canvas, InterfaceID.ToplevelOsrsStretch.MAINMODAL);
			addMounted(client, foregrounds, canvas, InterfaceID.ToplevelOsrsStretch.FLOATER);
		} else if (topLevel == InterfaceID.TOPLEVEL_PRE_EOC) {
			addLive(obstacles, canvas, client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_BACKGROUND));
			addLive(obstacles, canvas, client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_STATIC_LAYER));
			addLive(obstacles, canvas, client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_MOVABLE_LAYER));
			addLive(obstacles, canvas, client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_CONTAINER));
			add(obstacles, canvas, client.getWidget(InterfaceID.ToplevelPreEoc.MAP_CONTAINER));
			add(obstacles, canvas, client.getWidget(InterfaceID.ToplevelPreEoc.ORBS));
			addMounted(client, foregrounds, canvas, InterfaceID.ToplevelPreEoc.MAINMODAL);
			addMounted(client, foregrounds, canvas, InterfaceID.ToplevelPreEoc.FLOATER);
		}

		return new InterfaceBounds(canvas, obstacles, foregrounds);
	}

	Rectangle getCanvas() {
		return canvas;
	}

	List<Rectangle> getObstacles() {
		return obstacles;
	}

	boolean intersectsForeground(Rectangle bounds) {
		if (bounds == null || bounds.isEmpty()) {
			return false;
		}

		for (Rectangle foreground : foregrounds) {
			if (bounds.intersects(foreground)) {
				return true;
			}
		}

		return false;
	}

	static Rectangle liveBounds(Widget widget) {
		if (widget == null || widget.isHidden() || widget.getWidth() <= 0 || widget.getHeight() <= 0) {
			return null;
		}

		int x = widget.getRelativeX();
		int y = widget.getRelativeY();
		for (Widget parent = widget.getParent(); parent != null; parent = parent.getParent()) {
			x += parent.getRelativeX();
			y += parent.getRelativeY();
		}

		return new Rectangle(x, y, widget.getWidth(), widget.getHeight());
	}

	private static void addMounted(
			Client client, List<Rectangle> foregrounds, Rectangle canvas, int componentId) {
		if (client.getComponentTable() == null || client.getComponentTable().get(componentId) == null) {
			return;
		}

		final Widget mount = client.getWidget(componentId);
		final Rectangle bounds = mountedContentBounds(mount, canvas);
		if (bounds == null || bounds.isEmpty()) {
			return;
		}

		foregrounds.add(bounds);
	}

	private static Rectangle mountedContentBounds(Widget mount, Rectangle canvas) {
		if (mount == null || mount.isHidden()) {
			return null;
		}

		final Rectangle mountBounds = liveBounds(mount);
		if (mountBounds == null) {
			return null;
		}

		final Rectangle clip = mountBounds.intersection(canvas);
		if (clip.isEmpty()) {
			return null;
		}

		Rectangle bounds = null;
		for (Widget root : mount.getNestedChildren()) {
			bounds = union(bounds, visibleContentBounds(root, clip));
		}

		return bounds;
	}

	private static Rectangle visibleContentBounds(Widget widget, Rectangle clip) {
		if (widget == null || widget.isHidden() || clip == null || clip.isEmpty()) {
			return null;
		}

		final Rectangle widgetBounds = widget.getBounds();
		if (widgetBounds == null || widgetBounds.width <= 0 || widgetBounds.height <= 0) {
			return null;
		}

		final Rectangle visible = widgetBounds.intersection(clip);
		if (visible.isEmpty()) {
			return null;
		}

		Rectangle bounds = widget.getType() != WidgetType.LAYER && widget.getOpacity() != 255
				? new Rectangle(visible)
				: null;

		for (Widget child : widget.getStaticChildren()) {
			bounds = union(bounds, visibleContentBounds(child, visible));
		}

		for (Widget child : widget.getDynamicChildren()) {
			bounds = union(bounds, visibleContentBounds(child, visible));
		}

		for (Widget child : widget.getNestedChildren()) {
			bounds = union(bounds, visibleContentBounds(child, visible));
		}

		return bounds;
	}

	private static Rectangle union(Rectangle first, Rectangle second) {
		if (second == null || second.isEmpty()) {
			return first;
		}

		if (first == null) {
			return new Rectangle(second);
		}

		first.add(second);
		return first;
	}

	private static void addLive(List<Rectangle> obstacles, Rectangle canvas, Widget widget) {
		final Rectangle bounds = liveBounds(widget);
		if (bounds == null || !bounds.intersects(canvas)) {
			return;
		}

		obstacles.add(bounds);
	}

	private static void add(List<Rectangle> obstacles, Rectangle canvas, Widget widget) {
		if (widget == null || widget.isHidden()) {
			return;
		}

		final Rectangle bounds = widget.getBounds();
		if (bounds == null || bounds.width <= 0 || bounds.height <= 0 || !bounds.intersects(canvas)) {
			return;
		}

		obstacles.add(new Rectangle(bounds));
	}
}

package com.bigboldchat.layout;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;

import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * Owns plugin-managed layout changes to the Modern side container.
 */
public final class SideContainerLayout {
	private final Client client;

	private boolean nativeLayoutRunning;
	private boolean pluginTwoRows;
	private boolean oneRowKnown;
	private int oneRowMovableX;
	private int oneRowMovableY;
	private int oneRowContainerY;
	private RelativeBounds movableOneRow;
	private List<RelativeBounds> movableChildrenOneRow = new ArrayList<>();
	private RelativeBounds backgroundOneRow;
	private RelativeBounds containerOneRow;

	public SideContainerLayout(Client client) {
		this.client = client;
	}

	/**
	 * Suspends plugin row ownership while RuneScape chooses its native layout.
	 */
	public void beginNativeLayout() {
		if (!isModernLayout()) {
			reset();
			return;
		}

		nativeLayoutRunning = true;
	}

	/**
	 * Accepts the row arrangement chosen by RuneScape's native resize script.
	 */
	public void endNativeLayout() {
		nativeLayoutRunning = false;
		pluginTwoRows = false;

		final Widgets widgets = getWidgets();
		if (widgets == null) {
			clearOneRow();
			return;
		}

		if (isTwoRows(widgets.staticLayer, widgets.movableLayer)) {
			clearOneRow();
			return;
		}

		captureOneRow(widgets);
	}

	/**
	 * Gives the Modern button strip a second row when the configured chatbox
	 * reaches only the movable half of the native one-row strip.
	 */
	public Result apply(Widget slot, int configuredWidth, int configuredHeight) {
		if (slot == null || !isModernLayout()) {
			reset();
			return Result.NONE;
		}

		if (nativeLayoutRunning) {
			return Result.NONE;
		}

		final Widgets widgets = getWidgets();
		if (widgets == null) {
			return Result.NONE;
		}

		final boolean currentTwoRows = isTwoRows(widgets.staticLayer, widgets.movableLayer);
		if (pluginTwoRows && !currentTwoRows) {
			pluginTwoRows = false;
			captureOneRow(widgets);
		} else if (!pluginTwoRows) {
			if (currentTwoRows) {
				return Result.NONE;
			}

			captureOneRow(widgets);
		}

		if (!oneRowKnown) {
			return Result.NONE;
		}

		final Rectangle desired = desiredBounds(slot, configuredWidth, configuredHeight);
		if (desired == null) {
			return Result.NONE;
		}

		if (needsTwoRows(desired, widgets)) {
			return pluginTwoRows
					? Result.NONE
					: applyTwoRows(widgets, desired);
		}

		return pluginTwoRows
				? applyOneRow(widgets)
				: Result.NONE;
	}

	public Result restoreNative() {
		if (!pluginTwoRows || !oneRowKnown) {
			reset();
			return Result.NONE;
		}

		final Widgets widgets = getWidgets();
		if (widgets == null) {
			reset();
			return Result.NONE;
		}

		final Result result = applyOneRow(widgets);
		reset();
		return result;
	}

	public void reset() {
		nativeLayoutRunning = false;
		pluginTwoRows = false;
		clearOneRow();
	}

	private boolean needsTwoRows(Rectangle desired, Widgets widgets) {
		final Rectangle staticBounds = InterfaceBounds.liveBounds(widgets.staticLayer);
		if (staticBounds == null) {
			return false;
		}

		final boolean staticButtonsHit = hitsVisibleChildren(desired, widgets.staticLayer);
		final boolean movableButtonsHit = pluginTwoRows
				? hitsRelativeChildren(desired, staticBounds, movableChildrenOneRow, movableOneRow)
				: hitsVisibleChildren(desired, widgets.movableLayer);
		final Rectangle backgroundBounds = pluginTwoRows && backgroundOneRow != null
				? backgroundOneRow.resolve(staticBounds)
				: InterfaceBounds.liveBounds(widgets.background);
		final Rectangle containerBounds = pluginTwoRows && containerOneRow != null
				? containerOneRow.resolve(staticBounds)
				: InterfaceBounds.liveBounds(widgets.container);

		return !staticButtonsHit
				&& movableButtonsHit
				&& !intersects(desired, backgroundBounds)
				&& !intersects(desired, containerBounds)
				&& !intersects(desired, InterfaceBounds.liveBounds(widgets.mapContainer))
				&& !intersects(desired, InterfaceBounds.liveBounds(widgets.orbs));
	}

	private Result applyTwoRows(Widgets widgets, Rectangle desired) {
		captureOneRow(widgets);
		if (!oneRowKnown) {
			return Result.NONE;
		}

		final int rowHeight = Math.max(1, Math.max(widgets.staticLayer.getHeight(), widgets.movableLayer.getHeight()));
		final int movableX = widgets.staticLayer.getOriginalX();
		final int movableY = widgets.staticLayer.getOriginalY() + rowHeight;
		final int containerY = oneRowContainerY + rowHeight;
		int mutations = 0;
		int revalidates = 0;

		if (widgets.movableLayer.getOriginalX() != movableX || widgets.movableLayer.getOriginalY() != movableY) {
			widgets.movableLayer.setOriginalX(movableX);
			widgets.movableLayer.setOriginalY(movableY);
			mutations++;

			widgets.movableLayer.revalidate();
			revalidates++;
		}

		if (intersects(desired, InterfaceBounds.liveBounds(widgets.movableLayer))) {
			widgets.movableLayer.setOriginalX(oneRowMovableX);
			widgets.movableLayer.setOriginalY(oneRowMovableY);
			mutations++;

			widgets.movableLayer.revalidate();
			revalidates++;
			return new Result(mutations, revalidates);
		}

		if (widgets.container.getOriginalY() != containerY) {
			widgets.container.setOriginalY(containerY);
			mutations++;

			widgets.container.revalidate();
			revalidates++;
		}

		pluginTwoRows = true;
		return new Result(mutations, revalidates);
	}

	private Result applyOneRow(Widgets widgets) {
		int mutations = 0;
		int revalidates = 0;

		if (widgets.movableLayer.getOriginalX() != oneRowMovableX
				|| widgets.movableLayer.getOriginalY() != oneRowMovableY) {
			widgets.movableLayer.setOriginalX(oneRowMovableX);
			widgets.movableLayer.setOriginalY(oneRowMovableY);
			mutations++;

			widgets.movableLayer.revalidate();
			revalidates++;
		}

		if (widgets.container.getOriginalY() != oneRowContainerY) {
			widgets.container.setOriginalY(oneRowContainerY);
			mutations++;

			widgets.container.revalidate();
			revalidates++;
		}

		pluginTwoRows = false;
		return new Result(mutations, revalidates);
	}

	private void captureOneRow(Widgets widgets) {
		final Rectangle staticBounds = InterfaceBounds.liveBounds(widgets.staticLayer);
		final Rectangle movableBounds = InterfaceBounds.liveBounds(widgets.movableLayer);
		if (staticBounds == null || movableBounds == null) {
			return;
		}

		oneRowMovableX = widgets.movableLayer.getOriginalX();
		oneRowMovableY = widgets.movableLayer.getOriginalY();
		oneRowContainerY = widgets.container.getOriginalY();
		movableOneRow = RelativeBounds.capture(staticBounds, movableBounds);
		movableChildrenOneRow = captureRelativeChildren(staticBounds, widgets.movableLayer);

		final Rectangle backgroundBounds = InterfaceBounds.liveBounds(widgets.background);
		backgroundOneRow = backgroundBounds != null
				? RelativeBounds.capture(staticBounds, backgroundBounds)
				: null;

		final Rectangle containerBounds = InterfaceBounds.liveBounds(widgets.container);
		containerOneRow = containerBounds != null
				? RelativeBounds.capture(staticBounds, containerBounds)
				: null;
		oneRowKnown = true;
	}

	private void clearOneRow() {
		oneRowKnown = false;
		movableOneRow = null;
		movableChildrenOneRow = new ArrayList<>();
		backgroundOneRow = null;
		containerOneRow = null;
	}

	private Rectangle desiredBounds(Widget slot, int configuredWidth, int configuredHeight) {
		final Rectangle slotBounds = InterfaceBounds.liveBounds(slot);
		if (slotBounds == null) {
			return null;
		}

		final int anchorX = slotBounds.x;
		final int anchorBottom = slotBounds.y + slotBounds.height;
		final int availableWidth = client.getCanvasWidth() - anchorX;
		final int availableHeight = anchorBottom;
		if (availableWidth <= 0 || availableHeight <= 0) {
			return null;
		}

		final int width = Math.min(configuredWidth, availableWidth);
		final int height = Math.min(configuredHeight, availableHeight);
		return new Rectangle(anchorX, anchorBottom - height, width, height);
	}

	private Widgets getWidgets() {
		if (!isModernLayout()) {
			return null;
		}

		final Widget staticLayer = client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_STATIC_LAYER);
		final Widget movableLayer = client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_MOVABLE_LAYER);
		final Widget container = client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_CONTAINER);
		if (staticLayer == null || movableLayer == null || container == null
				|| staticLayer.isHidden() || movableLayer.isHidden()) {
			return null;
		}

		return new Widgets(
				staticLayer,
				movableLayer,
				client.getWidget(InterfaceID.ToplevelPreEoc.SIDE_BACKGROUND),
				container,
				client.getWidget(InterfaceID.ToplevelPreEoc.MAP_CONTAINER),
				client.getWidget(InterfaceID.ToplevelPreEoc.ORBS));
	}

	private static boolean hitsVisibleChildren(Rectangle desired, Widget parent) {
		final List<Rectangle> children = visibleChildBounds(parent);
		if (children.isEmpty()) {
			return intersects(desired, InterfaceBounds.liveBounds(parent));
		}

		for (Rectangle child : children) {
			if (intersects(desired, child)) {
				return true;
			}
		}

		return false;
	}

	private static boolean hitsRelativeChildren(
			Rectangle desired, Rectangle anchor, List<RelativeBounds> children, RelativeBounds fallback) {
		if (children != null && !children.isEmpty()) {
			for (RelativeBounds child : children) {
				if (intersects(desired, child.resolve(anchor))) {
					return true;
				}
			}

			return false;
		}

		return fallback != null && intersects(desired, fallback.resolve(anchor));
	}

	private static List<RelativeBounds> captureRelativeChildren(Rectangle anchor, Widget parent) {
		final List<RelativeBounds> children = new ArrayList<>();

		captureRelativeChildren(children, anchor, parent != null
				? parent.getStaticChildren()
				: null);
		captureRelativeChildren(children, anchor, parent != null
				? parent.getDynamicChildren()
				: null);
		captureRelativeChildren(children, anchor, parent != null
				? parent.getNestedChildren()
				: null);

		return children;
	}

	private static void captureRelativeChildren(List<RelativeBounds> bounds, Rectangle anchor, Widget[] children) {
		if (children == null) {
			return;
		}

		for (Widget child : children) {
			final Rectangle childBounds = InterfaceBounds.liveBounds(child);
			if (childBounds != null) {
				bounds.add(RelativeBounds.capture(anchor, childBounds));
			}
		}
	}

	private static List<Rectangle> visibleChildBounds(Widget parent) {
		final List<Rectangle> bounds = new ArrayList<>();

		addVisibleChildren(bounds, parent != null
				? parent.getStaticChildren()
				: null);
		addVisibleChildren(bounds, parent != null
				? parent.getDynamicChildren()
				: null);
		addVisibleChildren(bounds, parent != null
				? parent.getNestedChildren()
				: null);

		return bounds;
	}

	private static void addVisibleChildren(List<Rectangle> bounds, Widget[] children) {
		if (children == null) {
			return;
		}

		for (Widget child : children) {
			final Rectangle childBounds = InterfaceBounds.liveBounds(child);
			if (childBounds != null) {
				bounds.add(childBounds);
			}
		}
	}

	private boolean isModernLayout() {
		return client.getTopLevelInterfaceId() == InterfaceID.TOPLEVEL_PRE_EOC;
	}

	private static boolean isTwoRows(Widget staticLayer, Widget movableLayer) {
		return movableLayer.getOriginalY() != staticLayer.getOriginalY();
	}

	private static boolean intersects(Rectangle first, Rectangle second) {
		return first != null && second != null && first.intersects(second);
	}

	private static final class Widgets {
		private final Widget staticLayer;
		private final Widget movableLayer;
		private final Widget background;
		private final Widget container;
		private final Widget mapContainer;
		private final Widget orbs;

		private Widgets(
				Widget staticLayer,
				Widget movableLayer,
				Widget background,
				Widget container,
				Widget mapContainer,
				Widget orbs) {
			this.staticLayer = staticLayer;
			this.movableLayer = movableLayer;
			this.background = background;
			this.container = container;
			this.mapContainer = mapContainer;
			this.orbs = orbs;
		}
	}

	private static final class RelativeBounds {
		private final int x;
		private final int y;
		private final int width;
		private final int height;

		private RelativeBounds(int x, int y, int width, int height) {
			this.x = x;
			this.y = y;
			this.width = width;
			this.height = height;
		}

		private static RelativeBounds capture(Rectangle anchor, Rectangle bounds) {
			return new RelativeBounds(
					bounds.x - anchor.x,
					bounds.y - anchor.y,
					bounds.width,
					bounds.height);
		}

		private Rectangle resolve(Rectangle anchor) {
			return new Rectangle(anchor.x + x, anchor.y + y, width, height);
		}
	}

	public static final class Result {
		private static final Result NONE = new Result(0, 0);

		private final int mutations;
		private final int revalidates;

		private Result(int mutations, int revalidates) {
			this.mutations = mutations;
			this.revalidates = revalidates;
		}

		public int getMutations() {
			return mutations;
		}

		public int getRevalidates() {
			return revalidates;
		}
	}
}

package com.bigboldchat.layout;

import java.awt.Rectangle;

import net.runelite.api.Client;

/*
 * Resolves split-PM width against the interfaces that overlap its own
 * screen position. The configured/inherited width remains the maximum.
 */
final class PrivateChatBounds {
	private static final int MIN_WIDTH = 200;

	private PrivateChatBounds() {
		/*
		 * PRIVATE CHAT BOUNDS
		 */
	}

	static int resolveWidth(Client client, Rectangle surfaceBounds, int desiredWidth) {
		if (client == null || surfaceBounds == null || desiredWidth <= 0) {
			return Math.max(MIN_WIDTH, desiredWidth);
		}

		final InterfaceBounds interfaces = InterfaceBounds.capture(client);
		final Rectangle canvas = interfaces.getCanvas();
		final int anchorX = surfaceBounds.x;
		final int availableWidth = canvas.x + canvas.width - anchorX;
		int effectiveWidth = constrain(desiredWidth, availableWidth);

		/*
		 * This prototype preserves the PM surface's left edge and constrains only
		 * against interfaces to its right. Left-edge preservation is deliberate:
		 * the general symmetric movable-geometry phase will add opposite-edge
		 * ownership for left-side collisions without duplicating that solver here.
		 */
		for (Rectangle obstacle : interfaces.getObstacles()) {
			if (!intersectsVertically(surfaceBounds, obstacle)
					|| obstacle.x <= anchorX
					|| obstacle.x >= anchorX + effectiveWidth) {
				continue;
			}

			effectiveWidth = Math.max(MIN_WIDTH, obstacle.x - anchorX);
		}

		return effectiveWidth;
	}

	private static boolean intersectsVertically(Rectangle surfaceBounds, Rectangle obstacle) {
		final int surfaceHeight = Math.max(1, surfaceBounds.height);
		final int surfaceBottom = surfaceBounds.y + surfaceHeight;
		final int obstacleBottom = obstacle.y + obstacle.height;
		return surfaceBounds.y < obstacleBottom && surfaceBottom > obstacle.y;
	}

	private static int constrain(int desiredWidth, int availableWidth) {
		if (availableWidth <= 0) {
			return Math.max(MIN_WIDTH, desiredWidth);
		}

		return Math.max(MIN_WIDTH, Math.min(desiredWidth, availableWidth));
	}
}

package com.bigboldchat.layout;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;

import com.bigboldchat.chatbox.ChatboxGeometry;

import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;

/**
 * Resolves configured chatbox dimensions against visible interface bounds.
 */
public final class ChatboxBounds {
	private static final int MIN_WIDTH = 200;
	private static final int MIN_HEIGHT = 100;

	private ChatboxBounds() {
		/*
		 * CHATBOX BOUNDS
		 */
	}

	public static Result resolve(Client client, Widget slot, int configuredWidth, int configuredHeight) {
		return resolve(client, slot, configuredWidth, configuredHeight, false);
	}

	public static Result resolve(
			Client client,
			Widget slot,
			int configuredWidth,
			int configuredHeight,
			boolean buttonsHidden) {
		if (client == null || slot == null) {
			return new Result(configuredWidth, configuredHeight, false, false);
		}

		final InterfaceBounds interfaces = InterfaceBounds.capture(client);
		final Rectangle canvas = interfaces.getCanvas();
		final Rectangle slotBounds = slot.getBounds();
		if (slotBounds == null) {
			return new Result(configuredWidth, configuredHeight, false, false);
		}

		final int anchorX = slotBounds.x;
		final int anchorBottom = canvas.y + canvas.height;
		final int availableWidth = canvas.x + canvas.width - anchorX;
		final int availableHeight = anchorBottom - canvas.y;
		final int desiredWidth = constrain(configuredWidth, availableWidth, MIN_WIDTH);
		final int desiredHeight = constrain(configuredHeight, availableHeight, MIN_HEIGHT);

		final Result fitted = fit(
				anchorX, anchorBottom, desiredWidth, desiredHeight, canvas, interfaces.getObstacles());
		final Rectangle presentationBounds = new Rectangle(
				anchorX,
				anchorBottom - fitted.height,
				fitted.width,
				ChatboxGeometry.bodyHeight(fitted.height, buttonsHidden));

		return new Result(
				fitted.width, fitted.height, interfaces.intersectsForeground(presentationBounds), fitted.fallback);
	}

	private static Result fit(
			int anchorX,
			int anchorBottom,
			int desiredWidth,
			int desiredHeight,
			Rectangle canvas,
			List<Rectangle> obstacles) {
		final List<Integer> widths = new ArrayList<>();
		final List<Integer> heights = new ArrayList<>();

		addCandidate(widths, desiredWidth, MIN_WIDTH, desiredWidth);
		addCandidate(widths, ChatboxGeometry.NATIVE_WIDTH, MIN_WIDTH, desiredWidth);
		addCandidate(heights, desiredHeight, MIN_HEIGHT, desiredHeight);
		addCandidate(heights, ChatboxGeometry.NATIVE_SLOT_HEIGHT, MIN_HEIGHT, desiredHeight);

		for (Rectangle obstacle : obstacles) {
			addCandidate(widths, obstacle.x - anchorX, MIN_WIDTH, desiredWidth);
			addCandidate(
					heights, anchorBottom - (obstacle.y + obstacle.height),
					MIN_HEIGHT, desiredHeight);
		}

		Result best = null;
		long bestArea = -1L;
		for (int width : widths) {
			for (int height : heights) {
				final Rectangle candidate = new Rectangle(anchorX, anchorBottom - height, width, height);
				if (!fits(candidate, canvas, obstacles)) {
					continue;
				}

				final long area = (long) width * height;
				if (best == null
						|| area > bestArea
						|| area == bestArea && width > best.width) {
					best = new Result(width, height, false, false);
					bestArea = area;
				}
			}
		}

		if (best != null) {
			return best;
		}

		/*
		 * Preserve the axis that would require the larger proportional
		 * reduction and accept overlap on the constrained axis.
		 * Never shrink both axes when an interface enters native chatbox footprint.
		 */
		return fallback(anchorX, anchorBottom, desiredWidth, desiredHeight, obstacles);
	}

	private static Result fallback(
			int anchorX,
			int anchorBottom,
			int desiredWidth,
			int desiredHeight,
			List<Rectangle> obstacles) {
		final Rectangle desired = new Rectangle(
				anchorX,
				anchorBottom - desiredHeight,
				desiredWidth,
				desiredHeight);
		int widthLoss = 0;
		int heightLoss = 0;

		for (Rectangle obstacle : obstacles) {
			if (!desired.intersects(obstacle)) {
				continue;
			}

			final int widthLimit = obstacle.x - anchorX;
			final int heightLimit = anchorBottom - (obstacle.y + obstacle.height);
			widthLoss = Math.max(widthLoss, requiredLoss(desiredWidth, widthLimit));
			heightLoss = Math.max(heightLoss, requiredLoss(desiredHeight, heightLimit));
		}

		if ((long) heightLoss * desiredWidth <= (long) widthLoss * desiredHeight) {
			return new Result(desiredWidth, Math.min(desiredHeight, MIN_HEIGHT), false, true);
		}

		return new Result(Math.max(MIN_WIDTH, desiredWidth - widthLoss), desiredHeight, false, true);
	}

	private static int requiredLoss(int desiredSize, int limit) {
		if (limit >= desiredSize) {
			return 0;
		}

		if (limit <= 0) {
			return desiredSize;
		}

		return desiredSize - limit;
	}

	private static boolean fits(Rectangle candidate, Rectangle canvas, List<Rectangle> obstacles) {
		if (!canvas.contains(candidate)) {
			return false;
		}

		for (Rectangle obstacle : obstacles) {
			if (candidate.intersects(obstacle)) {
				return false;
			}
		}

		return true;
	}

	private static void addCandidate(List<Integer> candidates, int value, int minimum, int maximum) {
		if (value < minimum || value > maximum || candidates.contains(value)) {
			return;
		}

		candidates.add(value);
	}

	private static int constrain(int configuredSize, int availableSize, int minimumSize) {
		if (availableSize <= 0) {
			return configuredSize;
		}

		return Math.max(minimumSize, Math.min(configuredSize, availableSize));
	}

	public static final class Result {
		private final int width;
		private final int height;
		private final boolean foregroundOverlap;
		private final boolean fallback;

		private Result(int width, int height, boolean foregroundOverlap, boolean fallback) {
			this.width = width;
			this.height = height;
			this.foregroundOverlap = foregroundOverlap;
			this.fallback = fallback;
		}

		public int getWidth() {
			return width;
		}

		public int getHeight() {
			return height;
		}

		public boolean isForegroundOverlap() {
			return foregroundOverlap;
		}

		public boolean isFallback() {
			return fallback;
		}
	}
}

package com.bigboldchat.layout;

import com.bigboldchat.Configurations;

import java.awt.Rectangle;

import com.bigboldchat.overlay.PrivateChatOverlay;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.ui.overlay.OverlayPosition;

/*
 * Owns split-PM external placement and width without replacing RuneScape's
 * font-dependent row construction.
 */
public final class PrivateChatLayout {
	private static final String CONFIG_GROUP = "bigboldchat";
	private static final String WIDTH_KEY = "splitPmWidth";
	private static final String WIDTH_OVERRIDE_KEY = "splitPmWidthOverride";
	private static final String CHATBOX_WIDTH_KEY = "chatboxWidth";
	private static final int MIN_WIDTH = 200;

	private final Client client;
	private final Configurations config;
	private final ConfigManager configManager;
	private final PrivateChatOverlay overlay;

	private Widget forcedHost;
	private Widget sizedHost;
	private int nativeOriginalWidth;
	private int appliedOriginalWidth;
	private boolean nativeWidthCaptured;

	/*
	 * Split-PM width inheritance is explicit state rather than inferred from the
	 * visible numeric value. This lets an inherited value mirror Chatbox Width
	 * while a user-entered value remains independent until Split-PM Width is reset.
	 */
	private boolean widthOverrideInitialized;
	private boolean widthOverridden;

	/*
	 * Width rewrapping changes the visible PM block height. Collision tests must
	 * not feed that newly-wrapped height straight back into the next width solve,
	 * or the PM can alternate between colliding and not colliding every frame.
	 */
	private int stableCollisionHeight;
	private int stableDesiredWidth;

	public PrivateChatLayout(
			Client client,
			Configurations config,
			ConfigManager configManager,
			PrivateChatOverlay overlay) {
		this.client = client;
		this.config = config;
		this.configManager = configManager;
		this.overlay = overlay;
	}

	public Result sync() {
		ensureWidthOverrideInitialized();

		final Widget pmHost = activePmHost();
		final Widget chatSlot = activeChatSlot();
		if (pmHost == null || chatSlot == null) {
			overlay.setNaturalBounds(null);
			restoreNative();
			return Result.NO_CHANGE;
		}

		if (forcedHost != null && forcedHost != pmHost) {
			restoreForcedHost();
		}
		if (sizedHost != null && sizedHost != pmHost) {
			restoreSizedHost();
		}

		final Rectangle contentBounds = visiblePmBounds();
		final int currentOffsetX = pmHost.getRelativeX() - pmHost.getOriginalX();
		final int currentOffsetY = pmHost.getRelativeY() - pmHost.getOriginalY();
		final Rectangle baseContentBounds = contentBounds == null
				? null
				: translated(contentBounds, -currentOffsetX, -currentOffsetY);

		/*
		 * RuneLite's BOTTOM_LEFT snap corner is the green anchor above the
		 * chatbox. When split PM is snapped there, follow the chatbox translation
		 * directly rather than deriving Y from a reflowing overlay rectangle.
		 */
		final boolean chatboxAnchored = overlay.getPreferredPosition() == OverlayPosition.BOTTOM_LEFT;
		final Offset target = overlay.isManuallyPositioned()
				&& !chatboxAnchored
				&& baseContentBounds != null
				? manualOffset(baseContentBounds)
				: chatboxOffset(chatSlot);

		final Rectangle expectedContentBounds = baseContentBounds == null
				? null
				: translated(baseContentBounds, target.x, target.y);
		final int desiredWidth = desiredWidth(chatSlot);
		final Rectangle collisionBounds = stableCollisionBounds(pmHost, expectedContentBounds, desiredWidth);
		final int effectiveWidth = collisionBounds == null
				? desiredWidth
				: PrivateChatBounds.resolveWidth(client, collisionBounds, desiredWidth);
		final boolean widthChanged = setEffectiveWidth(pmHost, effectiveWidth);

		if (expectedContentBounds != null && effectiveWidth >= desiredWidth) {
			stableCollisionHeight = Math.max(1, expectedContentBounds.height);
			stableDesiredWidth = desiredWidth;
		}

		if (widthChanged) {
			final Widget pmChat = client.getWidget(InterfaceID.PM_CHAT, 0);
			if (pmChat != null) {
				pmChat.revalidate();
			}
		}

		/*
		 * Width changes revalidate PM_CONTAINER before native rows are rebuilt. That
		 * revalidation recalculates the host's relative position and can temporarily
		 * discard our forced placement. Applying the external translation last keeps
		 * the host stable while refreshChat() reconstructs and rewraps its children.
		 */
		applyOffset(pmHost, target.x, target.y);

		/*
		 * The overlay hitbox represents the effective PM surface width. Visible
		 * row widgets contribute only the vertical span so malformed/stale text
		 * cannot create an enormous horizontal drag region.
		 */
		final Rectangle overlayBounds = expectedContentBounds == null
				? null
				: new Rectangle(
						expectedContentBounds.x,
						expectedContentBounds.y,
						effectiveWidth,
						expectedContentBounds.height);
		overlay.setNaturalBounds(overlayBounds);

		return widthChanged
				? Result.WIDTH_CHANGED
				: Result.NO_CHANGE;
	}

	public void restoreNative() {
		restoreForcedHost();
		restoreSizedHost();
		stableCollisionHeight = 0;
		stableDesiredWidth = 0;
	}

	public void onConfigChanged(ConfigChanged event) {
		if (event == null || !CONFIG_GROUP.equals(event.getGroup())) {
			return;
		}

		ensureWidthOverrideInitialized();

		if (CHATBOX_WIDTH_KEY.equals(event.getKey())) {
			if (!widthOverridden) {
				syncInheritedWidthConfiguration();
			}
			return;
		}

		if (!WIDTH_KEY.equals(event.getKey())) {
			return;
		}

		final String storedWidth = configManager.getConfiguration(CONFIG_GROUP, WIDTH_KEY);
		if (storedWidth == null) {
			setWidthOverridden(false);
			syncInheritedWidthConfiguration();
			return;
		}

		/*
		 * Programmatic mirroring writes the same configured width as Chatbox Width
		 * and must not turn inheritance into an override. Once an override is
		 * already active, even matching Chatbox Width remains intentionally manual.
		 */
		if (!widthOverridden && parseWidth(storedWidth) == config.chatboxWidth()) {
			return;
		}

		setWidthOverridden(true);
	}

	private int desiredWidth(Widget chatSlot) {
		if (widthOverridden) {
			return Math.max(MIN_WIDTH, config.splitPmWidth());
		}

		/*
		 * Inherited mode mirrors the chatbox's live effective width, not merely the
		 * configured maximum. This keeps an anchored PM surface synchronized when
		 * the chatbox itself is temporarily narrowed by interface collision.
		 */
		return Math.max(MIN_WIDTH, chatSlot.getWidth());
	}

	private void ensureWidthOverrideInitialized() {
		if (widthOverrideInitialized) {
			return;
		}

		final String storedOverride = configManager.getConfiguration(CONFIG_GROUP, WIDTH_OVERRIDE_KEY);
		widthOverridden = storedOverride != null && Boolean.parseBoolean(storedOverride);
		widthOverrideInitialized = true;

		/*
		 * Older Phase-5 prototypes could leave splitPmWidth stored while it was
		 * intended to inherit. Without the explicit marker introduced here, treat
		 * that state as inherited and mirror the configured Chatbox Width.
		 */
		if (storedOverride == null) {
			setWidthOverridden(false);
			syncInheritedWidthConfiguration();
		}
	}

	private void setWidthOverridden(boolean overridden) {
		widthOverridden = overridden;
		configManager.setConfiguration(CONFIG_GROUP, WIDTH_OVERRIDE_KEY, overridden);
	}

	private void syncInheritedWidthConfiguration() {
		final int chatboxWidth = config.chatboxWidth();
		final String storedWidth = configManager.getConfiguration(CONFIG_GROUP, WIDTH_KEY);
		if (parseWidth(storedWidth) == chatboxWidth) {
			return;
		}

		configManager.setConfiguration(CONFIG_GROUP, WIDTH_KEY, chatboxWidth);
	}

	private static int parseWidth(String value) {
		if (value == null || value.isEmpty()) {
			return -1;
		}

		try {
			return Integer.parseInt(value);
		} catch (NumberFormatException ignored) {
			return -1;
		}
	}

	private Rectangle stableCollisionBounds(
			Widget pmHost,
			Rectangle expectedContentBounds,
			int desiredWidth) {
		if (pmHost == null || expectedContentBounds == null) {
			return null;
		}

		final int currentHeight = Math.max(1, expectedContentBounds.height);
		if (stableCollisionHeight <= 0
				|| stableDesiredWidth != desiredWidth
				|| pmHost.getWidth() >= desiredWidth) {
			stableCollisionHeight = currentHeight;
			stableDesiredWidth = desiredWidth;
		}

		/*
		 * Width wrapping may make the visible PM block taller. Use the last
		 * unconstrained height while solving collision so our own rewrap cannot
		 * make an obstacle disappear on the next frame and create a width/position
		 * oscillation. Bottom-left chatbox anchoring preserves the PM's lower edge;
		 * freely detached overlays preserve their top edge.
		 */
		final boolean bottomAnchored = !overlay.isManuallyPositioned()
				|| overlay.getPreferredPosition() == OverlayPosition.BOTTOM_LEFT;
		final int y = bottomAnchored
				? expectedContentBounds.y + expectedContentBounds.height - stableCollisionHeight
				: expectedContentBounds.y;

		return new Rectangle(
				expectedContentBounds.x,
				y,
				desiredWidth,
				stableCollisionHeight);
	}

	private Offset chatboxOffset(Widget chatSlot) {
		final Rectangle bounds = chatSlot.getBounds();
		if (bounds == null) {
			return Offset.ZERO;
		}

		/*
		 * Use the chatbox bottom-left corner to isolate external movement from
		 * ChatXL's temporary width/height changes. A normal resizable chatbox ends
		 * at the canvas bottom-left regardless of its current constrained size.
		 */
		return new Offset(
				bounds.x,
				bounds.y + bounds.height - client.getCanvasHeight());
	}

	private Offset manualOffset(Rectangle baseContentBounds) {
		final Rectangle overlayBounds = overlay.getBounds();
		return new Offset(
				overlayBounds.x - baseContentBounds.x,
				overlayBounds.y - baseContentBounds.y);
	}

	private void applyOffset(Widget pmHost, int offsetX, int offsetY) {
		if (forcedHost != null && forcedHost != pmHost) {
			restoreForcedHost();
		}

		if (offsetX == 0 && offsetY == 0 && !overlay.isManuallyPositioned()) {
			restoreForcedHost();
			return;
		}

		final int targetX = pmHost.getOriginalX() + offsetX;
		final int targetY = pmHost.getOriginalY() + offsetY;
		if (forcedHost == pmHost
				&& pmHost.getRelativeX() == targetX
				&& pmHost.getRelativeY() == targetY) {
			return;
		}

		pmHost.setForcedPosition(targetX, targetY);
		forcedHost = pmHost;
	}

	private boolean setEffectiveWidth(Widget pmHost, int width) {
		if (pmHost == null || width <= 0 || pmHost.getWidth() == width) {
			return false;
		}

		captureNativeWidth(pmHost);
		final int targetOriginalWidth;
		switch (pmHost.getWidthMode()) {
			case WidgetSizeMode.ABSOLUTE:
				targetOriginalWidth = width;
				break;
			case WidgetSizeMode.MINUS:
				final Widget parent = pmHost.getParent();
				if (parent == null) {
					return false;
				}

				targetOriginalWidth = Math.max(0, parent.getWidth() - width);
				break;
			case WidgetSizeMode.ABSOLUTE_16384THS:
				final Widget proportionalParent = pmHost.getParent();
				if (proportionalParent == null || proportionalParent.getWidth() <= 0) {
					return false;
				}

				targetOriginalWidth = Math.max(0, Math.min(16384,
						(int) Math.round(width * 16384.0 / proportionalParent.getWidth())));
				break;
			default:
				return false;
		}

		if (pmHost.getOriginalWidth() == targetOriginalWidth) {
			return false;
		}

		if (nativeWidthCaptured && pmHost.getOriginalWidth() != appliedOriginalWidth) {
			nativeOriginalWidth = pmHost.getOriginalWidth();
		}

		pmHost.setOriginalWidth(targetOriginalWidth);
		pmHost.revalidate();
		appliedOriginalWidth = targetOriginalWidth;
		return true;
	}

	private void captureNativeWidth(Widget pmHost) {
		if (sizedHost == pmHost && nativeWidthCaptured) {
			return;
		}

		if (sizedHost != null && sizedHost != pmHost) {
			restoreSizedHost();
		}

		sizedHost = pmHost;
		nativeOriginalWidth = pmHost.getOriginalWidth();
		appliedOriginalWidth = nativeOriginalWidth;
		nativeWidthCaptured = true;
	}

	private void restoreForcedHost() {
		if (forcedHost == null) {
			return;
		}

		forcedHost.setForcedPosition(-1, -1);
		forcedHost.revalidate();
		forcedHost = null;
	}

	private void restoreSizedHost() {
		if (sizedHost == null || !nativeWidthCaptured) {
			return;
		}

		if (sizedHost.getOriginalWidth() == appliedOriginalWidth
				&& sizedHost.getOriginalWidth() != nativeOriginalWidth) {
			sizedHost.setOriginalWidth(nativeOriginalWidth);
			sizedHost.revalidate();
		}

		sizedHost = null;
		nativeOriginalWidth = 0;
		appliedOriginalWidth = 0;
		nativeWidthCaptured = false;
	}

	private Rectangle visiblePmBounds() {
		final Widget pmChat = client.getWidget(InterfaceID.PM_CHAT, 0);
		if (pmChat == null || pmChat.isHidden()) {
			return null;
		}

		Rectangle bounds = null;
		for (Widget child : pmChat.getDynamicChildren()) {
			bounds = union(bounds, visibleBounds(child));
		}

		bounds = union(bounds, visibleBounds(client.getWidget(InterfaceID.PmChat.PM1)));
		bounds = union(bounds, visibleBounds(client.getWidget(InterfaceID.PmChat.PM2)));
		bounds = union(bounds, visibleBounds(client.getWidget(InterfaceID.PmChat.PM3)));
		bounds = union(bounds, visibleBounds(client.getWidget(InterfaceID.PmChat.PM4)));
		bounds = union(bounds, visibleBounds(client.getWidget(InterfaceID.PmChat.PM5)));
		return bounds;
	}

	private Widget activeChatSlot() {
		final int topLevel = client.getTopLevelInterfaceId();
		if (topLevel == InterfaceID.TOPLEVEL_OSRS_STRETCH) {
			return client.getWidget(InterfaceID.ToplevelOsrsStretch.CHAT_CONTAINER);
		}
		if (topLevel == InterfaceID.TOPLEVEL_PRE_EOC) {
			return client.getWidget(InterfaceID.ToplevelPreEoc.CHAT_CONTAINER);
		}
		return null;
	}

	private Widget activePmHost() {
		final int topLevel = client.getTopLevelInterfaceId();
		if (topLevel == InterfaceID.TOPLEVEL_OSRS_STRETCH) {
			return client.getWidget(InterfaceID.ToplevelOsrsStretch.PM_CONTAINER);
		}
		if (topLevel == InterfaceID.TOPLEVEL_PRE_EOC) {
			return client.getWidget(InterfaceID.ToplevelPreEoc.PM_CONTAINER);
		}
		return null;
	}

	private static Rectangle visibleBounds(Widget widget) {
		if (widget == null || widget.isHidden() || widget.getWidth() <= 0 || widget.getHeight() <= 0) {
			return null;
		}

		final Rectangle bounds = widget.getBounds();
		return bounds == null || bounds.isEmpty()
				? null
				: new Rectangle(bounds);
	}

	private static Rectangle union(Rectangle first, Rectangle second) {
		if (second == null || second.isEmpty()) {
			return first;
		}
		if (first == null) {
			return new Rectangle(second);
		}

		first.add(second);
		return first;
	}

	private static Rectangle translated(Rectangle bounds, int x, int y) {
		final Rectangle translated = new Rectangle(bounds);
		translated.translate(x, y);
		return translated;
	}

	public static final class Result {
		private static final Result NO_CHANGE = new Result(false);
		private static final Result WIDTH_CHANGED = new Result(true);

		private final boolean widthChanged;

		private Result(boolean widthChanged) {
			this.widthChanged = widthChanged;
		}

		public boolean isWidthChanged() {
			return widthChanged;
		}
	}

	private static final class Offset {
		private static final Offset ZERO = new Offset(0, 0);
		private final int x;
		private final int y;

		private Offset(int x, int y) {
			this.x = x;
			this.y = y;
		}
	}
}

package com.bigboldchat.fonts;

import com.bigboldchat.config.ChatFont;

public final class Verdana13 implements ChatFontProfile {
	private static final int LINE_HEIGHT_ADJUSTMENT = 0;
	private static final int ROW_Y_OFFSET = 0;

	private static final int PRIVATE_CHAT_GAP = -2;

	private static final int CHANNEL_NAME_Y_OFFSET = 0;
	private static final int CHANNEL_RANK_ICON_Y_OFFSET = -1;
	private static final int CHANNEL_ACCOUNT_BUILD_ICON_SPACING = 0;
	private static final int CHANNEL_USERNAME_Y_OFFSET = 0;
	private static final int CHANNEL_TEXT_Y_OFFSET = 0;

	private static final int FRIENDS_CHAT_PREFIX_Y_OFFSET = 0;
	private static final int FRIENDS_CHAT_TEXT_Y_OFFSET = 0;
	private static final int FRIENDS_CHAT_PLAYER_ICON_SPACING = 1;

	private static final int RANK_ICON_RIGHT_ADJUSTMENT = 1;
	private static final int RANK_ICON_SIZE_ADJUSTMENT = 0;

	private static final int ACCOUNT_BUILD_ICON_PADDING = 0;

	@Override
	public ChatFont getChatFont() {
		return ChatFont.VERDANA_13;
	}

	@Override
	public int getLineHeightAdjustment() {
		return LINE_HEIGHT_ADJUSTMENT;
	}

	@Override
	public int getRowYOffset() {
		return ROW_Y_OFFSET;
	}

	@Override
	public int getPrivateChatGap() {
		return PRIVATE_CHAT_GAP;
	}

	@Override
	public int getChannelNameYOffset() { return CHANNEL_NAME_Y_OFFSET; }

	@Override
	public int getChannelRankIconYOffset() { return CHANNEL_RANK_ICON_Y_OFFSET; }

	@Override
	public int getChannelAccountBuildIconSpacing() { return CHANNEL_ACCOUNT_BUILD_ICON_SPACING; }

	@Override
	public int getChannelUsernameYOffset() { return CHANNEL_USERNAME_Y_OFFSET; }

