package com.bigboldchat;

import com.bigboldchat.config.ChatFont;

import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup("bigboldchat")
public interface Configurations extends Config {
	/**
	 *  CHAT BOX
	 */
	@ConfigSection(
			name = "Chatbox",
			description = "Modify the Chatbox in game layouts.",
			position = 0
	)
	String chatBoxSection = "chatBox";

	@ConfigItem(
			keyName = "chatFont",
			name = "Font",
			description = "Font used for chatbox and private-message text.",
			position = 0,
			section = chatBoxSection
	)
	default ChatFont chatFont() {
		return ChatFont.PLAIN_12;
	}

	@Range(min = 200, max = 8192)
	@Units(Units.PIXELS)
	@ConfigItem(
			keyName = "chatboxWidth",
			name = "Chatbox Width",
			description = "Width of the chatbox.",
			position = 1,
			section = chatBoxSection
	)
	default int chatboxWidth() {
		return 519;
	}

	@Range(min = 100, max = 8192)
	@Units(Units.PIXELS)
	@ConfigItem(
			keyName = "chatboxHeight",
			name = "Chatbox Height",
			description = "Height of the chatbox.",
			position = 2,
			section = chatBoxSection
	)
	default int chatboxHeight() {
		return 165;
	}

	@Range(min = 200, max = 8192)
	@Units(Units.PIXELS)
	@ConfigItem(
			keyName = "splitPmWidth",
			name = "Split-PM Width",
			description = "Maximum width of split private chat. Follows the live chatbox width until overridden.",
			position = 3,
			section = chatBoxSection
	)
	default int splitPmWidth() {
		/*
		 * Keep the visible default synchronized with Chatbox Width. ConfigManager
		 * supplies a stored split-PM value instead once the user explicitly
		 * overrides this item; resetting it returns to inherited live width.
		 */
		return chatboxWidth();
	}

	@ConfigItem(
			keyName = "hideChatboxButtons",
			name = "Hide Chatbox Buttons",
			description = "Hide the chatbox button row.",
			position = 4,
			section = chatBoxSection
	)
	default boolean hideChatboxButtons() {
		return false;
	}

	@ConfigItem(
			keyName = "hideChatboxHotkey",
			name = "Hide Chatbox Hotkey",
			description = "Toggle the chatbox body between hidden and visible.",
			position = 5,
			section = chatBoxSection
	)
	default Keybind hideChatboxHotkey() {
		return new Keybind(KeyEvent.VK_C, InputEvent.ALT_DOWN_MASK);
	}

	@ConfigItem(
			keyName = "clearChatHotkey",
			name = "Clear Chat Hotkey",
			description = "Clear all chat messages.<br>You can also type ::clear or ::cls.",
			position = 6,
			section = chatBoxSection
	)
	default Keybind clearChatHotkey() {
		return new Keybind(KeyEvent.VK_X, InputEvent.ALT_DOWN_MASK);
	}
}
